:root {
  --bg: #f6f7f9;
  --surface: #ffffff;
  --surface-soft: #f0f4f5;
  --surface-warm: #fff8eb;
  --line: #d8dee4;
  --line-strong: #b7c3c8;
  --text: #162026;
  --border: var(--line);
  --ink: var(--text);
  --muted: #68747d;
  --accent: #087f8c;
  --accent-dark: #075f69;
  --gold: #c98214;
  --rose: #b2456e;
  --green: #287d4b;
  --blue: #335c81;
  --danger: #a83f39;
  --shadow: 0 18px 48px rgba(19, 37, 45, 0.12);
  --radius: 8px;
  color-scheme: light;
  font-family:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
}


/* Persisted audit findings */
.audit-finding-register {
  display: grid;
  gap: 16px;
  padding: 20px;
  border: 1px solid var(--line, #d8e2e8);
  border-radius: 8px;
  background: #fff;
}

.audit-finding-register .audit-execution-section-head p {
  margin: 6px 0 0;
  color: var(--muted, #667783);
}

.audit-finding-register-list {
  display: grid;
  gap: 10px;
  min-width: 0;
}

.audit-finding-record {
  display: grid;
  grid-template-columns: minmax(260px, 1.8fr) minmax(120px, .7fr) minmax(150px, .8fr) minmax(140px, .7fr) minmax(150px, .8fr) auto;
  gap: 12px;
  align-items: end;
  min-width: 0;
  padding: 14px;
  border: 1px solid var(--line, #d8e2e8);
  border-left: 3px solid #16889a;
  border-radius: 8px;
  background: #fff;
}

.audit-finding-record.hoch,
.audit-finding-record.kritisch {
  border-left-color: #c54747;
}

.audit-finding-record-copy {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.audit-finding-record-copy span,
.audit-finding-record label > span {
  color: var(--muted, #667783);
  font-size: 12px;
  font-weight: 700;
}

.audit-finding-record-copy strong,
.audit-finding-record-copy small {
  overflow-wrap: anywhere;
}

.audit-finding-record label {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.audit-finding-record input,
.audit-finding-record select {
  width: 100%;
  min-width: 0;
}

.audit-finding-record-actions {
  display: flex;
  gap: 8px;
  align-items: center;
  justify-content: flex-end;
}

@media (max-width: 1280px) {
  .audit-finding-record {
    grid-template-columns: minmax(240px, 1.5fr) repeat(2, minmax(140px, .8fr));
  }

  .audit-finding-record-actions {
    justify-content: flex-start;
  }
}

@media (max-width: 760px) {
  .audit-finding-register {
    padding: 14px;
  }

  .audit-finding-record {
    grid-template-columns: minmax(0, 1fr);
  }

  .audit-finding-record-actions {
    flex-wrap: wrap;
  }
}

/* Workspace concurrency: visible, recoverable and safe on every module. */
.workspace-conflict-banner {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  gap: 16px;
  align-items: center;
  margin: 0 0 18px;
  padding: 16px 18px;
  border: 1px solid #e4b56d;
  border-left: 4px solid #b86a13;
  border-radius: var(--sfm-radius-md, 6px);
  background: #fff9ed;
  color: var(--sfm-text-strong, #10243a);
  box-shadow: var(--sfm-shadow-xs, 0 1px 2px rgba(16, 36, 58, 0.08));
}

.workspace-conflict-icon {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #b86a13;
  color: #ffffff;
  font-size: 20px;
  font-weight: 800;
}

.workspace-conflict-copy {
  min-width: 0;
}

.workspace-conflict-copy .eyebrow {
  color: #8a4c08;
}

.workspace-conflict-copy h3,
.workspace-conflict-copy p {
  margin: 0;
}

.workspace-conflict-copy h3 {
  margin-top: 2px;
  font-size: 16px;
  line-height: 1.35;
}

.workspace-conflict-copy p {
  margin-top: 4px;
  color: var(--sfm-muted, #607286);
  font-size: 13px;
  line-height: 1.45;
}

.workspace-conflict-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.workspace-conflict-comparison {
  margin: 0 0 18px;
  padding: 18px;
  border: 1px solid #e4b56d;
  border-radius: var(--sfm-radius-md, 6px);
  background: #ffffff;
  box-shadow: var(--sfm-shadow-xs, 0 1px 2px rgba(16, 36, 58, 0.08));
}

.workspace-conflict-comparison-head,
.workspace-conflict-comparison-footer {
  display: flex;
  gap: 16px;
  align-items: flex-start;
  justify-content: space-between;
}

.workspace-conflict-comparison-head h3,
.workspace-conflict-comparison-head p,
.workspace-conflict-comparison-footer p {
  margin: 0;
}

.workspace-conflict-comparison-head h3 {
  margin-top: 2px;
  font-size: 18px;
}

.workspace-conflict-comparison-head p,
.workspace-conflict-comparison-footer p {
  margin-top: 5px;
  color: var(--sfm-muted, #607286);
  font-size: 13px;
  line-height: 1.45;
}

.workspace-conflict-comparison-list {
  display: grid;
  gap: 8px;
  margin-top: 16px;
}

.workspace-conflict-comparison-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(230px, 310px);
  gap: 16px;
  align-items: center;
  padding: 12px 14px;
  border: 1px solid var(--sfm-border, #d8dee4);
  border-radius: var(--sfm-radius-sm, 4px);
  background: #f9fbfc;
}

.workspace-conflict-comparison-row > span {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.workspace-conflict-comparison-row small {
  color: var(--sfm-muted, #607286);
  line-height: 1.4;
}

.workspace-conflict-comparison-row select {
  width: 100%;
  min-width: 0;
}

.workspace-conflict-comparison-footer {
  align-items: center;
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px solid var(--sfm-border, #d8dee4);
}

.workspace-connectivity-banner {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  gap: 16px;
  align-items: center;
  margin: 0 0 18px;
  padding: 16px 18px;
  border: 1px solid #9bc8d2;
  border-left: 4px solid var(--accent, #087f8c);
  border-radius: var(--sfm-radius-md, 6px);
  background: #eef8fa;
  color: var(--sfm-text-strong, #10243a);
  box-shadow: var(--sfm-shadow-xs, 0 1px 2px rgba(16, 36, 58, 0.08));
}

.workspace-connectivity-icon {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--accent, #087f8c);
  color: #ffffff;
  font-size: 18px;
  font-weight: 800;
}

.workspace-connectivity-copy {
  min-width: 0;
}

.workspace-connectivity-copy h3,
.workspace-connectivity-copy p {
  margin: 0;
}

.workspace-connectivity-copy h3 {
  margin-top: 2px;
  font-size: 16px;
  line-height: 1.35;
}

.workspace-connectivity-copy p {
  margin-top: 4px;
  color: var(--sfm-muted, #607286);
  font-size: 13px;
  line-height: 1.45;
}

.session-expired-banner {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) minmax(520px, 1.35fr);
  gap: 20px;
  align-items: end;
  margin: 0 0 18px;
  padding: 18px;
  border: 1px solid #e4b56d;
  border-left: 4px solid #b86a13;
  border-radius: var(--sfm-radius-md, 6px);
  background: #fff9ed;
  color: var(--sfm-text-strong, #10243a);
  box-shadow: var(--sfm-shadow-xs, 0 1px 2px rgba(16, 36, 58, 0.08));
}

.session-expired-copy h3,
.session-expired-copy p {
  margin: 0;
}

.session-expired-copy h3 {
  margin-top: 2px;
  font-size: 18px;
  line-height: 1.35;
}

.session-expired-copy p {
  margin-top: 5px;
  color: var(--sfm-muted, #607286);
  font-size: 13px;
  line-height: 1.45;
}

.session-reauth-form {
  display: grid;
  grid-template-columns: minmax(130px, 0.9fr) minmax(150px, 1fr) minmax(110px, 0.7fr) auto;
  gap: 10px;
  align-items: end;
  min-width: 0;
}

.session-reauth-form label {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.session-reauth-form label span {
  color: var(--sfm-muted, #607286);
  font-size: 11px;
  font-weight: 800;
}

.session-reauth-form input,
.session-reauth-form button {
  width: 100%;
  min-width: 0;
}

.remote-update-banner {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  margin: 0 0 18px;
  padding: 16px 18px;
  border: 1px solid #9bc8d2;
  border-left: 4px solid var(--accent, #087f8c);
  border-radius: var(--sfm-radius-md, 6px);
  background: #f2fafb;
  color: var(--sfm-text-strong, #10243a);
  box-shadow: var(--sfm-shadow-xs, 0 1px 2px rgba(16, 36, 58, 0.08));
}

.remote-update-banner h3,
.remote-update-banner p {
  margin: 0;
}

.remote-update-banner h3 {
  margin-top: 2px;
  font-size: 16px;
  line-height: 1.35;
}

.remote-update-banner p {
  margin-top: 4px;
  color: var(--sfm-muted, #607286);
  font-size: 13px;
  line-height: 1.45;
}

@media (max-width: 900px) {
  .workspace-conflict-banner,
  .workspace-connectivity-banner {
    grid-template-columns: 42px minmax(0, 1fr);
  }

  .workspace-conflict-actions {
    grid-column: 1 / -1;
    justify-content: stretch;
  }

  .workspace-conflict-actions button {
    flex: 1 1 220px;
  }

  .workspace-conflict-comparison-row {
    grid-template-columns: 1fr;
  }

  .workspace-conflict-comparison-head,
  .workspace-conflict-comparison-footer {
    display: grid;
    grid-template-columns: 1fr;
  }

  .workspace-connectivity-banner > button {
    grid-column: 1 / -1;
    width: 100%;
  }

  .session-expired-banner {
    grid-template-columns: 1fr;
  }

  .remote-update-banner {
    grid-template-columns: 1fr;
  }

  .session-reauth-form {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 560px) {
  .workspace-conflict-banner,
  .workspace-connectivity-banner {
    grid-template-columns: 1fr;
    padding: 14px;
  }

  .workspace-conflict-actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .workspace-conflict-actions button {
    width: 100%;
  }

  .workspace-conflict-comparison,
  .workspace-conflict-comparison-row {
    padding: 14px;
  }

  .workspace-conflict-comparison-head button,
  .workspace-conflict-comparison-footer button {
    width: 100%;
  }

  .session-expired-banner,
  .session-reauth-form {
    grid-template-columns: 1fr;
  }

  .remote-update-banner button {
    width: 100%;
  }
}

* {
  box-sizing: border-box;
}

html,
body {
  min-height: 100%;
  overflow-x: hidden;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  cursor: pointer;
}

.app-shell {
  display: grid;
  grid-template-columns: 286px minmax(0, 1fr);
  width: 100%;
  max-width: 100vw;
  min-height: 100vh;
}

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 24px;
  padding: 22px;
  background: #172327;
  color: #f8fbfc;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
}

.brand {
  display: grid;
  grid-template-columns: 46px 1fr;
  align-items: center;
  gap: 12px;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: var(--radius);
  background: #f7c873;
  color: #172327;
  font-weight: 800;
}

.brand h1,
.topbar h2 {
  margin: 0;
  letter-spacing: 0;
}

.brand h1 {
  font-size: 18px;
}

.brand p,
.knowledge-card p {
  margin: 4px 0 0;
  color: rgba(248, 251, 252, 0.68);
  line-height: 1.45;
  font-size: 13px;
}

.main-nav {
  display: grid;
  gap: 6px;
}

.nav-button {
  display: grid;
  grid-template-columns: 28px 1fr auto;
  align-items: center;
  width: 100%;
  min-height: 42px;
  padding: 9px 10px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  background: transparent;
  color: rgba(248, 251, 252, 0.78);
  text-align: left;
}

.nav-button:hover,
.nav-button.active {
  background: rgba(255, 255, 255, 0.09);
  border-color: rgba(255, 255, 255, 0.12);
  color: #ffffff;
}

.nav-icon {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.1);
  font-size: 12px;
  font-weight: 800;
}

.nav-count {
  min-width: 26px;
  padding: 2px 7px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.11);
  color: rgba(248, 251, 252, 0.72);
  text-align: center;
  font-size: 12px;
}

.knowledge-card {
  margin-top: auto;
  padding: 14px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.06);
}

.eyebrow {
  display: block;
  margin-bottom: 5px;
  color: var(--accent-dark);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: uppercase;
}

.sidebar .eyebrow {
  color: #f7c873;
}

.main {
  display: flex;
  min-width: 0;
  max-width: 100%;
  flex-direction: column;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  min-height: 86px;
  padding: 20px 28px;
  border-bottom: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.86);
  backdrop-filter: blur(10px);
  position: sticky;
  top: 0;
  z-index: 5;
}

.topbar h2 {
  font-size: 27px;
}

.top-actions,
.action-row,
.inline-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}

.icon-button,
.primary-button,
.quiet-button,
.danger-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 38px;
  padding: 8px 12px;
  border-radius: var(--radius);
  border: 1px solid var(--line-strong);
  background: var(--surface);
  color: var(--text);
  font-weight: 700;
}

.primary-button {
  border-color: var(--accent);
  background: var(--accent);
  color: #ffffff;
}

.primary-button:hover {
  background: var(--accent-dark);
}

.quiet-button:hover,
.icon-button:hover {
  border-color: var(--accent);
  color: var(--accent-dark);
}

.icon-button.active {
  border-color: var(--accent);
  background: #eef9fa;
  color: var(--accent-dark);
}

.primary-button:disabled,
.quiet-button:disabled,
.icon-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.danger-button {
  border-color: rgba(168, 63, 57, 0.35);
  color: var(--danger);
}

.file-import input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}

.view {
  min-width: 0;
  max-width: 100%;
  padding: 26px 28px 42px;
}

.dashboard-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(310px, 0.65fr);
  gap: 18px;
}

.panel,
.metric-card,
.table-panel,
.requirement-panel,
.source-panel {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: 0 8px 26px rgba(19, 37, 45, 0.05);
}

.panel {
  padding: 18px;
}

.panel-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 15px;
}

.panel-header h3,
.table-panel h3,
.requirement-panel h3 {
  margin: 0;
  font-size: 18px;
  letter-spacing: 0;
}

.panel-header p {
  margin: 5px 0 0;
  color: var(--muted);
  line-height: 1.5;
}

.customer-guide-panel {
  margin-bottom: 18px;
  border-color: rgba(11, 127, 141, 0.28);
  background:
    radial-gradient(circle at top right, rgba(118, 102, 255, 0.08), transparent 32%),
    linear-gradient(135deg, #ffffff 0%, #f5fafb 100%);
}

.customer-guide-main {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(150px, 0.24fr);
  gap: 18px;
  align-items: start;
}

.customer-guide-main h3 {
  margin: 0;
  font-size: 20px;
}

.customer-guide-main p {
  margin: 6px 0 0;
  color: var(--muted);
  line-height: 1.5;
}

.customer-guide-progress {
  display: grid;
  gap: 6px;
  min-height: 76px;
  padding: 11px 12px;
  border: 1px solid rgba(204, 214, 224, 0.9);
  border-radius: var(--radius);
  background: #ffffff;
}

.customer-guide-progress strong,
.customer-guide-progress span {
  display: block;
}

.customer-guide-progress strong {
  font-size: 22px;
  line-height: 1;
}

.customer-guide-progress span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.customer-guide-progress div {
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: #e8eff2;
}

.customer-guide-progress i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--accent), #7468ff);
}

.customer-guide-step {
  display: grid;
  gap: 6px;
  margin-top: 13px;
  padding: 13px;
  border: 1px solid rgba(216, 222, 228, 0.92);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.82);
}

.customer-guide-step span {
  color: var(--accent-dark);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.customer-guide-step strong {
  font-size: 15px;
  line-height: 1.35;
}

.customer-guide-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 13px;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 18px;
}

.metric-card {
  padding: 15px;
}

.metric-card span {
  display: block;
  color: var(--muted);
  font-size: 13px;
  font-weight: 700;
}

.metric-card strong {
  display: block;
  margin-top: 8px;
  font-size: 30px;
}

.metric-card small {
  display: block;
  margin-top: 6px;
  color: var(--muted);
}

.status-strip {
  display: grid;
  grid-template-columns: 1.1fr 1fr 0.9fr;
  gap: 12px;
}

.status-block {
  min-height: 116px;
  padding: 15px;
  border-radius: var(--radius);
  background: var(--surface-soft);
}

.status-block:nth-child(2) {
  background: #eff7f4;
}

.status-block:nth-child(3) {
  background: var(--surface-warm);
}

.status-block b {
  display: block;
  margin-bottom: 9px;
}

.progress {
  height: 10px;
  overflow: hidden;
  border-radius: 999px;
  background: #dce4e8;
}

.progress span {
  display: block;
  height: 100%;
  border-radius: 999px;
  background: var(--accent);
}

.upload-zone {
  display: grid;
  place-items: center;
  min-height: 180px;
  padding: 22px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius);
  background: #fbfcfd;
  text-align: center;
}

.upload-zone.dragover {
  border-color: var(--accent);
  background: #eef9fa;
}

.upload-zone strong {
  display: block;
  margin-bottom: 7px;
  font-size: 17px;
}

.upload-zone p,
.muted {
  color: var(--muted);
}

.upload-zone input {
  display: none;
}

.split-layout {
  display: grid;
  grid-template-columns: minmax(300px, 0.88fr) minmax(0, 1.12fr);
  gap: 18px;
  align-items: start;
  min-width: 0;
  max-width: 100%;
}

.split-layout > *,
.requirement-panel,
.list-panel {
  min-width: 0;
}

.detail-scroll-layout > .list-panel,
.detail-scroll-layout > .requirement-panel {
  position: sticky;
  top: 96px;
  max-height: calc(100vh - 118px);
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-gutter: stable;
  align-self: start;
}

.detail-scroll-layout > .list-panel {
  padding-right: 4px;
}

.detail-scroll-layout > .list-panel .search {
  position: sticky;
  top: 0;
  z-index: 2;
