}

.detail-scroll-layout > .list-panel::-webkit-scrollbar-thumb,
.detail-scroll-layout > .requirement-panel::-webkit-scrollbar-thumb {
  border: 3px solid transparent;
  border-radius: 999px;
  background: rgba(96, 112, 122, 0.42);
  background-clip: padding-box;
}

.template-view {
  grid-template-columns: minmax(260px, 0.52fr) minmax(0, 1.48fr);
  align-items: start;
}

.nis-detail-layout {
  grid-template-columns: minmax(340px, 0.42fr) minmax(0, 0.58fr);
}

.nis-detail-layout .section-button {
  grid-template-columns: minmax(0, 1fr);
}

.nis-detail-layout .section-button > span:first-child {
  min-width: 0;
  overflow-wrap: anywhere;
}

.nis-detail-layout .section-button .badge {
  justify-self: start;
}

.list-panel {
  display: grid;
  gap: 10px;
  align-content: start;
}

.search {
  width: 100%;
  min-height: 42px;
  padding: 10px 12px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  background: var(--surface);
}

.requirement-button,
.section-button {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  text-align: left;
}

.requirement-button:hover,
.requirement-button.active,
.section-button:hover,
.section-button.active {
  border-color: var(--accent);
  background: #f1fbfc;
}

.requirement-button strong,
.section-button strong {
  display: block;
  font-size: 15px;
}

.requirement-button span,
.section-button span {
  color: var(--muted);
  font-size: 13px;
}

.badge,
.tag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  padding: 3px 8px;
  border-radius: 999px;
  background: #e7edf0;
  color: #33424a;
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
}

.badge.must {
  background: #f9e8e6;
  color: var(--danger);
}

.badge.should {
  background: #fff0d5;
  color: #8c5808;
}

.badge.practice {
  background: #e3f4ea;
  color: var(--green);
}

.tag.must {
  background: #f9e8e6;
  color: var(--danger);
}

.tag.should {
  background: #fff0d5;
  color: #8c5808;
}

.tag.practice {
  background: #e3f4ea;
  color: var(--green);
}

.requirement-panel {
  padding: 20px;
  overflow-wrap: anywhere;
}

.requirement-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 14px 0;
}

.source-list,
.plain-list {
  padding-left: 18px;
  margin: 10px 0 0;
}

.source-list li,
.plain-list li {
  margin: 7px 0;
}

.source-list a {
  color: var(--accent-dark);
  overflow-wrap: anywhere;
}

.compare-table,
.data-table {
  width: 100%;
  min-width: 980px;
  border-collapse: collapse;
}

.compare-table {
  min-width: 880px;
}

.compare-table th,
.compare-table td,
.data-table th,
.data-table td {
  padding: 11px 10px;
  border-bottom: 1px solid var(--line);
  text-align: left;
  vertical-align: top;
}

.compare-table th,
.data-table th {
  color: var(--muted);
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0;
}

.table-panel {
  overflow: hidden;
}

.table-panel h3 {
  padding: 16px 16px 0;
}

.table-scroll {
  overflow-x: auto;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin: 14px 0 16px;
}

.form-grid.two {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.risk-form {
  grid-template-columns: repeat(4, minmax(160px, 1fr));
  gap: 14px;
}

.field {
  display: grid;
  gap: 6px;
}

.field label {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
}

.field-help,
.soa-wizard-context label .field-help,
.soa-wizard-form label .field-help {
  display: block;
  color: #647684;
  font-size: 12px;
  font-weight: 650;
  line-height: 1.42;
  text-transform: none;
  overflow-wrap: anywhere;
}

.field input,
.field select,
.field textarea {
  width: 100%;
  min-height: 44px;
  padding: 10px 11px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  background: var(--surface);
}

.field textarea {
  min-height: 96px;
  resize: vertical;
}

.risk-form .field textarea {
  min-height: 124px;
  line-height: 1.35;
}

.risk-form .field input,
.risk-form .field select {
  min-height: 46px;
}

.risk-workshop-panel {
  display: grid;
  gap: 18px;
  margin-bottom: 18px;
  border-color: rgba(42, 166, 204, 0.22);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.98) 0%, rgba(239, 248, 250, 0.98) 100%),
    #ffffff;
}

.risk-workshop-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(260px, 0.42fr);
  gap: 16px;
  align-items: stretch;
}

.risk-workshop-head h3 {
  margin: 0;
}

.risk-workshop-head p {
  max-width: 78ch;
  margin: 7px 0 0;
  color: var(--muted);
  line-height: 1.5;
}

.risk-workshop-status {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.risk-workshop-status div {
  display: grid;
  align-content: center;
  min-height: 78px;
  padding: 11px;
  border: 1px solid rgba(216, 222, 228, 0.92);
  border-radius: var(--radius);
  background: #ffffff;
}

.risk-workshop-status div.warning {
  border-color: rgba(194, 126, 20, 0.3);
  background: #fff8eb;
}

.risk-workshop-status strong {
  display: block;
  color: var(--text);
  font-size: 22px;
  line-height: 1;
}

.risk-workshop-status span {
  display: block;
  margin-top: 7px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
  line-height: 1.25;
  text-transform: uppercase;
}

.risk-workshop-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(240px, 0.32fr);
  gap: 16px;
  align-items: start;
}

.risk-workshop-form {
  display: grid;
  grid-template-columns: repeat(4, minmax(150px, 1fr));
  gap: 12px;
}

.risk-workshop-form .field.wide {
  grid-column: span 2;
}

.risk-workshop-form .field.full {
  grid-column: 1 / -1;
}

.risk-workshop-form textarea {
  min-height: 94px;
  line-height: 1.45;
}

.risk-workshop-form .risk-workshop-submit {
  align-self: end;
}

.risk-workshop-form .risk-workshop-submit .primary-button {
  width: 100%;
  min-height: 46px;
}

.risk-board-panel {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(260px, 0.34fr);
  gap: 0;
  overflow: hidden;
  margin-bottom: 18px;
  padding: 0;
  border-color: rgba(6, 31, 61, 0.14);
  background: #ffffff;
}

.risk-board-main {
  min-width: 0;
  padding: 24px;
}

.risk-board-side {
  display: grid;
  align-content: start;
  gap: 18px;
  min-width: 0;
  padding: 24px 20px;
  border-left: 1px solid rgba(216, 222, 228, 0.92);
  background: #f7fafc;
}

.risk-board-toolbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
}

.risk-board-toolbar h3 {
  margin: 0;
  color: var(--text);
  font-size: 24px;
  line-height: 1.15;
}

.risk-board-toolbar p {
  max-width: 76ch;
  margin: 7px 0 0;
  color: var(--muted);
  line-height: 1.45;
}

.risk-board-tabs {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 14px;
  border-bottom: 1px solid rgba(216, 222, 228, 0.92);
}

.risk-board-tabs button {
  min-height: 38px;
  padding: 8px 10px 10px;
  border: 0;
  border-bottom: 3px solid transparent;
  background: transparent;
  color: var(--muted);
  font-weight: 850;
  cursor: pointer;
}

.risk-board-tabs button.active,
.risk-board-tabs button:hover {
  border-color: var(--accent);
  color: var(--accent-dark);
}

.risk-board-controls {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) auto auto;
  gap: 10px;
  align-items: center;
  margin-bottom: 14px;
}

.risk-board-controls input {
  min-width: 0;
  min-height: 42px;
  padding: 10px 12px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  background: #ffffff;
}

.risk-board-controls span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 850;
  white-space: nowrap;
}

.risk-board-list {
  display: grid;
  gap: 0;
  border: 1px solid rgba(216, 222, 228, 0.92);
  border-radius: var(--radius);
  overflow: hidden;
  background: #ffffff;
}

.risk-board-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(124px, 0.24fr) minmax(150px, 0.26fr);
  gap: 16px;
  align-items: center;
  min-width: 0;
  padding: 14px 16px;
  border-left: 4px solid transparent;
  border-bottom: 1px solid rgba(216, 222, 228, 0.76);
  background: #ffffff;
}

.risk-board-item:last-child {
  border-bottom: 0;
}

.risk-board-item.critical {
  border-left-color: #e0475b;
}

.risk-board-item.high {
  border-left-color: #ef7c5a;
}

.risk-board-item.medium {
  border-left-color: #e9c95c;
}

.risk-board-item.low {
  border-left-color: #5bbd8a;
}

.risk-board-item-text,
.risk-board-item-meta,
.risk-board-item-actions {
  display: grid;
  min-width: 0;
}

.risk-board-item-text {
  gap: 5px;
}

.risk-board-item-text strong {
  color: var(--text);
  font-size: 15px;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.risk-board-item-text p {
  margin: 0;
  color: var(--text);
  line-height: 1.38;
  overflow-wrap: anywhere;
}

.risk-board-item-text span,
.risk-board-item-meta small {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
}

.risk-board-gap-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
  margin-top: 2px;
}

.risk-board-gap-row span {
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  min-height: 24px;
  padding: 4px 8px;
  border: 1px solid rgba(184, 95, 13, 0.22);
  border-radius: 999px;
  background: #fff6e8;
  color: #86520c;
  font-size: 11px;
  font-weight: 850;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.risk-board-gap-row span.ready {
  border-color: rgba(25, 135, 84, 0.22);
  background: #eefaf3;
  color: #176b42;
}

.risk-board-item-meta,
.risk-board-item-actions {
  justify-items: start;
  gap: 7px;
}

.risk-board-item-actions .quiet-button {
  width: 100%;
  min-height: 32px;
  padding: 7px 9px;
  font-size: 12px;
}

.risk-board-info {
  padding: 14px;
  border: 1px solid rgba(51, 92, 129, 0.12);
  border-radius: var(--radius);
  background: #eef4fb;
}

.risk-board-info strong {
  color: var(--accent-dark);
}

.risk-board-info p {
  margin: 7px 0 0;
  color: var(--muted);
  line-height: 1.42;
}

.risk-matrix-wrap {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  grid-template-rows: auto auto;
  gap: 8px;
  align-items: center;
}

.risk-matrix-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(34px, 1fr));
  gap: 5px;
}

.risk-matrix-cell {
  position: relative;
  aspect-ratio: 1;
  min-width: 0;
  border: 1px solid rgba(255, 255, 255, 0.74);
  border-radius: 8px;
  cursor: pointer;
  box-shadow: inset 0 0 0 1px rgba(6, 31, 61, 0.04);
}

.risk-matrix-cell.low {
  background: #a8dac6;
}

.risk-matrix-cell.medium {
  background: #f3e980;
}

.risk-matrix-cell.high {
  background: #f6b184;
}

.risk-matrix-cell.critical {
  background: #f27686;
}

.risk-matrix-cell.empty {
  background: #edf3f6;
}

.risk-matrix-cell.active {
  outline: 3px solid rgba(11, 127, 141, 0.36);
  outline-offset: 2px;
}

.risk-matrix-cell span {
  position: absolute;
  top: 50%;
  left: 50%;
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  transform: translate(-50%, -50%);
  border-radius: 999px;
  background: #ffffff;
  color: var(--text);
  font-size: 11px;
  font-weight: 900;
  box-shadow: 0 6px 14px rgba(6, 31, 61, 0.12);
}

.risk-matrix-axis {
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.risk-matrix-axis.impact {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
}

.risk-matrix-axis.likelihood {
  grid-column: 2;
  justify-self: center;
}

.risk-board-kpis {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.risk-board-kpis div {
  min-width: 0;
  padding: 11px;
  border: 1px solid rgba(216, 222, 228, 0.92);
  border-radius: var(--radius);
  background: #ffffff;
}

.risk-board-kpis div.warning {
  border-color: rgba(224, 71, 91, 0.25);
  background: #fff6f7;
}

.risk-board-kpis strong,
.risk-board-kpis span {
  display: block;
}

.risk-board-kpis strong {
  color: var(--text);
  font-size: 22px;
  line-height: 1;
}

.risk-board-kpis span {
  margin-top: 7px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.risk-workshop-guide {
  display: grid;
  gap: 10px;
  padding: 14px;
  border: 1px solid rgba(6, 31, 61, 0.12);
  border-radius: var(--radius);
  background: #ffffff;
}

.risk-workshop-guide strong {
  color: var(--text);
}

.risk-workshop-guide ol {
  margin: 0;
  padding-left: 20px;
  color: var(--muted);
