  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  font-size: 13px;
  line-height: 1.45;
}

.draft-list {
  display: grid;
  gap: 10px;
}

.draft-button {
  width: 100%;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #ffffff;
  color: var(--text);
  text-align: left;
  cursor: pointer;
}

.draft-button:hover,
.draft-button.active {
  border-color: rgba(11, 127, 141, 0.45);
  background: #effafa;
}

.draft-button strong,
.draft-button small {
  display: block;
}

.draft-button small {
  margin-top: 4px;
  color: var(--muted);
  line-height: 1.35;
}

.draft-editor-panel {
  margin-top: 18px;
}

.draft-editor {
  display: grid;
  gap: 14px;
}

.draft-editor-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.draft-editor .field.full {
  grid-column: 1 / -1;
}

.draft-content-editor {
  min-height: 520px;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  font-size: 13px;
  line-height: 1.5;
}

.group-card {
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fbfcfd;
}

.group-card b {
  display: block;
  margin-bottom: 5px;
}

.module-guide {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(260px, 0.9fr) minmax(210px, 0.55fr);
  gap: 16px;
  align-items: start;
  margin-bottom: 18px;
  border-color: rgba(11, 127, 141, 0.22);
  background:
    radial-gradient(circle at top right, rgba(116, 104, 255, 0.08), transparent 34%),
    linear-gradient(135deg, #ffffff 0%, #f6fafb 100%);
}

.module-guide-copy h3 {
  margin: 0;
  font-size: 23px;
  line-height: 1.18;
}

.module-guide-copy p {
  margin: 10px 0 0;
  color: var(--muted);
  line-height: 1.5;
}

.module-guide-steps {
  display: grid;
  gap: 8px;
}

.module-guide-steps span {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  min-height: 42px;
  padding: 8px;
  border: 1px solid rgba(216, 222, 228, 0.94);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.82);
  color: var(--text);
  font-size: 13px;
  font-weight: 800;
  line-height: 1.25;
}

.module-guide-steps b {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 999px;
  background: #eaf7f9;
  color: var(--accent-dark);
  font-size: 12px;
}

.module-guide-side {
  display: grid;
  grid-template-columns: 1fr;
  gap: 8px;
}

.module-guide-side div {
  min-height: 58px;
  padding: 10px;
  border: 1px solid rgba(216, 222, 228, 0.94);
  border-radius: var(--radius);
  background: #ffffff;
}

.module-guide-side strong,
.module-guide-side span {
  display: block;
}

.module-guide-side strong {
  font-size: 22px;
  line-height: 1;
}

.module-guide-side span {
  margin-top: 6px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.module-guide-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  grid-column: 1 / -1;
}

.module-guide-actions .primary-button,
.module-guide-actions .quiet-button {
  min-height: 34px;
  padding: 7px 10px;
  font-size: 12px;
}

.register-empty-state {
  display: grid;
  gap: 5px;
  margin: 16px;
}

.register-empty-state strong,
.register-empty-state span {
  display: block;
}

.empty-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-top: 8px;
}

.empty-actions .primary-button,
.empty-actions .quiet-button {
  min-height: 34px;
  padding: 7px 10px;
  font-size: 12px;
}

.register-actions {
  min-width: 220px;
}

.register-actions .quiet-button,
.register-actions .danger-button {
  min-height: 32px;
  padding: 6px 9px;
  font-size: 12px;
}

.toast {
  position: fixed;
  right: 22px;
  bottom: 22px;
  transform: translateY(120%);
  min-width: 260px;
  max-width: min(420px, calc(100vw - 32px));
  padding: 12px 14px;
  border-radius: var(--radius);
  background: #172327;
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: var(--shadow);
  transition: transform 180ms ease;
  z-index: 20;
}

.toast.success {
  background: #12352b;
}

.toast.warning {
  background: #4b3518;
}

.toast.danger {
  background: #4c1f1d;
}

.toast.show {
  transform: translateY(0);
}

.toast:empty {
  display: none;
}

.empty-state {
  padding: 28px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius);
  background: #fbfcfd;
  text-align: center;
  color: var(--muted);
}

.product-empty-state {
  display: grid;
  justify-items: center;
  gap: 8px;
  padding: 24px;
  background:
    radial-gradient(circle at top, rgba(8, 127, 140, 0.06), transparent 36%),
    #fbfdfe;
}

.product-empty-state.compact {
  padding: 16px;
}

.product-empty-state .empty-state-mark {
  display: grid;
  place-items: center;
  min-width: 38px;
  height: 38px;
  padding: 0 9px;
  border-radius: 999px;
  background: #eaf7f9;
  color: var(--accent-dark);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0;
}

.product-empty-state.access-state {
  border-style: solid;
  background:
    linear-gradient(180deg, rgba(51, 92, 129, 0.05), rgba(255, 255, 255, 0.94)),
    #fbfdfe;
}

.product-empty-state.access-state .empty-state-mark {
  background: #eef4fa;
  color: #335c81;
}

.product-empty-state strong,
.product-empty-state span {
  display: block;
}

.product-empty-state strong {
  color: var(--text);
  font-size: 15px;
}

.product-empty-state > span:not(.empty-state-mark) {
  max-width: 620px;
  line-height: 1.45;
}

@media (max-width: 1120px) {
  .app-shell {
    grid-template-columns: 238px minmax(0, 1fr);
  }

  .dashboard-grid,
  .template-layout {
    grid-template-columns: 1fr;
  }

  .detail-scroll-layout {
    grid-template-columns: minmax(270px, 0.88fr) minmax(0, 1.12fr);
    gap: 14px;
  }

  .nis-detail-layout {
    grid-template-columns: minmax(320px, 0.44fr) minmax(0, 0.56fr);
  }

  .detail-scroll-layout > .list-panel,
  .detail-scroll-layout > .requirement-panel {
    top: 88px;
    max-height: calc(100vh - 106px);
  }

  .metrics,
  .control-groups {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .form-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .app-shell {
    display: block;
  }

  .sidebar {
    position: static;
    padding: 16px;
  }

  .split-layout,
  .detail-scroll-layout {
    grid-template-columns: 1fr;
  }

  .detail-scroll-layout > .list-panel,
  .detail-scroll-layout > .requirement-panel {
    position: static;
    max-height: none;
    overflow: visible;
  }

  .detail-scroll-layout > .list-panel {
    padding-right: 0;
  }

  .detail-scroll-layout > .list-panel .search {
    position: static;
    box-shadow: none;
  }

  .main-nav {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .consultant-review-grid,
  .consultant-boundary-grid,
  .policy-guide-grid {
    grid-template-columns: 1fr;
  }

  .topbar {
    position: static;
    align-items: flex-start;
    flex-direction: column;
    padding: 18px;
  }

  .view {
    padding: 18px;
  }

  .metrics,
  .status-strip,
  .source-grid,
  .control-groups,
  .template-form,
  .draft-editor-grid,
  .form-grid,
  .form-grid.two {
    grid-template-columns: 1fr;
  }

  .field.wide {
    grid-column: auto;
  }
}

/* Professional product polish */
:root {
  --bg: #eef3f5;
  --surface: #ffffff;
  --surface-soft: #f5f8fa;
  --surface-warm: #fff7e8;
  --line: #d7e0e5;
  --line-strong: #b6c5ce;
  --text: #17242b;
  --muted: #60707a;
  --accent: #0b7f8d;
  --accent-dark: #095f69;
  --gold: #b7770f;
  --rose: #a44268;
  --green: #287a4a;
  --blue: #315f86;
  --danger: #a54039;
  --shadow: 0 18px 44px rgba(20, 37, 45, 0.1);
  --shadow-soft: 0 8px 22px rgba(20, 37, 45, 0.07);
  --radius: 8px;
}

html {
  background: var(--bg);
}

body {
  background:
    linear-gradient(180deg, #f8fbfc 0, var(--bg) 340px);
  color: var(--text);
  font-size: 15px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
}

button,
a,
input,
select,
textarea {
  transition:
    border-color 160ms ease,
    background-color 160ms ease,
    color 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease;
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid rgba(11, 127, 141, 0.2);
  outline-offset: 2px;
}

.app-shell {
  grid-template-columns: 304px minmax(0, 1fr);
}

.sidebar {
  position: sticky;
  top: 0;
  height: 100vh;
  overflow-y: auto;
  gap: 18px;
  padding: 22px 18px;
  background: #122126;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: 12px 0 34px rgba(19, 33, 38, 0.1);
}

.brand {
  padding: 4px 4px 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.brand-mark {
  width: 44px;
  height: 44px;
  border-radius: 8px;
  background: #eeb94d;
  box-shadow: inset 0 -10px 18px rgba(18, 33, 38, 0.12);
}

.brand h1 {
  font-size: 18px;
  font-weight: 850;
}

.brand p,
.knowledge-card p {
  color: rgba(246, 251, 252, 0.66);
}

.main-nav {
  gap: 4px;
}

.nav-button {
  grid-template-columns: 30px 1fr auto;
  min-height: 40px;
  padding: 8px 9px;
  border-radius: 8px;
  color: rgba(246, 251, 252, 0.78);
}

.nav-button:hover {
  background: rgba(255, 255, 255, 0.075);
  border-color: rgba(255, 255, 255, 0.12);
}

.nav-button.active {
  background: #edf7f8;
  border-color: #edf7f8;
  color: #112126;
  box-shadow: 0 10px 26px rgba(0, 0, 0, 0.16);
}

.nav-button.active .nav-icon,
.nav-button.active .nav-count {
  background: rgba(11, 127, 141, 0.12);
  color: var(--accent-dark);
}

.nav-icon {
  width: 23px;
  height: 23px;
  border-radius: 7px;
  font-size: 11px;
}

.nav-count {
  min-width: 28px;
  font-weight: 800;
}

.knowledge-card {
  padding: 15px;
  background: rgba(255, 255, 255, 0.055);
}

.main {
  background: transparent;
}

.topbar {
  min-height: 80px;
  padding: 18px 30px;
  background: rgba(248, 251, 252, 0.92);
  border-bottom: 1px solid rgba(183, 197, 206, 0.7);
}

.topbar h2 {
  font-size: 26px;
  font-weight: 850;
}

.eyebrow {
  margin-bottom: 4px;
  color: var(--accent-dark);
  font-size: 11px;
  font-weight: 850;
}

.view {
  width: min(100%, 1480px);
  padding: 28px 32px 48px;
}

.icon-button,
.primary-button,
.quiet-button,
.danger-button {
  min-height: 38px;
  padding: 8px 13px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 800;
  box-shadow: none;
}

.primary-button {
  border-color: var(--accent);
  background: var(--accent);
}

.primary-button:hover {
  background: var(--accent-dark);
  border-color: var(--accent-dark);
  transform: translateY(-1px);
}

.quiet-button,
.icon-button {
  background: #fbfdfe;
  border-color: var(--line);
}

.quiet-button:hover,
.icon-button:hover {
  background: #eef8f9;
  border-color: rgba(11, 127, 141, 0.38);
}

.danger-button:hover {
  background: #fff1ef;
}

.dashboard-grid,
.split-layout {
  gap: 20px;
}

.panel,
.metric-card,
.table-panel,
.requirement-panel,
.source-panel {
  border: 1px solid rgba(183, 197, 206, 0.78);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.98);
  box-shadow: var(--shadow-soft);
}

.panel,
.requirement-panel {
  padding: 20px;
}

.panel-header {
  gap: 18px;
  margin-bottom: 16px;
}

.panel-header h3,
.table-panel h3,
.requirement-panel h3 {
  color: #14262d;
  font-size: 18px;
  font-weight: 850;
}

.panel-header p,
.requirement-panel p {
  color: var(--muted);
}

.metrics {
  gap: 14px;
  margin-bottom: 20px;
}

.metric-card {
  min-height: 118px;
  padding: 16px;
  background: #ffffff;
}

.metric-card span {
  color: #657680;
  font-size: 12px;
  text-transform: uppercase;
}

.metric-card strong {
  margin-top: 10px;
  color: #14262d;
  font-size: 32px;
  line-height: 1;
}

.metric-card small {
  color: var(--muted);
  line-height: 1.35;
}

.status-strip {
  gap: 14px;
}

.status-block {
  min-height: 122px;
  padding: 16px;
  border: 1px solid rgba(183, 197, 206, 0.62);
  background: #f6f9fa;
}

.status-block:nth-child(2) {
  background: #eef8f4;
}

.status-block:nth-child(3) {
  background: #fff8eb;
}

.upload-zone {
  min-height: 178px;
  border-color: #a9bdc8;
  background: #f8fbfc;
}

.upload-zone:hover {
  border-color: var(--accent);
  background: #eff9fa;
}

.requirement-button,
.section-button,
.group-card {
  border-color: rgba(183, 197, 206, 0.78);
  background: #ffffff;
  box-shadow: 0 4px 12px rgba(20, 37, 45, 0.04);
}

.requirement-button:hover,
.section-button:hover {
  transform: translateY(-1px);
}

.requirement-button.active,
.section-button.active {
  border-color: rgba(11, 127, 141, 0.45);
  background: #eef9fa;
  box-shadow: 0 10px 24px rgba(11, 127, 141, 0.12);
}

.badge,
.tag {
  min-height: 24px;
  padding: 3px 9px;
  border-radius: 999px;
  font-size: 11px;
  letter-spacing: 0;
}

.tag.must,
.badge.must {
  background: #fdecea;
  color: #9c342e;
}

.tag.should,
.badge.should {
  background: #fff3d8;
  color: #805008;
}

.tag.practice,
.badge.practice {
  background: #e6f5ec;
  color: #217145;
}

.compare-table,
.data-table {
  font-size: 14px;
}

.compare-table th,
.data-table th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: #f6f9fa;
  color: #5a6b74;
  font-size: 11px;
  font-weight: 850;
}

.compare-table td,
.data-table td {
  background: #ffffff;
}

.compare-table tbody tr:hover td,
.data-table tbody tr:hover td {
  background: #f8fbfc;
}

.table-panel h3 {
  padding: 18px 18px 0;
}

.table-scroll {
  scrollbar-color: #b7c7ce transparent;
}

.field {
  gap: 7px;
}

.field label {
  color: #596b75;
  font-size: 11px;
  letter-spacing: 0;
}

.field input,
.field select,
.field textarea,
.search,
.data-table input,
.data-table select {
  border-color: #b9c8d0;
  border-radius: 8px;
  background: #fbfdfe;
  color: var(--text);
}

.field input:hover,
.field select:hover,
.field textarea:hover,
.search:hover,
.data-table input:hover,
.data-table select:hover {
  border-color: #8fb0bc;
}

.field input:focus,
.field select:focus,
.field textarea:focus,
.search:focus,
.data-table input:focus,
.data-table select:focus {
  border-color: var(--accent);
  background: #ffffff;
  box-shadow: 0 0 0 4px rgba(11, 127, 141, 0.11);
  outline: 0;
}

.data-table input,
.data-table select {
  min-height: 34px;
  padding: 7px 8px;
}

.project-command {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 190px;
  gap: 18px;
  align-items: center;
  padding: 22px;
  border: 1px solid rgba(31, 39, 57, 0.18);
  border-radius: var(--radius);
  background:
    linear-gradient(135deg, #191b2d 0%, #242139 58%, #153235 100%);
  color: #ffffff;
  box-shadow: var(--shadow);
}

.project-command .eyebrow {
  color: #8bdbe4;
}

.project-command h3,
.project-stream h3,
.project-boundary h3 {
  margin: 0;
  letter-spacing: 0;
}

.project-command h3 {
  font-size: clamp(26px, 4vw, 42px);
  line-height: 1.05;
}

.project-command p {
  max-width: 760px;
  margin: 10px 0 0;
  color: rgba(255, 255, 255, 0.76);
  line-height: 1.55;
}

.project-next-callout {
  display: grid;
  gap: 4px;
  max-width: 760px;
  margin-top: 16px;
  padding: 13px 14px;
  border: 1px solid rgba(139, 219, 228, 0.3);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.08);
}

.project-next-callout span,
.project-next-callout small {
  color: rgba(255, 255, 255, 0.72);
  font-size: 12px;
  font-weight: 800;
}

.project-next-callout strong {
  color: #ffffff;
  line-height: 1.25;
}

.project-command-progress {
  display: grid;
  place-items: center;
  gap: 5px;
  min-height: 164px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.08);
}

.project-command-progress strong {
  font-size: 38px;
}

.project-command-progress span {
  color: rgba(255, 255, 255, 0.7);
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
}

.project-orbit {
  width: 116px;
  height: 9px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.16);
}

.project-orbit i {
  display: block;
  width: var(--progress);
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #8bdbe4, #f7c873);
}

.project-command-actions {
  display: flex;
  grid-column: 1 / -1;
  flex-wrap: wrap;
  gap: 10px;
}

.project-command .quiet-button {
  border-color: rgba(255, 255, 255, 0.34);
  background: rgba(255, 255, 255, 0.1);
  color: #ffffff;
}

.simple-project-panel {
  display: grid;
  gap: 14px;
  border-color: rgba(42, 166, 204, 0.22);
  background:
    linear-gradient(135deg, #ffffff 0%, rgba(238, 247, 249, 0.96) 100%),
    #ffffff;
}

.simple-project-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
}

.simple-project-head h3 {
  margin: 0;
  color: var(--text);
}

.simple-project-head p {
  max-width: 78ch;
  margin: 7px 0 0;
  color: var(--muted);
  line-height: 1.5;
}

.simple-project-tracks {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.simple-project-track {
  display: grid;
  gap: 8px;
  min-height: 130px;
  padding: 14px;
  border: 1px solid rgba(216, 222, 228, 0.92);
  border-left: 4px solid rgba(42, 166, 204, 0.72);
  border-radius: var(--radius);
  background: #ffffff;
  color: var(--text);
  text-align: left;
}

.simple-project-track.nis {
  border-left-color: #b2456e;
}

.simple-project-track.shared {
  border-left-color: var(--green);
}

.simple-project-track span,
.simple-project-track small {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
}

.simple-project-track span {
  color: var(--accent-dark);
  font-weight: 900;
  text-transform: uppercase;
}

.simple-project-track strong {
  font-size: 18px;
  line-height: 1.22;
}

.simple-track-meter {
  height: 8px;
  overflow: hidden;
  border-radius: 999px;
  background: #e2eaee;
}

