  margin-bottom: 18px;
  border-color: rgba(39, 132, 145, 0.18);
  background: linear-gradient(135deg, #ffffff 0%, #f5fbfc 100%);
}

.policy-guide h3 {
  margin: 0;
}

.policy-guide p {
  margin: 7px 0 0;
  color: var(--muted);
  line-height: 1.55;
}

.policy-guide-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.policy-guide-grid div {
  display: grid;
  gap: 4px;
  min-height: 74px;
  padding: 12px;
  border: 1px solid rgba(183, 197, 206, 0.72);
  border-radius: 8px;
  background: #ffffff;
}

.policy-guide-grid strong {
  color: var(--text);
  font-size: 22px;
}

.policy-guide-grid span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  line-height: 1.35;
}

.policy-detail-panel {
  margin-bottom: 18px;
  border-color: rgba(39, 132, 145, 0.22);
  background: linear-gradient(135deg, #ffffff 0%, #f6fbfc 100%);
}

.policy-detail-empty {
  display: flex;
  gap: 18px;
  align-items: center;
  justify-content: space-between;
}

.policy-detail-empty-copy {
  max-width: 780px;
}

.policy-detail-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: start;
  margin-bottom: 16px;
}

.policy-detail-head h3 {
  margin: 0;
}

.policy-detail-head p,
.policy-detail-card p {
  margin: 7px 0 0;
  color: var(--muted);
  line-height: 1.55;
}

.policy-detail-badges,
.policy-detail-head-actions,
.policy-detail-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.policy-detail-badges {
  margin-top: 10px;
}

.policy-detail-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.42fr) minmax(320px, 0.72fr);
  gap: 14px;
  align-items: start;
}

.policy-detail-main,
.policy-detail-side {
  display: grid;
  gap: 14px;
}

.policy-detail-card {
  min-width: 0;
  padding: 14px;
  border: 1px solid rgba(183, 197, 206, 0.72);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.92);
}

.policy-detail-section-head {
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.policy-detail-section-head h4 {
  margin: 0;
  color: var(--text);
  font-size: 16px;
}

.policy-detail-section-head > span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 900;
  text-transform: uppercase;
}

.policy-detail-facts,
.policy-detail-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.policy-detail-facts div,
.policy-artifact-list div {
  min-width: 0;
  padding: 10px;
  border: 1px solid rgba(216, 222, 228, 0.9);
  border-radius: 8px;
  background: #fbfdfe;
}

.policy-detail-facts span,
.policy-artifact-list span,
.policy-detail-form label span,
.policy-comment-card label span {
  display: block;
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0;
  text-transform: uppercase;
}

.policy-detail-form label small {
  display: block;
  min-height: 54px;
  color: #667784;
  font-size: 12px;
  font-weight: 650;
  line-height: 1.42;
  overflow-wrap: anywhere;
}

.policy-detail-facts strong,
.policy-artifact-list strong {
  display: block;
  margin-top: 5px;
  color: var(--text);
  line-height: 1.3;
  overflow-wrap: anywhere;
}

.policy-detail-form label,
.policy-comment-card label {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.policy-detail-form label.wide {
  grid-column: span 2;
}

.policy-detail-form label.full {
  grid-column: 1 / -1;
}

.policy-detail-form input,
.policy-detail-form select,
.policy-detail-form textarea,
.policy-comment-card textarea {
  width: 100%;
}

.policy-detail-form textarea,
.policy-comment-card textarea {
  min-height: 92px;
  resize: vertical;
}

.policy-detail-callout {
  display: flex;
  gap: 14px;
  align-items: center;
  justify-content: space-between;
}

.policy-artifact-list {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 12px;
}

.policy-artifact-list div.ready {
  border-color: rgba(40, 125, 75, 0.22);
  background: #edf6f0;
}

.policy-evidence-list,
.policy-link-list {
  display: grid;
  gap: 8px;
  margin: 12px 0;
}

.policy-evidence-row,
.policy-link-chip {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  width: 100%;
  padding: 10px;
  border: 1px solid rgba(216, 222, 228, 0.92);
  border-radius: 8px;
  background: #ffffff;
  color: var(--text);
  text-align: left;
  cursor: pointer;
}

.policy-evidence-row strong,
.policy-link-chip strong {
  display: block;
  overflow-wrap: anywhere;
}

.policy-evidence-row small,
.policy-link-chip small,
.policy-link-chip span {
  display: block;
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  line-height: 1.35;
}

.policy-link-chip {
  grid-template-columns: auto minmax(0, 1fr) auto;
}

.policy-comment-card {
  display: grid;
  gap: 12px;
}

.policy-decision-card .policy-detail-actions,
.policy-artifact-card .policy-detail-actions,
.policy-evidence-card .policy-detail-actions,
.policy-links-card .policy-detail-actions {
  margin-top: 12px;
}

.active-register-row td {
  background: rgba(39, 132, 145, 0.06);
}

.policy-register-panel .table-panel-heading {
  padding: 18px 20px 12px;
}

.policy-table th,
.policy-table td {
  vertical-align: top;
}

.policy-title-cell {
  min-width: 310px;
}

.policy-title-button,
.policy-title-cell span,
.policy-title-cell small {
  display: block;
}

.policy-title-button {
  width: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--text);
  font-weight: 850;
  line-height: 1.25;
  text-align: left;
  cursor: pointer;
}

.policy-title-button:hover {
  color: var(--accent-dark);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.policy-title-cell span {
  max-width: 520px;
  margin-top: 4px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.4;
}

.policy-title-cell small {
  margin-top: 6px;
  color: #516570;
  font-weight: 800;
}

.policy-actions {
  min-width: 280px;
}

.policy-actions .quiet-button {
  min-height: 32px;
  padding: 6px 9px;
  font-size: 12px;
}

.policy-actions .primary-link {
  border-color: rgba(11, 127, 141, 0.28);
  background: #eef9f8;
  color: var(--accent-dark);
}

@media (max-width: 1180px) {
  .policy-detail-layout {
    grid-template-columns: 1fr;
  }

  .policy-detail-side {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 820px) {
  .policy-detail-empty,
  .policy-detail-callout {
    display: grid;
  }

  .policy-detail-head {
    grid-template-columns: 1fr;
  }

  .policy-detail-side,
  .policy-detail-facts,
  .policy-detail-form-grid,
  .policy-artifact-list {
    grid-template-columns: 1fr;
  }

  .policy-detail-form label.wide,
  .policy-detail-form label.full {
    grid-column: auto;
  }

  .policy-link-chip,
  .policy-evidence-row {
    grid-template-columns: 1fr;
  }
}

.source-panel {
  padding: 15px;
}

.source-panel:hover {
  border-color: rgba(11, 127, 141, 0.35);
}

.template-preview {
  background: #f7fafb;
}

.template-preview pre {
  border-color: #d7e0e5;
  background: #ffffff;
}

.toast {
  background: #122126;
  box-shadow: var(--shadow);
}

.toast.success {
  background: #12352b;
}

.toast.warning {
  background: #4b3518;
}

.toast.danger {
  background: #4c1f1d;
}

@media (max-width: 1120px) {
  .app-shell {
    grid-template-columns: 250px minmax(0, 1fr);
  }

  .view {
    padding: 24px;
  }
}

@media (max-width: 760px) {
  .sidebar {
    height: auto;
    position: static;
  }

  .view {
    width: 100%;
    padding: 18px;
  }

  .top-actions,
  .action-row,
  .inline-actions {
    width: 100%;
  }

  .icon-button,
  .primary-button,
  .quiet-button,
  .danger-button {
    flex: 1 1 auto;
  }
}

/* Dashboard redesign inspired by the uploaded SaaS dashboard references */
.sidebar {
  background: #202333;
}

.brand-mark {
  background: #ffb45f;
  color: #202333;
}

.nav-button {
  min-height: 40px;
  color: rgba(255, 255, 255, 0.72);
}

.nav-button:hover,
.nav-button.active {
  background: rgba(125, 112, 255, 0.18);
  border-color: rgba(125, 112, 255, 0.28);
  color: #ffffff;
}

.nav-button.locked {
  border-style: dashed;
  color: rgba(255, 255, 255, 0.58);
}

.nav-button.locked .nav-count {
  background: rgba(255, 180, 95, 0.16);
  color: #ffcf93;
}

.nav-icon {
  background: rgba(255, 255, 255, 0.09);
}

.nav-button.active .nav-icon,
.nav-button.active .nav-count {
  background: rgba(255, 255, 255, 0.12);
  color: #ffffff;
}

.nav-group {
  display: grid;
  gap: 4px;
  padding: 10px 0 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
}

.nav-group:first-child {
  border-top: 0;
  padding-top: 0;
}

.nav-group-label {
  padding: 2px 10px 6px;
  color: rgba(255, 255, 255, 0.38);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0;
  text-transform: uppercase;
}

.nav-button {
  border: 1px solid transparent;
  background: transparent;
}

.nav-button.active {
  background: rgba(125, 112, 255, 0.24);
  border-color: rgba(145, 136, 255, 0.38);
  box-shadow: inset 3px 0 0 #8f84ff;
}

.nav-count {
  justify-self: end;
}

.nav-count.subtle {
  opacity: 0.48;
}

.nav-count.muted-dot {
  min-width: 22px;
  width: 22px;
  height: 3px;
  padding: 0;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.18);
  color: transparent;
}

.dashboard-focus-strip {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(0, 1fr) minmax(0, 1fr);
  gap: 12px;
}

.dashboard-focus-card {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 12px;
  align-items: start;
  min-height: 132px;
  padding: 16px;
  border: 1px solid rgba(183, 197, 206, 0.82);
  border-radius: var(--radius);
  background: #ffffff;
  box-shadow: var(--shadow-soft);
  color: var(--text);
  text-align: left;
}

.dashboard-focus-card.primary {
  border-color: rgba(8, 127, 140, 0.34);
  background:
    linear-gradient(135deg, rgba(237, 248, 250, 0.98), #ffffff 66%),
    #ffffff;
}

.dashboard-focus-card:hover {
  transform: translateY(-1px);
  border-color: rgba(8, 127, 140, 0.38);
  box-shadow: 0 16px 32px rgba(19, 37, 45, 0.1);
}

.focus-step {
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: var(--radius);
  background: #eaf7f9;
  color: var(--accent-dark);
  font-weight: 900;
}

.dashboard-focus-card small {
  display: block;
  color: var(--accent-dark);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.dashboard-focus-card strong {
  display: block;
  margin-top: 4px;
  font-size: 17px;
  line-height: 1.25;
}

.dashboard-focus-card p {
  margin: 7px 0 0;
  color: var(--muted);
  line-height: 1.42;
}

.simple-path-panel {
  display: grid;
  gap: 14px;
  border-color: rgba(42, 166, 204, 0.22);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.98) 0%, rgba(238, 247, 249, 0.96) 100%),
    #ffffff;
}

.simple-path-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
}

.simple-path-head h3 {
  margin: 0;
  color: var(--text);
}

.simple-path-head p {
  max-width: 76ch;
  margin: 7px 0 0;
  color: var(--muted);
  line-height: 1.5;
}

.simple-path-steps {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
}

.simple-path-step {
  display: grid;
  align-content: start;
  gap: 8px;
  min-height: 142px;
  padding: 13px;
  border: 1px solid rgba(216, 222, 228, 0.92);
  border-radius: var(--radius);
  background: #ffffff;
  color: var(--text);
  text-align: left;
}

.simple-path-step.active {
  border-color: rgba(42, 166, 204, 0.34);
  background: #f3fbfc;
}

.simple-path-step.done {
  border-color: rgba(40, 125, 75, 0.24);
  background: #f5fbf7;
}

.simple-path-step > span {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: rgba(42, 166, 204, 0.14);
  color: var(--accent-dark);
  font-size: 12px;
  font-weight: 900;
}

.simple-path-step.done > span {
  background: rgba(40, 125, 75, 0.14);
  color: var(--green);
}

.simple-path-step strong {
  line-height: 1.25;
}

.simple-path-step small {
  color: var(--muted);
  line-height: 1.35;
}

.dashboard-tool-hub {
  display: grid;
  gap: 14px;
  border-color: rgba(11, 127, 141, 0.16);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(248, 252, 253, 0.96)),
    #ffffff;
}

.dashboard-tool-head {
  display: flex;
  gap: 14px;
  justify-content: space-between;
  align-items: flex-start;
}

.dashboard-tool-head h3 {
  margin: 0;
}

.dashboard-tool-head p {
  max-width: 760px;
  margin: 7px 0 0;
  color: var(--muted);
  line-height: 1.5;
}

.dashboard-tool-role {
  display: grid;
  gap: 4px;
  min-width: 180px;
  padding: 11px 12px;
  border: 1px solid rgba(204, 214, 224, 0.88);
  border-radius: var(--radius);
  background: #ffffff;
}

.dashboard-tool-role strong {
  color: var(--text);
}

.dashboard-tool-role span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 850;
}

.dashboard-tool-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.dashboard-tool-grid.secondary {
  margin-top: 12px;
}

.dashboard-tool-card {
  display: grid;
  align-content: start;
  gap: 10px;
  min-width: 0;
  min-height: 220px;
  padding: 15px;
  border: 1px solid rgba(204, 214, 224, 0.92);
  border-radius: var(--radius);
  background: #ffffff;
  box-shadow: 0 10px 22px rgba(42, 45, 76, 0.05);
}

.dashboard-tool-card.warning {
  border-color: rgba(168, 63, 57, 0.26);
  background: #fffaf7;
}

.dashboard-tool-card.active {
  border-color: rgba(11, 127, 141, 0.24);
  background: #f5fbfc;
}

.dashboard-tool-card.done {
  border-color: rgba(22, 139, 74, 0.22);
  background: #f7fcf9;
}

.dashboard-tool-top {
  display: flex;
  gap: 8px;
  justify-content: space-between;
  align-items: flex-start;
}

.dashboard-tool-metric {
  display: grid;
  align-content: center;
  justify-items: center;
  min-width: 38px;
  min-height: 46px;
  padding: 0 8px;
  border-radius: 10px;
  background: rgba(11, 127, 141, 0.11);
  color: var(--accent-dark);
  font-weight: 950;
}

.dashboard-tool-card .dashboard-tool-metric strong {
  color: inherit;
  font-size: 20px;
  line-height: 1;
}

.dashboard-tool-card .dashboard-tool-metric small {
  max-width: 86px;
  color: inherit;
  font-size: 9px;
  font-weight: 900;
  line-height: 1.12;
  text-align: center;
  text-transform: uppercase;
}

.dashboard-tool-card.warning .dashboard-tool-metric {
  background: rgba(168, 63, 57, 0.10);
  color: var(--danger);
}

.dashboard-tool-card.done .dashboard-tool-metric {
  background: rgba(22, 139, 74, 0.10);
  color: var(--green);
}

.dashboard-tool-top .tag {
  max-width: min(100%, 190px);
  white-space: normal;
  text-align: right;
}

.dashboard-tool-card > strong {
  color: var(--text);
  font-size: 18px;
  line-height: 1.22;
  overflow-wrap: anywhere;
}

.dashboard-tool-card p {
  margin: 0;
  color: var(--muted);
  line-height: 1.45;
}

.dashboard-tool-foot {
  display: grid;
  gap: 10px;
  margin-top: auto;
}

.dashboard-tool-foot small {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
}

.dashboard-tool-foot .primary-button,
.dashboard-tool-foot .quiet-button {
  justify-self: start;
}

.dashboard-more-tools {
  border: 1px solid rgba(204, 214, 224, 0.88);
  border-radius: var(--radius);
  background: #fbfdfe;
}

.dashboard-more-tools summary {
  display: flex;
  gap: 10px;
  justify-content: space-between;
  align-items: center;
  min-height: 48px;
  padding: 12px 14px;
  cursor: pointer;
  color: var(--text);
  font-weight: 900;
}

.dashboard-more-tools summary strong {
  display: grid;
  place-items: center;
  min-width: 28px;
  height: 28px;
  border-radius: 999px;
  background: rgba(11, 127, 141, 0.10);
  color: var(--accent-dark);
  font-size: 12px;
}

.dashboard-more-tools[open] {
  padding-bottom: 12px;
}

.dashboard-more-tools[open] .dashboard-tool-grid {
  padding: 0 12px;
}

.command-center {
  border: 0;
  background: transparent;
  box-shadow: none;
  padding: 0;
}

.dashboard-section-nav {
  position: sticky;
  top: 0;
  z-index: 5;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: -4px 0 18px;
  padding: 10px;
  border: 1px solid rgba(183, 197, 206, 0.72);
  border-radius: var(--radius);
  background: rgba(247, 250, 251, 0.92);
  backdrop-filter: blur(12px);
  box-shadow: 0 12px 26px rgba(42, 45, 76, 0.08);
}

.dashboard-section-nav button {
  min-height: 34px;
  padding: 7px 11px;
  border: 1px solid rgba(183, 197, 206, 0.72);
  border-radius: 999px;
  background: #ffffff;
  color: var(--muted);
  font-size: 12px;
  font-weight: 850;
}

.dashboard-section-nav button:hover {
  border-color: rgba(14, 112, 126, 0.32);
  color: #0f6170;
}

.dashboard-section {
  display: grid;
  gap: 14px;
  margin-top: 22px;
  padding-top: 2px;
  scroll-margin-top: 92px;
}

.dashboard-section:first-of-type {
  margin-top: 0;
}

.dashboard-section-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 6px;
  padding: 0 2px;
}

.dashboard-section-head h3 {
  margin: 3px 0 0;
  font-size: 21px;
  line-height: 1.2;
}

.dashboard-section-head p {
  max-width: 820px;
  margin: 5px 0 0;
  color: var(--muted);
  line-height: 1.5;
}

.dashboard-section .customer-cockpit,
.dashboard-section .customer-todo-center,
.dashboard-section .dashboard-workspace {
  margin-top: 0;
}

.dashboard-details {
  border: 1px solid rgba(183, 197, 206, 0.72);
  border-radius: var(--radius);
  background: #ffffff;
  box-shadow: var(--shadow-soft);
}

.dashboard-details summary {
  cursor: pointer;
  padding: 15px 16px;
  color: var(--text);
  font-weight: 850;
}

.dashboard-details .table-panel {
  margin-top: 0;
  border: 0;
  border-top: 1px solid rgba(183, 197, 206, 0.72);
  border-radius: 0;
  box-shadow: none;
}

.workspace-context-bar {
  display: grid;
  grid-template-columns: minmax(260px, 1.1fr) minmax(360px, 0.95fr) auto;
  gap: 14px;
  align-items: center;
  margin-bottom: 18px;
  padding: 16px;
  border: 1px solid rgba(183, 197, 206, 0.76);
  border-radius: var(--radius);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.96), rgba(245, 250, 251, 0.94)),
    radial-gradient(circle at 5% 0%, rgba(116, 104, 255, 0.12), transparent 34%);
  box-shadow: var(--shadow-soft);
}

.workspace-context-main {
