/* Workspace polish: stable sidebar and readable register cards. */
body {
  min-height: 100vh;
}

.app-shell {
  grid-template-columns: 286px minmax(0, 1fr);
  height: 100vh;
  min-height: 100vh;
  overflow: hidden;
  background: #eef4f6;
}

.sidebar {
  position: sticky;
  top: 0;
  height: 100vh;
  overflow-x: hidden;
  overflow-y: auto;
  padding: 22px 18px;
  background:
    linear-gradient(180deg, rgba(39, 39, 61, 0.96) 0%, rgba(29, 33, 49, 0.98) 55%, #1a2231 100%);
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.24) transparent;
}

.sidebar::-webkit-scrollbar {
  width: 7px;
}

.sidebar::-webkit-scrollbar-track {
  background: transparent;
}

.sidebar::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.22);
}

.brand {
  padding-bottom: 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.main-nav {
  gap: 2px;
}

.nav-group {
  gap: 3px;
  padding: 13px 0;
}

.nav-group-label {
  padding: 0 10px 8px;
  color: rgba(255, 255, 255, 0.42);
}

.nav-button {
  grid-template-columns: 28px minmax(0, 1fr) auto;
  min-height: 40px;
  padding: 8px 9px;
}

.nav-button span:nth-child(2) {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.nav-button.active {
  background: rgba(125, 112, 255, 0.22);
  border-color: rgba(145, 136, 255, 0.34);
  box-shadow: inset 3px 0 0 #8f84ff;
}

.nav-count {
  min-width: 28px;
}

.knowledge-card {
  margin-top: 14px;
}

.main {
  height: 100vh;
  overflow-x: hidden;
  overflow-y: auto;
}

.topbar {
  width: 100%;
}

.view {
  width: 100%;
  max-width: 1480px;
  margin: 0 auto;
}

.register-card-list {
  display: grid;
  gap: 12px;
  padding: 16px 18px 18px;
}

.register-work-card {
  display: grid;
  grid-template-columns: minmax(230px, 0.9fr) minmax(360px, 1.35fr);
  gap: 16px 20px;
  padding: 16px;
  border: 1px solid rgba(194, 205, 212, 0.86);
  border-radius: var(--radius);
  background: #ffffff;
  box-shadow: 0 10px 26px rgba(19, 37, 45, 0.05);
}

.register-work-card.register-row-overdue {
  border-color: rgba(194, 126, 20, 0.3);
  background: linear-gradient(180deg, #fffdf8 0%, #ffffff 62%);
}

.register-work-card.register-row-ready {
  border-color: rgba(40, 125, 75, 0.24);
  background: linear-gradient(180deg, #f7fcf9 0%, #ffffff 62%);
}

.register-work-card-main {
  display: grid;
  align-content: start;
  gap: 6px;
}

.register-work-card-main strong {
  color: var(--text);
  font-size: 16px;
  line-height: 1.28;
}

.register-work-card-main p,
.register-work-card-main small {
  margin: 0;
  color: var(--muted);
  line-height: 1.45;
}

.register-card-module {
  width: fit-content;
  padding: 4px 8px;
  border-radius: 999px;
  background: #edf7f8;
  color: var(--accent-dark);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.register-work-card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
}

.register-work-card-grid > div {
  display: grid;
  align-content: start;
  gap: 6px;
  min-width: 0;
  padding: 10px;
  border: 1px solid rgba(216, 222, 228, 0.82);
  border-radius: var(--radius);
  background: #f8fbfc;
}

.register-work-card-grid > div > span:first-child {
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.register-work-card-grid strong {
  min-width: 0;
  overflow-wrap: anywhere;
}

.register-review-cell {
  display: grid;
  justify-items: start;
  gap: 6px;
}

.register-review-cell small {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
}

.register-mini-path {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  min-width: 0;
}

.register-mini-path.compact {
  margin-top: 8px;
  grid-template-columns: repeat(4, minmax(72px, 1fr));
}

.register-mini-path div {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 8px;
  align-items: start;
  min-width: 0;
  padding: 8px;
  border: 1px solid rgba(216, 222, 228, 0.88);
  border-radius: 9px;
  background: #fbfdfe;
}

.register-mini-path div.done {
  border-color: rgba(40, 125, 75, 0.22);
  background: #f5fbf7;
}

.register-mini-path div.active {
  border-color: rgba(11, 127, 141, 0.26);
  background: #f1fbfd;
  box-shadow: inset 3px 0 0 rgba(11, 127, 141, 0.58);
}

.register-mini-path div.warning {
  border-color: rgba(168, 63, 57, 0.26);
  background: #fff8f5;
  box-shadow: inset 3px 0 0 rgba(168, 63, 57, 0.58);
}

.register-mini-path b {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: rgba(6, 31, 61, 0.08);
  color: var(--text);
  font-size: 11px;
  font-weight: 900;
}

.register-mini-path div.done b {
  background: rgba(40, 125, 75, 0.14);
  color: var(--green);
}

.register-mini-path div.active b {
  background: rgba(11, 127, 141, 0.14);
  color: var(--accent-dark);
}

.register-mini-path div.warning b {
  background: rgba(168, 63, 57, 0.12);
  color: var(--danger);
}

.register-mini-path span,
.register-mini-path strong,
.register-mini-path small {
  display: block;
  min-width: 0;
}

.register-mini-path strong {
  color: var(--text);
  font-size: 12px;
  line-height: 1.18;
  overflow-wrap: anywhere;
}

.register-mini-path small {
  margin-top: 3px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.register-card-footer {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-top: 12px;
  border-top: 1px solid rgba(216, 222, 228, 0.82);
}

.register-card-footer .document-actions {
  justify-content: flex-end;
  min-width: 0;
}

.register-actions .register-primary-action {
  border-color: rgba(11, 127, 141, 0.28);
  background: #eef9fb;
  color: var(--accent-dark);
  font-weight: 900;
}

.register-card-footer .register-next-step {
  max-width: min(480px, 100%);
}

.warning-text {
  color: var(--gold);
  font-size: 12px;
  font-weight: 850;
}

@media (max-width: 1180px) {
  .app-shell {
    grid-template-columns: 260px minmax(0, 1fr);
  }

  .sidebar {
    padding-inline: 14px;
  }

  .register-work-card {
    grid-template-columns: 1fr;
  }

  .register-mini-path {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .register-mini-path.compact {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .register-card-footer {
    align-items: stretch;
    flex-direction: column;
  }

  .register-card-footer .document-actions {
    justify-content: flex-start;
  }
}

@media (max-width: 900px) {
  .register-work-card-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .app-shell {
    display: block;
    height: auto;
    min-height: 100vh;
    overflow: visible;
  }

  .sidebar {
    position: static;
    height: auto;
    max-height: none;
  }

  .main {
    height: auto;
    overflow: visible;
  }

  .view {
    max-width: 100vw;
  }

  .register-work-card-grid {
    grid-template-columns: 1fr;
  }
}

/* SFM visual identity base layer. */
:root {
  --bg: #f3f6f7;
  --surface: #ffffff;
  --surface-soft: #eef5f6;
  --surface-warm: #fff8eb;
  --line: #d7e1e5;
  --line-strong: #a7bac2;
  --text: #061f3d;
  --muted: #5d6d79;
  --accent: #2aa6cc;
  --accent-dark: #007ca7;
  --gold: #c98214;
  --rose: #b2456e;
  --green: #287d4b;
  --blue: #061f3d;
  --danger: #a83f39;
  --shadow: 0 22px 54px rgba(6, 31, 61, 0.13);
}

body,
button,
input,
select,
textarea {
  font-family: "Open Sans", Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.topbar h2,
.dashboard-hero h2,
.dashboard-section h3,
.panel-header h3,
.table-panel h3,
.requirement-panel h3,
.register-form-panel h3,
.workspace-context-main h3 {
  color: var(--text);
  font-family: "DM Serif Display", Georgia, "Times New Roman", serif;
  font-weight: 700;
  letter-spacing: 0;
}

.app-shell {
  background:
    radial-gradient(circle at 84% 4%, rgba(42, 166, 204, 0.13), transparent 34%),
    linear-gradient(180deg, #f8fbfc 0%, #eef4f6 100%);
}

.sidebar {
  background:
    radial-gradient(circle at 18% 0%, rgba(69, 166, 194, 0.18), transparent 32%),
    linear-gradient(180deg, #061f3d 0%, #062340 58%, #041932 100%);
  border-right: 1px solid rgba(168, 213, 224, 0.2);
}

.brand {
  grid-template-columns: minmax(92px, auto) minmax(0, 1fr);
  gap: 14px;
  align-items: center;
}

.brand-mark {
  width: auto;
  min-width: 92px;
  height: auto;
  padding: 0;
  border-radius: 0;
  background: transparent;
  color: #ffffff;
  font-size: 29px;
  font-weight: 900;
  letter-spacing: -1.3px;
  text-align: left;
}

.brand h1 {
  font-family: "Open Sans", Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 15px;
  font-weight: 800;
}

.brand p {
  color: rgba(255, 255, 255, 0.68);
}

.nav-group {
  border-top-color: rgba(168, 213, 224, 0.15);
}

.nav-group-label {
  color: rgba(168, 213, 224, 0.62);
}

.nav-icon {
  background: rgba(168, 213, 224, 0.14);
  color: rgba(255, 255, 255, 0.88);
}

.nav-button {
  color: rgba(255, 255, 255, 0.76);
}

.nav-button:hover {
  background: rgba(168, 213, 224, 0.1);
  border-color: rgba(168, 213, 224, 0.18);
}

.nav-button.active {
  background: rgba(42, 166, 204, 0.18);
  border-color: rgba(42, 166, 204, 0.5);
  box-shadow: inset 3px 0 0 var(--accent);
}

.nav-button.active .nav-icon,
.nav-button.active .nav-count {
  background: rgba(42, 166, 204, 0.26);
  color: #ffffff;
}

.knowledge-card {
  border-color: rgba(168, 213, 224, 0.22);
  background: rgba(255, 255, 255, 0.06);
}

.topbar {
  min-height: 90px;
  background: rgba(255, 255, 255, 0.92);
  border-bottom-color: rgba(6, 31, 61, 0.12);
}

.topbar .eyebrow,
.eyebrow {
  color: var(--accent-dark);
  font-weight: 900;
}

.icon-button,
.quiet-button {
  border-color: rgba(6, 31, 61, 0.16);
  background: #ffffff;
}

.icon-button:hover,
.quiet-button:hover {
  border-color: rgba(42, 166, 204, 0.44);
  color: var(--accent-dark);
}

.primary-button {
  border-color: var(--accent-dark);
  background: var(--accent-dark);
  box-shadow: 0 12px 28px rgba(0, 124, 167, 0.18);
}

.primary-button:hover {
  border-color: #006a91;
  background: #006a91;
}

.panel,
.metric-card,
.table-panel,
.requirement-panel,
.source-panel,
.register-work-card,
.workspace-context-bar,
.customer-guide-panel,
.dashboard-focus-card {
  border-color: rgba(6, 31, 61, 0.12);
  box-shadow: 0 18px 42px rgba(6, 31, 61, 0.08);
}

.panel-header,
.register-form-panel .panel-header,
.register-panel-heading {
  border-bottom-color: rgba(6, 31, 61, 0.1);
}

.metric-card,
.dashboard-focus-card,
.register-work-card-grid > div,
.register-date-cell {
  background: #fbfdfe;
}

.metric-card::before,
.dashboard-focus-card::before {
  background: var(--accent);
}

.badge.practice,
.tag.practice,
.register-card-module {
  background: rgba(42, 166, 204, 0.12);
  color: #006a91;
}

.badge.must,
.tag.must {
  background: #f7e9e7;
}

.data-table thead,
.compare-table thead {
  background: #a8d5e0;
}

.data-table th,
.compare-table th {
  color: #061f3d;
  font-weight: 900;
}

.table-panel-heading {
  background: linear-gradient(180deg, rgba(248, 251, 252, 0.96) 0%, rgba(255, 255, 255, 0) 100%);
}

.register-panel {
  background:
    linear-gradient(180deg, rgba(238, 245, 246, 0.95) 0%, #ffffff 44%),
    #ffffff;
}

.register-work-card {
  border-left: 4px solid rgba(42, 166, 204, 0.72);
}

.register-work-card.register-row-overdue {
  border-left-color: var(--gold);
}

.register-work-card.register-row-ready {
  border-left-color: var(--green);
}

.register-next-step {
  border-color: rgba(42, 166, 204, 0.24);
  background: rgba(168, 213, 224, 0.17);
  color: #06334c;
}

.workspace-context-bar,
.customer-guide-panel {
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.94) 0%, rgba(238, 247, 249, 0.96) 100%);
}

@media (max-width: 1180px) {
  .simple-path-steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .page-action-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .simple-project-item {
    grid-template-columns: 42px minmax(0, 1fr);
  }

  .simple-project-meta,
  .simple-project-actions {
    grid-column: 2;
    justify-content: flex-start;
  }

  .document-simple-steps {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .brand {
    grid-template-columns: 1fr;
    gap: 8px;
  }
}

@media (max-width: 980px) {
  .simple-path-head,
  .simple-project-head,
  .document-simple-head,
  .page-action-head {
    display: grid;
  }

  .simple-project-tracks {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .simple-path-steps,
  .document-simple-steps,
  .page-action-grid {
    grid-template-columns: 1fr;
  }

  .simple-project-item {
    grid-template-columns: 1fr;
  }

  .simple-project-number,
  .simple-project-meta,
  .simple-project-actions {
    grid-column: auto;
  }

  .simple-project-actions .primary-button,
  .simple-project-actions .quiet-button,
  .document-simple-head .primary-button,
  .simple-path-head .primary-button,
  .page-action-head .primary-button,
  .page-action-head .quiet-button,
  .page-action-card .primary-button,
  .page-action-card .quiet-button {
    width: 100%;
  }
}

/* Customer-first register cleanup: simple input, clear ISO/NIS-2 separation. */
.register-clean-panel {
  margin-bottom: 18px;
  border-color: rgba(183, 199, 207, 0.7);
  background:
    linear-gradient(180deg, #ffffff 0%, #fbfdfe 100%),
    #ffffff;
}

.register-workflow-panel {
  display: grid;
  gap: 14px;
  margin-bottom: 18px;
  border-color: rgba(42, 166, 204, 0.22);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.96) 0%, rgba(238, 247, 249, 0.96) 100%),
    #ffffff;
}

.register-workflow-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(260px, 0.42fr);
  gap: 16px;
  align-items: stretch;
}

.register-workflow-head h3 {
  margin: 0;
  color: var(--text);
}

.register-workflow-head p {
  max-width: 78ch;
  margin: 7px 0 0;
  color: var(--muted);
  line-height: 1.5;
}

.register-workflow-next {
  display: grid;
  align-content: center;
  gap: 6px;
  min-height: 104px;
  padding: 13px;
  border: 1px solid rgba(42, 166, 204, 0.24);
  border-radius: var(--radius);
  background: #f6fbfc;
}

.register-workflow-next.warning {
  border-color: rgba(194, 126, 20, 0.28);
  background: #fff8eb;
}

.register-workflow-next span,
.register-workflow-kpis span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.register-workflow-next strong {
  color: var(--text);
  font-size: 18px;
  line-height: 1.25;
}

.register-workflow-next small {
  color: var(--muted);
  line-height: 1.35;
}

.register-workflow-steps {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.register-workflow-steps div {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  min-height: 82px;
  padding: 12px;
  border: 1px solid rgba(216, 222, 228, 0.92);
  border-radius: var(--radius);
  background: #ffffff;
}

.register-workflow-steps div.done {
  border-color: rgba(40, 125, 75, 0.24);
  background: #f5fbf7;
}

.register-workflow-steps b {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 10px;
  background: rgba(42, 166, 204, 0.14);
  color: var(--accent-dark);
  font-size: 13px;
}

.register-workflow-steps div.done b {
  background: rgba(40, 125, 75, 0.14);
  color: var(--green);
}

.register-workflow-steps strong,
.register-workflow-steps span {
  display: block;
  min-width: 0;
}

.register-workflow-steps strong {
  color: var(--text);
  line-height: 1.25;
}

.register-workflow-steps span {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
}

.register-workflow-kpis {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
}

.register-workflow-kpis div {
  min-height: 68px;
  padding: 11px;
  border: 1px solid rgba(216, 222, 228, 0.92);
  border-radius: var(--radius);
  background: #ffffff;
}

.register-workflow-kpis div.warning {
  border-color: rgba(194, 126, 20, 0.28);
  background: #fff8eb;
}

.register-workflow-kpis strong {
  display: block;
  color: var(--text);
  font-size: 22px;
  line-height: 1;
}

.register-workflow-kpis span {
  display: block;
  margin-top: 7px;
}

.register-workflow-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.register-workflow-actions .primary-button,
.register-workflow-actions .quiet-button {
  min-height: 34px;
  padding: 7px 10px;
  font-size: 12px;
}

.register-clean-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 16px;
  align-items: flex-start;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(216, 226, 231, 0.78);
}

.register-clean-header h3 {
  margin: 0;
}

.register-clean-header p {
  max-width: 78ch;
  margin-top: 7px;
}

.register-scope-legend,
.register-card-badges {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
}

.register-scope-legend {
  justify-content: flex-end;
  min-width: min(340px, 100%);
}

.scope-badge {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 5px 9px;
  border: 1px solid rgba(6, 31, 61, 0.12);
  border-radius: 999px;
  background: #eef4f6;
  color: #314556;
  font-size: 12px;
  font-weight: 900;
  line-height: 1;
  white-space: nowrap;
}

.scope-badge.iso {
  border-color: rgba(42, 166, 204, 0.34);
  background: rgba(42, 166, 204, 0.12);
  color: #006a91;
}

.scope-badge.nis {
  border-color: rgba(178, 69, 110, 0.24);
  background: rgba(178, 69, 110, 0.1);
  color: #8d3055;
}

.scope-badge.shared {
  border-color: rgba(40, 125, 75, 0.24);
  background: rgba(40, 125, 75, 0.1);
  color: #246d43;
}

.scope-badge.review {
  border-color: rgba(201, 130, 20, 0.28);
  background: #fff8eb;
  color: #8b580c;
}

.register-simple-form {
  grid-template-columns: repeat(4, minmax(150px, 1fr));
  gap: 14px;
  align-items: start;
  margin-top: 16px;
}

.register-simple-form .field.full {
  grid-column: 1 / -1;
}

.register-simple-form .field.wide {
  grid-column: span 2;
}

.register-simple-form .field {
  min-width: 0;
}

.register-simple-form .field label {
  display: block;
  min-height: 18px;
  margin-bottom: 6px;
}

.register-simple-form .field-help {
  display: block;
  margin: 0 0 7px;
  padding: 7px 9px;
  border-left: 2px solid rgba(10, 130, 144, 0.28);
  border-radius: 6px;
  background: rgba(245, 250, 251, 0.9);
  color: #60737d;
  font-size: 11px;
  font-weight: 650;
  line-height: 1.35;
}

.register-simple-form .field input,
.register-simple-form .field select,
.register-simple-form .field textarea {
  width: 100%;
}

.register-simple-form .field:has(button) {
  align-self: end;
}

.register-simple-form .field:has(button) label {
  display: none;
}

.register-simple-form .field:has(button) .primary-button,
.register-simple-form .field:has(button) .quiet-button {
  width: 100%;
  min-height: 42px;
}

.optional-register-section {
  margin-top: 14px;
}

.optional-register-section > summary {
  width: fit-content;
  min-height: 36px;
  padding: 8px 12px;
  border: 1px solid rgba(6, 31, 61, 0.16);
  border-radius: var(--radius);
  background: #ffffff;
  color: var(--text);
  font-weight: 850;
  cursor: pointer;
}

.optional-register-section[open] > summary {
  border-color: rgba(42, 166, 204, 0.42);
  color: var(--accent-dark);
}

.optional-register-section .soc-risk-panel {
  margin-top: 12px;
}

.register-card-badges {
  margin-bottom: 2px;
}

.register-card-badges .register-card-module {
  min-height: 28px;
}

@media (max-width: 980px) {
  .register-clean-header {
    grid-template-columns: 1fr;
  }

  .register-scope-legend {
    justify-content: flex-start;
    min-width: 0;
  }

  .register-workflow-head,
  .register-workflow-steps {
    grid-template-columns: 1fr;
  }

  .register-workflow-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .register-simple-form {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 640px) {
  .register-panel-heading {
    display: grid;
  }

  .register-panel-kpis {
    grid-template-columns: 1fr;
    min-width: 0;
  }

  .register-workflow-kpis,
  .register-mini-path,
  .register-mini-path.compact,
  .register-simple-form {
    grid-template-columns: 1fr;
  }

  .register-simple-form .field.wide {
    grid-column: 1 / -1;
  }
}

@media (max-width: 640px) {
  .register-simple-form,
  .register-simple-form .field.wide {
    grid-template-columns: 1fr;
    grid-column: 1 / -1;
  }
}

/* ISO customer view: practical work packages first, norm depth second. */
.iso-customer-overview {
  display: grid;
  gap: 16px;
}

.iso-customer-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 0.52fr);
  gap: 18px;
  align-items: center;
  border-left: 4px solid var(--accent);
}

.iso-customer-hero h3,
.iso-next-card h3,
.iso-work-card h3 {
  margin: 0;
}

.iso-customer-hero p,
.iso-next-card p,
.iso-work-card p {
  margin: 6px 0 0;
  color: var(--muted);
  line-height: 1.5;
}

.iso-customer-kpis {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.iso-customer-kpis div {
  min-height: 82px;
  padding: 12px;
  border: 1px solid rgba(6, 31, 61, 0.12);
  border-radius: var(--radius);
  background: #fbfdfe;
}

.iso-customer-kpis div.warning {
  border-color: rgba(201, 130, 20, 0.28);
  background: #fff8eb;
}

.iso-customer-kpis strong,
.iso-customer-kpis span {
  display: block;
}

.iso-customer-kpis strong {
  color: var(--text);
  font-size: 26px;
  line-height: 1;
}

.iso-customer-kpis span {
  margin-top: 8px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.iso-next-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  border-left: 4px solid var(--green);
}

.iso-work-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.iso-work-card {
  display: grid;
  gap: 14px;
  padding: 16px;
  border: 1px solid rgba(6, 31, 61, 0.12);
  border-left: 4px solid rgba(42, 166, 204, 0.7);
  border-radius: var(--radius);
  background: #ffffff;
  box-shadow: 0 16px 38px rgba(6, 31, 61, 0.07);
}

.iso-work-card.blocked {
  border-left-color: var(--danger);
}

.iso-work-card.done {
  border-left-color: var(--green);
}

.iso-work-card.active {
  border-left-color: var(--accent);
}

.iso-work-card-top {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  gap: 12px;
}

.iso-step-number {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: 999px;
  background: #a8d5e0;
  color: #061f3d;
  font-family: "DM Serif Display", Georgia, "Times New Roman", serif;
  font-size: 23px;
  font-weight: 700;
}

.iso-work-card-body {
  display: grid;
  grid-template-columns: 1.2fr 0.9fr 0.9fr;
