  gap: 10px;
  align-items: center;
  min-width: 0;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fbfcfd;
}

.guided-handover-action.rework {
  border-color: rgba(168, 63, 57, 0.24);
  background: #fff8f7;
}

.guided-handover-action.waiting {
  border-color: rgba(10, 130, 144, 0.22);
  background: #f7fcfd;
}

.guided-handover-action strong,
.guided-handover-action small {
  display: block;
  overflow-wrap: anywhere;
}

.guided-handover-action small {
  margin-top: 4px;
  color: var(--muted);
  line-height: 1.35;
}

.guided-handover-empty {
  display: grid;
  gap: 5px;
  padding: 13px;
  border: 1px dashed rgba(10, 130, 144, 0.32);
  border-radius: var(--radius);
  background: #f7fcfd;
}

.guided-handover-empty strong,
.guided-handover-empty span {
  display: block;
  overflow-wrap: anywhere;
}

.guided-handover-empty span {
  color: var(--muted);
  line-height: 1.42;
}

.guided-handover-list {
  display: grid;
  gap: 8px;
}

.guided-handover-item {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto auto;
  gap: 12px;
  align-items: center;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fbfcfd;
}

.guided-handover-item.missing {
  border-color: rgba(168, 63, 57, 0.25);
  background: #fffaf5;
}

.guided-handover-item.review {
  border-color: rgba(201, 130, 20, 0.26);
  background: #fffcf4;
}

.guided-handover-item.ready {
  border-color: rgba(40, 125, 75, 0.22);
  background: #f7fcf8;
}

.guided-handover-icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 999px;
  background: #e8f5f6;
