  font-size: 12px;
  font-weight: 900;
}

.guided-handover-item.missing .guided-handover-icon {
  background: #f8e5dd;
  color: var(--danger);
}

.guided-handover-item.review .guided-handover-icon {
  background: #fff0cf;
  color: #8a5a0b;
}

.guided-handover-item div {
