}

.guided-fast-card span {
  width: max-content;
  padding: 5px 9px;
  border-radius: 999px;
  background: #e8f5f6;
  color: var(--accent-dark);
  font-size: 12px;
  font-weight: 900;
}

.guided-fast-card strong {
