}

.guided-task-panel .panel-header {
  align-items: center;
}

.guided-capture-panel .panel-header {
  align-items: start;
}

.guided-capture-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.guided-capture-card {
  display: grid;
  gap: 14px;
  min-width: 0;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: #fbfcfd;
}

.guided-capture-card.evidence {
  border-color: rgba(8, 127, 140, 0.28);
  background: #f5fbfc;
}

.guided-capture-card.locked {
  align-content: start;
  background: #f4f6f7;
}

