.evidence-matrix-panel .panel-header > *,
.audit-matrix-hero .panel-header > *,
.audit-bundle-panel .panel-header > *,
.soa-hero .panel-header > *,
.soa-wizard-head > *,
.review-filter-head > *,
.review-overview-head > * {
  min-width: 0;
}

.table-scroll,
.soa-table-scroll,
.role-permission-matrix,
.audit-matrix-table-wrap {
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
}

.data-table,
.soa-table,
.audit-matrix-table {
  width: max-content;
  max-width: none;
}

.data-table th,
.data-table td,
.soa-table th,
.soa-table td,
.audit-matrix-table th,
.audit-matrix-table td {
  white-space: normal;
  overflow-wrap: break-word;
}

.tag,
.badge,
.scope-badge,
.nav-count {
  white-space: nowrap;
}

.document-actions,
.risk-compliance-actions,
.workspace-context-actions,
.register-actions,
.review-item-actions,
.review-queue-actions,
.audit-bundle-card-actions,
.soa-row-actions,
.project-command-actions {
  min-width: 0;
  max-width: 100%;
}

@media (max-width: 1280px) {
  .risk-compliance-layout {
    grid-template-columns: 1fr;
  }

  .management-score-card {
    grid-template-columns: minmax(142px, 0.26fr) minmax(0, 1fr);
  }
}

@media (max-width: 980px) {
  .dashboard-grid,
  .workspace-context-bar,
  .risk-board-panel,
  .risk-workshop-layout,
  .soa-wizard-layout,
  .template-view,
  .split-layout {
    grid-template-columns: 1fr;
  }

  .panel-header,
  .risk-compliance-head,
  .workspace-context-bar,
  .table-panel-heading,
  .soa-hero .panel-header,
  .soa-wizard-head {
    display: grid;
  }
}

@media (max-width: 760px) {
  .view {
    padding-inline: 14px;
  }

  .panel,
  .table-panel,
  .risk-compliance-dashboard,
  .risk-board-main,
  .risk-board-side,
  .soa-hero,
  .soa-wizard,
  .register-work-card {
    padding: 14px;
  }

  .dashboard-section-nav {
    position: static;
  }

  .management-score-card,
  .management-traffic-card,
  .risk-board-item,
  .customer-todo-item,
  .review-item,
  .review-queue-item,
  .register-work-card,
  .management-action-row,
  .management-decision-log-row {
    grid-template-columns: 1fr;
  }

  .management-score-card,
  .management-traffic-card {
    justify-items: start;
    text-align: left;
  }

  .management-score-badges,
  .management-traffic-card .tag {
    justify-content: flex-start;
    justify-self: start;
  }
}

/* Platform-wide clarity layer: preserve the customer view on narrower workspaces. */
.app-shell {
  grid-template-columns: clamp(248px, 20vw, 304px) minmax(0, 1fr);
}

.topbar,
.topbar > div,
.top-actions,
.view,
.nav-group,
.nav-button,
.panel,
.table-panel,
.dashboard-section,
.risk-compliance-dashboard,
.simple-project-panel,
.project-filter-panel,
.register-card-list,
.document-command-center,
.review-center-layout,
.audit-bundle-panel,
.soa-wizard,
.template-view {
  min-width: 0;
}

.nav-button > span:nth-child(2) {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.topbar h2,
.panel-header h3,
.dashboard-section-head h3,
.risk-compliance-head h3,
.simple-project-head h3,
.table-panel h3 {
  overflow-wrap: break-word;
  hyphens: auto;
}

.top-actions,
.risk-compliance-actions,
.project-command-actions,
.workspace-context-actions,
.register-actions,
.document-actions,
.review-item-actions,
.audit-bundle-card-actions {
  justify-content: flex-start;
}

.dashboard-focus-strip {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 330px), 1fr));
}

.dashboard-focus-card {
  min-height: 0;
}

.dashboard-focus-card strong,
.management-traffic-card strong,
.simple-project-track strong,
.simple-project-copy strong,
.register-work-card-main strong {
  overflow-wrap: break-word;
  word-break: normal;
  hyphens: auto;
}

.dashboard-tool-grid {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 310px), 1fr));
}

.dashboard-tool-card {
  align-content: start;
}

.risk-compliance-layout {
  grid-template-columns: minmax(280px, 0.27fr) minmax(410px, 0.44fr) minmax(300px, 0.29fr);
}

.management-score-card {
  grid-template-columns: 136px minmax(0, 1fr);
  align-items: center;
  text-align: left;
}

.management-score-card p {
  max-width: 36ch;
}

.management-traffic-card {
  grid-template-columns: 58px minmax(220px, 1fr) auto;
  min-height: 0;
}

.management-focus-columns {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 320px), 1fr));
}

.management-focus-column button {
  min-height: 0;
}

.management-board-grid,
.management-risk-insights {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 360px), 1fr));
}

.simple-project-tracks,
.project-track-summary,
.project-stream-lane-items {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 260px), 1fr));
}

.simple-project-item {
  grid-template-columns: 42px minmax(0, 1fr) minmax(220px, 0.32fr) auto;
}

.project-filter-grid,
.form-grid,
.template-form,
.draft-editor-grid,
.account-form,
.admin-form,
.backend-login-form {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 230px), 1fr));
}

.field,
.question-card,
.onboarding-field,
.project-filter-grid label {
  min-width: 0;
}

.field input,
.field select,
.field textarea,
.question-card input,
.question-card select,
.question-card textarea,
.project-filter-grid input,
.project-filter-grid select {
  width: 100%;
  min-width: 0;
}

.table-scroll,
.soa-table-scroll,
.audit-matrix-table-wrap,
.role-permission-matrix {
  border-radius: var(--radius);
}

@media (max-width: 1540px) {
  .risk-compliance-layout {
    grid-template-columns: minmax(300px, 0.38fr) minmax(0, 0.62fr);
  }

  .risk-compliance-layout > .management-compliance-card {
    grid-column: 1 / -1;
  }
}

@media (max-width: 1320px) {
  .topbar {
    align-items: flex-start;
    flex-direction: column;
  }

  .top-actions {
    width: 100%;
  }

  .simple-project-item {
    grid-template-columns: 42px minmax(0, 1fr);
  }

  .simple-project-meta,
  .simple-project-actions {
    grid-column: 2;
    justify-content: flex-start;
  }
}

@media (max-width: 1080px) {
  .risk-compliance-layout,
  .management-score-card,
  .management-traffic-card {
    grid-template-columns: 1fr;
  }

  .management-score-card {
    justify-items: start;
  }

  .management-score-badges {
    justify-content: flex-start;
  }
}

/* Customer-ready dashboard polish: no clipped subnav, no squeezed path cards. */
.app-shell {
  grid-template-columns: clamp(286px, 22vw, 324px) minmax(0, 1fr);
}

.sidebar {
  min-width: 0;
}

.nav-button {
  grid-template-columns: 28px minmax(0, 1fr) auto;
  min-height: 42px;
  align-items: center;
}

.nav-button > span:nth-child(2) {
  overflow: visible;
  text-overflow: clip;
  white-space: normal;
  line-height: 1.25;
}

.dashboard-section-nav {
  position: static;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin: 0 0 26px;
  padding: 12px;
  border-color: rgba(183, 197, 206, 0.85);
  background: #f8fbfc;
  box-shadow: none;
}

.dashboard-section-nav button {
  flex: 0 1 auto;
  min-width: 0;
  padding: 8px 14px;
}

.dashboard-section {
  margin-top: 28px;
  scroll-margin-top: 110px;
}

.dashboard-section-head {
  max-width: 860px;
}

.simple-path-panel {
  overflow: hidden;
}

.simple-path-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: start;
}

.simple-path-head .primary-button {
  justify-self: end;
  max-width: 100%;
  white-space: normal;
}

.simple-path-steps {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 255px), 1fr));
}

.simple-path-step {
  min-height: 156px;
  padding: 15px;
}

.simple-path-step .tag,
.simple-path-step .badge {
  width: fit-content;
  max-width: 100%;
  white-space: normal;
}

@media (max-width: 1280px) {
  .simple-path-head {
    grid-template-columns: 1fr;
  }

  .simple-path-head .primary-button {
    justify-self: start;
  }
}

@media (max-width: 1180px) {
  .app-shell {
    grid-template-columns: 272px minmax(0, 1fr);
  }
}

@media (max-width: 760px) {
  .dashboard-section-nav {
    gap: 8px;
  }

  .dashboard-section-nav button,
  .simple-path-head .primary-button {
    width: 100%;
  }
}

/* Presentation polish layer: calm, spacious, colleague-demo ready. */
:root {
  --demo-bg: #eef5f7;
  --demo-ink: #10242d;
  --demo-muted: #61737d;
  --demo-panel: #ffffff;
  --demo-accent: #087f8c;
  --demo-accent-soft: #e9f7f9;
  --demo-gold-soft: #fff3dc;
  --demo-shadow: 0 18px 44px rgba(16, 36, 45, 0.09);
  --demo-shadow-soft: 0 8px 20px rgba(16, 36, 45, 0.06);
}

body {
  background:
    linear-gradient(180deg, #f8fcfd 0, #eef5f7 360px),
    var(--demo-bg);
}

.app-shell {
  grid-template-columns: clamp(292px, 21vw, 320px) minmax(0, 1fr);
}

.sidebar {
  padding: 26px 20px;
  background:
    linear-gradient(180deg, #082b3f 0%, #082134 54%, #071d2e 100%);
  border-right: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: 16px 0 36px rgba(8, 29, 46, 0.16);
}

.brand {
  grid-template-columns: 86px minmax(0, 1fr);
  gap: 14px;
  padding: 5px 4px 22px;
}

.brand-mark {
  width: 78px;
  height: 54px;
  border-radius: 13px;
  background: #ffffff;
  color: #082134;
  font-size: 0;
  letter-spacing: 0;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.18);
}

.brand-mark::before {
  content: "SFM";
  font-size: 22px;
  font-weight: 950;
  letter-spacing: -0.02em;
}

.brand h1 {
  font-size: 20px;
  line-height: 1.15;
}

.brand p {
  max-width: 20ch;
  color: rgba(245, 251, 253, 0.72);
  font-size: 13px;
}

.nav-group {
  padding-block: 4px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.09);
}

.nav-group:last-of-type {
  border-bottom: 0;
}

.nav-button {
  min-height: 43px;
  margin-block: 1px;
  padding: 9px 10px;
  color: rgba(246, 251, 253, 0.8);
}

.nav-button:hover {
  background: rgba(255, 255, 255, 0.08);
  color: #ffffff;
  transform: translateX(2px);
}

.nav-button.active {
  background: rgba(8, 127, 140, 0.98);
  border-color: rgba(152, 232, 239, 0.38);
  color: #ffffff;
  box-shadow: 0 16px 28px rgba(0, 0, 0, 0.18);
}

.nav-icon {
  background: rgba(255, 255, 255, 0.13);
  color: rgba(255, 255, 255, 0.82);
}

.nav-button.active .nav-icon,
.nav-button.active .nav-count {
  background: rgba(255, 255, 255, 0.18);
  color: #ffffff;
}

.nav-count {
  min-width: 30px;
  background: rgba(255, 255, 255, 0.1);
  color: rgba(245, 251, 253, 0.74);
  font-size: 11px;
}

.knowledge-card {
  padding: 16px;
  border-color: rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.075);
}

.main {
  background:
    radial-gradient(circle at 10% 0%, rgba(8, 127, 140, 0.08), transparent 280px),
    transparent;
}

.topbar {
  min-height: 92px;
  padding: 22px clamp(24px, 2.2vw, 42px);
  background: rgba(248, 252, 253, 0.94);
  backdrop-filter: blur(14px);
}

.topbar h2 {
  color: var(--demo-ink);
  font-size: clamp(27px, 2.2vw, 36px);
  font-weight: 950;
  letter-spacing: 0;
}

.topbar .eyebrow {
  color: var(--demo-accent);
}

.top-actions {
  gap: 9px;
}

.view {
  width: min(100%, 1560px);
  padding: clamp(24px, 2vw, 38px) clamp(22px, 2.6vw, 48px) 58px;
}

.dashboard-presentation-suite {
  display: grid;
  gap: 16px;
  margin: 0 0 34px;
  padding: clamp(16px, 1.7vw, 24px);
  border: 1px solid rgba(183, 197, 206, 0.68);
  border-radius: 18px;
  background:
    linear-gradient(180deg, rgba(245, 251, 252, 0.96), rgba(255, 255, 255, 0.98)),
    #ffffff;
  box-shadow: var(--demo-shadow-soft);
}

.dashboard-presentation-suite-head {
  display: flex;
  gap: 6px;
  align-items: flex-start;
  justify-content: space-between;
  padding: 2px 2px 4px;
}

.dashboard-presentation-suite-head > div:first-child {
  display: grid;
  gap: 6px;
  max-width: 980px;
}

.dashboard-presentation-suite-head h3 {
  margin: 0;
  color: var(--demo-ink);
  font-size: clamp(22px, 1.9vw, 32px);
  line-height: 1.12;
}

.dashboard-presentation-suite-head p {
  margin: 0;
  color: var(--demo-muted);
  line-height: 1.55;
}

.dashboard-presentation-actions {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  gap: 9px;
  justify-content: flex-end;
  max-width: 520px;
}

.dashboard-presentation-actions .primary-button,
.dashboard-presentation-actions .quiet-button {
  min-height: 40px;
  white-space: nowrap;
}

.presentation-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(410px, 0.36fr);
  gap: 26px;
  align-items: end;
  margin: 0;
  padding: clamp(22px, 2.4vw, 34px);
  border: 1px solid rgba(8, 127, 140, 0.18);
  border-radius: 14px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(235, 249, 251, 0.96)),
    #ffffff;
  box-shadow: var(--demo-shadow);
}

.presentation-hero h3 {
  max-width: 820px;
  margin: 5px 0 0;
  color: var(--demo-ink);
  font-size: clamp(28px, 2.6vw, 42px);
  line-height: 1.08;
  letter-spacing: 0;
}

.presentation-hero p {
  max-width: 780px;
  margin: 16px 0 0;
  color: var(--demo-muted);
  font-size: clamp(15px, 1.05vw, 18px);
  line-height: 1.55;
}

.presentation-hero-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.presentation-hero-metrics span {
  display: grid;
  gap: 6px;
  min-width: 0;
  min-height: 96px;
  padding: 16px;
  border: 1px solid rgba(183, 197, 206, 0.62);
  border-radius: 11px;
  background: #ffffff;
}

.presentation-hero-metrics strong {
  color: var(--demo-ink);
  font-size: clamp(28px, 3vw, 44px);
  line-height: 1;
}

.presentation-hero-metrics small {
  color: var(--demo-muted);
  font-size: 10px;
  font-weight: 850;
  line-height: 1.25;
  overflow-wrap: anywhere;
  text-transform: uppercase;
}

.demo-mode-panel {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(300px, 0.34fr) minmax(240px, 0.24fr);
  gap: 18px;
  align-items: center;
  margin: 0;
  padding: 18px 20px;
  border: 1px solid rgba(183, 197, 206, 0.72);
  border-radius: 14px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(252, 247, 235, 0.94)),
    #ffffff;
  box-shadow: var(--demo-shadow-soft);
}

.demo-mode-panel.active {
  border-color: rgba(194, 126, 20, 0.28);
  background:
    linear-gradient(135deg, #fffdf8, #fff7e8),
    #ffffff;
}

.demo-mode-copy {
  min-width: 0;
}

.demo-mode-copy h3 {
  margin: 4px 0 0;
  color: var(--demo-ink);
  font-size: clamp(20px, 1.5vw, 26px);
  line-height: 1.14;
}

.demo-mode-copy p {
  max-width: 82ch;
  margin: 8px 0 0;
  color: var(--demo-muted);
  line-height: 1.45;
}

.demo-mode-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.demo-mode-metrics span {
  display: grid;
  gap: 4px;
  min-width: 0;
  min-height: 78px;
  padding: 12px;
  border: 1px solid rgba(216, 225, 229, 0.92);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.86);
}

.demo-mode-metrics strong {
  color: var(--demo-ink);
  font-size: clamp(24px, 2.1vw, 34px);
  line-height: 1;
}

.demo-mode-metrics small,
.demo-mode-actions small {
  color: var(--demo-muted);
  font-size: 10px;
  font-weight: 850;
  line-height: 1.25;
  overflow-wrap: anywhere;
  text-transform: uppercase;
}

.demo-mode-actions {
  display: grid;
  gap: 8px;
  justify-items: stretch;
  min-width: 0;
}

.demo-mode-actions .primary-button,
.demo-mode-actions .quiet-button {
  width: 100%;
}

.presentation-guide {
  display: grid;
  gap: 18px;
  margin: 0;
  padding: clamp(18px, 1.8vw, 26px);
  border: 1px solid rgba(183, 197, 206, 0.68);
  border-radius: 14px;
  background: #ffffff;
  box-shadow: var(--demo-shadow-soft);
}

.presentation-guide-intro {
  display: grid;
  gap: 7px;
  max-width: 960px;
}

.presentation-guide-intro h3 {
  margin: 0;
  color: var(--demo-ink);
  font-size: clamp(20px, 1.7vw, 28px);
  line-height: 1.16;
}

.presentation-guide-intro p {
  margin: 0;
  color: var(--demo-muted);
  line-height: 1.55;
}

.presentation-guide-steps {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.presentation-guide-step {
  display: grid;
  grid-template-rows: auto minmax(132px, 1fr) auto;
  gap: 12px;
  min-width: 0;
  padding: 16px;
  border: 1px solid rgba(216, 225, 229, 0.94);
  border-radius: 12px;
  background: linear-gradient(180deg, #ffffff, #f8fbfc);
}

.presentation-guide-number {
  display: inline-grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 11px;
  background: rgba(202, 239, 245, 0.76);
  color: #087f8c;
  font-size: 13px;
  font-weight: 900;
}

.presentation-guide-step h4 {
  margin: 0;
  color: var(--demo-ink);
  font-size: 17px;
  line-height: 1.2;
}

.presentation-guide-step p {
  margin: 8px 0 0;
  color: var(--demo-muted);
  line-height: 1.45;
}

.presentation-guide-step small {
  display: inline-flex;
  width: fit-content;
  max-width: 100%;
  margin-top: 12px;
  padding: 6px 10px;
  border-radius: 999px;
  background: #eef4f6;
  color: var(--demo-ink);
  font-size: 11px;
  font-weight: 850;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.presentation-guide-step .quiet-button {
  width: 100%;
}

.presentation-guide-note {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 13px 14px;
  border: 1px solid rgba(8, 127, 140, 0.16);
  border-radius: 11px;
  background: rgba(235, 249, 251, 0.72);
  color: var(--demo-muted);
  line-height: 1.45;
}

.presentation-guide-note strong {
  flex: 0 0 auto;
  color: var(--demo-ink);
}

.platform-capability-map {
  margin: 0;
  border: 1px solid rgba(183, 197, 206, 0.7);
  border-radius: 14px;
  background: #ffffff;
  box-shadow: var(--demo-shadow-soft);
  overflow: hidden;
}

.platform-capability-map > summary {
  display: flex;
  gap: 16px;
  align-items: center;
  justify-content: space-between;
  padding: 18px 20px;
  cursor: pointer;
  list-style: none;
}

.platform-capability-map > summary::-webkit-details-marker {
  display: none;
}

.platform-capability-map > summary span {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.platform-capability-map > summary strong {
  color: var(--demo-ink);
  font-size: 20px;
  line-height: 1.2;
}

.platform-capability-map > summary small {
  color: var(--demo-muted);
  line-height: 1.35;
}

.platform-capability-map > summary em {
  flex: 0 0 auto;
  padding: 7px 11px;
  border-radius: 999px;
  background: #eef4f6;
  color: var(--demo-ink);
  font-size: 11px;
  font-style: normal;
  font-weight: 850;
  text-transform: uppercase;
}

.platform-capability-map[open] > summary em {
