}

.side-rail-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  min-width: 0;
}

.side-rail-card-head > strong {
  display: inline-grid;
  place-items: center;
  min-width: 38px;
  min-height: 30px;
  padding: 5px 9px;
