  font-weight: 900;
}

.side-rail-list,
.side-rail-gap-list,
.side-rail-actions {
  display: grid;
  gap: 9px;
  min-width: 0;
}

.side-rail-row,
.side-rail-empty,
.side-rail-gap-list > div {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 12px;
  border: 1px solid rgba(216, 222, 228, 0.9);
