/* Team and invitation workspace: secure customer onboarding without password handover. */
.team-workspace {
  display: grid;
  gap: 18px;
}

.team-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(420px, 0.48fr);
  gap: 18px;
  align-items: start;
  border-color: rgba(42, 166, 204, 0.2);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.98) 0%, rgba(238, 247, 249, 0.96) 100%),
    #ffffff;
}

.team-hero h3,
.team-invite-panel h3,
.invite-accept-card h3 {
  margin: 0;
  color: var(--text);
  line-height: 1.2;
}

.team-hero p,
.team-invite-panel p,
.invite-accept-card p {
  color: var(--muted);
  line-height: 1.5;
}

.team-kpi-grid,
.invite-summary {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 130px), 1fr));
  gap: 10px;
}

.team-kpi-grid > div,
.invite-summary > div {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 13px;
  border: 1px solid rgba(216, 222, 228, 0.92);
  border-radius: var(--radius);
  background: #ffffff;
}

.team-kpi-grid > div.warning {
  border-color: rgba(201, 130, 20, 0.28);
  background: #fff8eb;
}

.team-kpi-grid strong,
.invite-summary strong {
  color: var(--text);
  font-size: 23px;
  line-height: 1;
  overflow-wrap: break-word;
}

.team-kpi-grid span,
.invite-summary span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.team-invite-form {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 220px), 1fr));
}

.team-invitation-list,
.team-user-grid {
  display: grid;
  gap: 12px;
  padding: 16px 18px 18px;
}

.team-invitation-row {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) minmax(180px, auto) minmax(170px, auto) auto;
  gap: 14px;
  align-items: center;
  min-width: 0;
  padding: 15px;
  border: 1px solid rgba(216, 222, 228, 0.92);
  border-left: 5px solid rgba(42, 166, 204, 0.72);
  border-radius: var(--radius);
  background: #ffffff;
}

.team-invitation-row.revoked,
.team-invitation-row.expired {
  border-left-color: var(--gold);
  background: #fffaf0;
}

.team-invitation-row.accepted {
  border-left-color: var(--green);
}

.team-invitation-row > div {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.team-invitation-row strong,
.team-invitation-row span,
.team-invitation-row small {
  min-width: 0;
  overflow-wrap: break-word;
}

.team-invitation-row small,
.team-invitation-row > div > span:first-child {
  color: var(--muted);
}

.team-row-actions {
  justify-self: end;
  display: flex !important;
  grid-auto-flow: column;
  gap: 8px !important;
}

.team-delivery-error {
  color: #a04438 !important;
  font-weight: 750;
}

.team-user-grid {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr));
}

.team-user-card {
  display: grid;
  gap: 7px;
  min-width: 0;
  padding: 14px;
  border: 1px solid rgba(216, 222, 228, 0.92);
  border-radius: var(--radius);
  background: #ffffff;
}

.team-user-card.inactive {
  opacity: 0.72;
}

.team-user-card strong,
.team-user-card span,
.team-user-card small {
  overflow-wrap: break-word;
}

.team-user-card > div {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.invite-accept-panel {
  display: grid;
  place-items: center;
  min-height: min(680px, calc(100vh - 140px));
  border-color: rgba(42, 166, 204, 0.2);
  background:
    radial-gradient(circle at top left, rgba(168, 213, 224, 0.3), transparent 34%),
    #ffffff;
}

.invite-accept-card {
  display: grid;
  gap: 16px;
  width: min(100%, 860px);
}

.invite-accept-form {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 220px), 1fr));
  margin-bottom: 0;
}

@media (max-width: 1180px) {
  .team-hero,
  .team-invitation-row {
    grid-template-columns: 1fr;
  }

  .team-row-actions {
    justify-self: start;
  }
}

/* Compliance cockpit: clear executive start view without replacing the detail modules. */
.compliance-cockpit {
  display: grid;
  gap: 18px;
  border-color: rgba(8, 127, 140, 0.18);
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(239, 249, 251, 0.94)),
    #ffffff;
  box-shadow: 0 18px 42px rgba(6, 31, 61, 0.08);
}

.compliance-cockpit-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, 0.28fr);
  gap: 18px;
  align-items: start;
}

.compliance-cockpit-head h3 {
  margin: 2px 0 0;
  color: var(--text);
  font-size: clamp(24px, 2.4vw, 34px);
  line-height: 1.08;
}

.compliance-cockpit-head p {
  max-width: 78ch;
  margin: 8px 0 0;
  color: var(--muted);
  line-height: 1.5;
}

.compliance-cockpit-gate {
  display: grid;
  gap: 6px;
  min-width: 0;
  padding: 14px;
  border: 1px solid rgba(216, 225, 229, 0.95);
  border-left: 5px solid var(--accent);
  border-radius: var(--radius);
  background: #ffffff;
}

.compliance-cockpit-gate.warning {
  border-left-color: #c27e14;
  background: #fff8eb;
}

.compliance-cockpit-gate.done {
  border-left-color: var(--green);
  background: #f5fbf7;
}

.compliance-cockpit-gate span,
