  font-weight: 950;
  text-transform: uppercase;
}

.compliance-cockpit-gate.warning span {
  color: #8a5a0b;
}

.compliance-cockpit-gate.done span {
  color: var(--green);
}

.compliance-cockpit-gate strong {
