}

.notification-inbox-lane-head > span {
  display: inline-grid;
  place-items: center;
  min-width: 28px;
  height: 26px;
  padding: 0 7px;
  border-radius: 999px;
  background: #eaf3f6;
  color: var(--accent-strong);
