  font-weight: 900;
}

.notification-inbox-list {
  display: grid;
  gap: 7px;
}

.notification-inbox-card {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid rgba(183, 197, 206, 0.68);
  border-radius: 9px;
  background: #ffffff;
  color: var(--ink);
