}

.notification-inbox-card.unread {
  border-color: rgba(11, 127, 141, 0.32);
}

.notification-inbox-card:hover {
  border-color: rgba(11, 127, 141, 0.44);
  background: #f8fcfd;
}

.notification-inbox-card span {
  color: var(--accent-strong);
