  background: rgba(255, 255, 255, 0.64);
}

.notification-kpis {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 10px;
}

.notification-kpi {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 14px;
  border: 1px solid rgba(183, 197, 206, 0.78);
  border-radius: var(--radius);
  background: #ffffff;
  color: var(--ink);
