@media (max-width: 1180px) {
  .audit-package-grid,
  .audit-package-criteria {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .audit-package-approval {
    grid-template-columns: 1fr;
  }

  .notification-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .notification-inbox-head,
  .notification-inbox-lanes {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .notification-inbox-head > div:first-child {
    grid-column: 1 / -1;
  }

  .notification-filter-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .notification-delivery-list article {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .notification-delivery-list article > small {
    grid-column: 1 / -1;
  }
