.operations-runtime.error .operations-runtime-dot {
  background: #b8423f;
  box-shadow: 0 0 0 4px rgba(184, 66, 63, 0.12);
}

.operations-runtime strong,
.operations-runtime small {
  display: block;
}

.operations-runtime strong {
  color: #10263d;
  font-size: 12px;
}

.operations-runtime small {
  margin-top: 3px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.35;
}

.operations-kpis {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 12px;
}

.operations-kpi {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding: 16px;
  border: 1px solid var(--line);
  border-top: 3px solid #7d8c96;
  border-radius: 8px;
  background: #fff;
}

.operations-kpi span,
.operations-kpi small {
  color: var(--muted);
}

.operations-kpi span {
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
}

.operations-kpi strong {
  color: #10263d;
  font-size: 28px;
  line-height: 1;
}

.operations-kpi.critical {
  border-top-color: #b8423f;
  background: #fff8f7;
}

.operations-kpi.warning,
.operations-kpi.attention {
  border-top-color: #c9821f;
  background: #fffaf1;
}

.operations-kpi.ready {
  border-top-color: #24835b;
  background: #f5fbf7;
}

.operations-rules {
  display: grid;
  grid-template-columns: minmax(260px, 0.85fr) minmax(0, 1.7fr);
  gap: 24px;
  align-items: center;
}

.operations-rule-steps {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.operations-rule-steps span {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr);
  gap: 8px;
  align-items: center;
  min-width: 0;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: #f7fafb;
  color: #344d60;
  font-size: 12px;
  line-height: 1.35;
}

.operations-rule-steps strong {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border-radius: 50%;
  background: #dff1f5;
  color: #087f9c;
}

.operations-section {
  padding: 4px 0;
}

.operations-section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
  padding: 0 2px;
}

.operations-section-head > strong {
  display: grid;
  min-width: 38px;
  height: 38px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: #fff;
  color: #10263d;
}

.operations-alert-list.compact {
  gap: 10px;
}

.operations-alert {
  position: relative;
  display: grid;
  grid-template-columns: 5px minmax(0, 1fr) auto;
  gap: 16px;
  align-items: center;
  min-width: 0;
  padding: 16px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fff;
}

.operations-alert-mark {
  align-self: stretch;
  min-height: 72px;
  border-radius: 4px;
  background: #7d8c96;
}

.operations-alert.critical .operations-alert-mark {
  background: #b8423f;
}

.operations-alert.warning .operations-alert-mark {
  background: #c9821f;
}

.operations-alert.info .operations-alert-mark {
  background: #087f9c;
}

.operations-alert.acknowledged {
  background: #fffdf8;
}

.operations-alert.resolved {
  background: #f5faf7;
  opacity: 0.86;
}

.operations-alert-main {
  min-width: 0;
}

.operations-alert-labels,
.operations-alert-meta,
.operations-alert-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.operations-alert-labels {
  color: var(--muted);
  font-size: 12px;
}

.operations-severity {
  padding: 4px 7px;
  border-radius: 4px;
  background: #edf2f4;
  color: #344d60;
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
}

.operations-alert.critical .operations-severity {
  background: #f9e4e2;
  color: #a63734;
}

.operations-alert.warning .operations-severity {
  background: #fff0d5;
  color: #8a5a13;
}

.operations-alert-meta {
  margin-top: 12px;
  color: var(--muted);
  font-size: 11px;
}

.operations-alert-meta span {
  padding-right: 8px;
  border-right: 1px solid var(--line);
}

.operations-alert-meta span:last-child {
  padding-right: 0;
  border-right: 0;
}

.operations-alert-actions {
  justify-content: flex-end;
  max-width: 330px;
}

.operations-section-intro {
  max-width: 820px;
  margin: -8px 0 0;
  color: var(--muted);
  line-height: 1.5;
}

.operations-maintenance-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  min-width: 0;
}

.operations-delivery-panel {
  border-color: rgba(11, 127, 141, 0.2);
  background: #fbfdfe;
}

.operations-delivery-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  min-width: 0;
  margin-top: 12px;
}

.operations-delivery-runtime {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  justify-content: space-between;
  min-width: 0;
  margin-top: 12px;
  padding: 10px;
  border: 1px solid rgba(183, 197, 206, 0.68);
  border-radius: 8px;
  background: #ffffff;
}

.operations-delivery-list {
  display: grid;
  gap: 8px;
  min-width: 0;
  margin-top: 12px;
}

.operations-delivery-list article {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) auto minmax(180px, .8fr);
  gap: 10px;
  align-items: center;
  min-width: 0;
  padding: 10px;
  border: 1px solid rgba(183, 197, 206, 0.68);
  border-radius: 8px;
  background: #ffffff;
}

.operations-delivery-list article > div {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.operations-delivery-list article strong,
.operations-delivery-list article small {
  overflow-wrap: anywhere;
}

.operations-delivery-list article small {
  color: var(--muted);
  line-height: 1.35;
}

.operations-maintenance-card {
  display: grid;
  grid-template-columns: 76px minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  min-width: 0;
  padding: 14px;
  border: 1px solid var(--line);
  border-left: 4px solid #c9821f;
  border-radius: 8px;
  background: #fffaf2;
}

.operations-maintenance-card.ready {
  border-left-color: #24835b;
  background: #f5fbf7;
}

.operations-maintenance-card h3,
.operations-maintenance-card p {
  margin: 0;
}

.operations-maintenance-card p {
  margin-top: 4px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.45;
}

.operations-maintenance-count {
  display: grid;
  place-items: center;
  min-height: 68px;
  padding: 8px;
  border: 1px solid rgba(201, 130, 31, 0.24);
  border-radius: 7px;
  background: #fff;
  text-align: center;
}

.operations-maintenance-card.ready .operations-maintenance-count {
  border-color: rgba(36, 131, 91, 0.22);
}

.operations-maintenance-count strong,
.operations-maintenance-count span {
  display: block;
}

.operations-maintenance-count strong {
  color: #10263d;
  font-size: 25px;
  line-height: 1;
}

.operations-maintenance-count span {
  margin-top: 5px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 900;
  text-transform: uppercase;
}

@media (max-width: 1320px) {
  .operations-kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .operations-delivery-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .operations-rules {
    grid-template-columns: 1fr;
  }

  .operations-maintenance-card {
    grid-template-columns: 68px minmax(0, 1fr);
  }

  .operations-maintenance-card > button {
    grid-column: 2;
    justify-self: start;
  }
}

@media (max-width: 900px) {
  .operations-hero {
    align-items: flex-start;
    flex-direction: column;
  }

  .operations-hero-actions {
    width: 100%;
    text-align: left;
  }

  .operations-kpis,
  .operations-rule-steps,
  .operations-maintenance-grid,
  .operations-delivery-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .operations-alert {
    grid-template-columns: 5px minmax(0, 1fr);
  }

  .operations-alert-actions {
    grid-column: 2;
    justify-content: flex-start;
    max-width: none;
  }

  .operations-delivery-list article {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .operations-delivery-list article > small {
    grid-column: 1 / -1;
  }
}

@media (max-width: 720px) {
  .operations-kpis,
  .operations-rule-steps,
  .operations-maintenance-grid,
  .operations-delivery-grid {
    grid-template-columns: 1fr;
  }

  .operations-section-head {
    align-items: flex-start;
  }

  .operations-delivery-runtime {
    align-items: flex-start;
    flex-direction: column;
  }

  .operations-delivery-list article {
    grid-template-columns: 1fr;
  }

  .operations-delivery-list article > small {
    grid-column: auto;
  }

  .operations-alert {
    gap: 12px;
    padding: 12px;
  }

  .operations-alert-actions {
    display: grid;
    width: 100%;
  }

  .operations-alert-actions button,
  .operations-hero-actions button,
  .operations-maintenance-card > button {
    width: 100%;
  }

  .operations-maintenance-card {
    grid-template-columns: 64px minmax(0, 1fr);
  }

  .operations-alert-meta {
    display: grid;
  }

  .operations-alert-meta span {
    padding-right: 0;
    border-right: 0;
  }
}

/* Mobile workspace navigation: keep the active work area above the fold. */
@media (max-width: 760px) {
  .app-shell {
    display: block;
    height: auto;
    min-height: 100vh;
    overflow: visible;
  }

  .sidebar {
    position: sticky;
    top: 0;
    z-index: 40;
    display: grid;
    gap: 8px;
    width: 100%;
    height: auto;
    max-height: none;
    padding: 10px 12px 8px;
    overflow: visible;
    border-right: 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.16);
    box-shadow: 0 8px 22px rgba(6, 31, 61, 0.18);
  }

  .brand {
    display: flex;
    gap: 10px;
    padding: 0 2px 8px;
  }

  .brand-mark {
    width: auto;
    height: auto;
    min-height: 30px;
    padding: 0;
    background: transparent;
    color: #fff;
    font-size: 0;
  }

  .brand-mark::before {
    font-size: 26px;
  }

  .brand h1 {
    font-size: 14px;
  }

  .brand p,
  .knowledge-card,
  .nav-group-label {
    display: none;
  }

  .main-nav {
    display: flex;
    gap: 6px;
    width: 100%;
    padding-bottom: 3px;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    scrollbar-width: thin;
  }

  .nav-group {
    display: contents;
  }

  .nav-button {
    flex: 0 0 auto;
    grid-template-columns: 20px auto auto;
    width: auto;
    min-height: 36px;
    padding: 6px 8px;
  }

  .nav-button > span:nth-child(2) {
    overflow: visible;
    text-overflow: clip;
    white-space: nowrap;
  }

  .nav-icon {
    width: 20px;
    height: 20px;
    font-size: 10px;
  }

  .nav-count {
    min-width: 24px;
    min-height: 20px;
    padding-inline: 6px;
  }

  .main {
    height: auto;
    min-height: calc(100vh - 96px);
    overflow: visible;
  }

  .topbar {
    position: static;
    min-height: 0;
    padding: 14px 16px;
  }

  .topbar h2 {
    font-size: 23px;
  }

  .top-actions {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 6px;
    align-items: stretch;
    flex-direction: initial;
    width: 100%;
  }

  .top-actions .icon-button,
  .top-actions .file-import {
    flex: none;
    width: 100%;
    min-height: 36px;
    padding: 7px 8px;
  }

  .view {
    padding: 16px 12px 32px;
  }

  .workspace-context-bar {
    gap: 10px;
    padding: 12px;
  }

  .workspace-context-main h3 {
    margin-bottom: 5px;
    font-size: 19px;
  }

  .workspace-context-main p {
    gap: 4px 9px;
    font-size: 11px;
  }

  .workspace-context-metrics {
    display: flex;
    gap: 6px;
    width: 100%;
    padding-bottom: 3px;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
  }

  .workspace-context-metrics div {
    flex: 0 0 128px;
    padding: 8px;
  }

  .workspace-context-metrics strong {
    font-size: 17px;
  }

  .workspace-context-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 6px;
    align-items: stretch;
    flex-direction: initial;
    width: 100%;
  }

  .workspace-context-actions .primary-button,
  .workspace-context-actions .quiet-button {
    flex: none;
    width: 100%;
    min-height: 34px;
    padding: 6px 8px;
    font-size: 12px;
  }

  .workspace-context-actions .primary-button:first-child {
    grid-column: 1 / -1;
  }
}

/* Product polish layer: quieter SaaS typography and component consistency. */
:root {
  --bg: #f4f7f8;
  --surface: #ffffff;
  --surface-soft: #f6f9fa;
  --line: #d8e2e7;
  --line-strong: #b7c7cf;
  --text: #0b1f2a;
  --muted: #5f707a;
  --accent: #0a8290;
  --accent-dark: #066775;
  --danger: #a23b36;
  --gold: #a96c0d;
  --green: #24734a;
  --shadow: 0 10px 28px rgba(8, 31, 43, 0.07);
  --shadow-soft: 0 4px 14px rgba(8, 31, 43, 0.055);
  --radius: 8px;
  --font-sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

html {
  text-rendering: optimizeLegibility;
}

body,
button,
input,
select,
textarea {
  font-family: var(--font-sans);
}

body {
  background:
    linear-gradient(180deg, #f9fbfc 0, #f4f7f8 320px),
    var(--bg);
  color: var(--text);
  font-size: 15px;
  line-height: 1.5;
}

h1,
h2,
h3,
h4,
.topbar h2,
.dashboard-hero h2,
.dashboard-section h3,
.panel-header h3,
.table-panel h3,
.requirement-panel h3,
.register-form-panel h3,
.workspace-context-main h3,
.customer-mode-hero-copy h3,
.presentation-hero h3,
.demo-mode-copy h3,
.iso-step-number {
  font-family: var(--font-sans);
  letter-spacing: 0;
}

.topbar h2 {
  font-size: clamp(25px, 1.8vw, 32px);
  font-weight: 850;
  line-height: 1.12;
}

.dashboard-section-head h3,
.presentation-hero h3,
.customer-mode-hero-copy h3,
.project-command h3,
.guided-hero-copy h3,
.guided-primary-copy h3 {
  font-size: clamp(26px, 2.35vw, 38px);
  font-weight: 850;
  line-height: 1.12;
}

.panel-header h3,
.table-panel h3,
.requirement-panel h3,
.customer-mode-list-head h3,
.customer-next-path-head h3,
.customer-mode-journey-head h3 {
  font-size: clamp(18px, 1.25vw, 22px);
  font-weight: 820;
  line-height: 1.18;
}

.eyebrow,
.nav-group-label,
.field label,
.data-table th,
.compare-table th,
.tag,
.badge,
.scope-badge {
  letter-spacing: 0;
}

.app-shell {
  grid-template-columns: clamp(286px, 20vw, 304px) minmax(0, 1fr);
}

.sidebar {
  background: #082437;
  box-shadow: 10px 0 28px rgba(8, 31, 43, 0.14);
}

.brand-mark {
  border-radius: 8px;
  box-shadow: none;
}

.brand h1 {
  font-size: 18px;
  font-weight: 850;
}

.nav-button {
  border-radius: 8px;
  font-size: 14px;
}

.nav-button:hover {
  transform: none;
}

.nav-button.active {
  background: rgba(10, 130, 144, 0.92);
  border-color: rgba(168, 213, 224, 0.42);
  box-shadow: inset 3px 0 0 rgba(255, 255, 255, 0.34);
}

.nav-icon {
  border-radius: 7px;
  font-size: 10px;
  font-weight: 850;
}

.nav-count {
  min-width: 28px;
  min-height: 22px;
  padding: 2px 7px;
  font-size: 11px;
  font-weight: 850;
}

.topbar {
  min-height: 84px;
  background: rgba(249, 251, 252, 0.96);
  border-bottom-color: rgba(183, 199, 207, 0.72);
}

.view {
  width: min(100%, 1500px);
}

.panel,
.table-panel,
.requirement-panel,
.metric-card,
.dashboard-tool-card,
.dashboard-focus-card,
.simple-path-panel,
.compliance-cockpit,
.command-center,
.workspace-context-bar,
.customer-guide-panel,
.customer-mode-hero,
.customer-next-path,
.customer-mode-journey,
.customer-mode-list-card,
.notification-inbox-hub {
  border-radius: 8px;
  border-color: rgba(183, 199, 207, 0.72);
  background: #ffffff;
  box-shadow: var(--shadow-soft);
}

.panel,
.table-panel,
.requirement-panel {
  padding: clamp(18px, 1.35vw, 24px);
}

.panel:hover,
.dashboard-tool-card:hover,
.dashboard-focus-card:hover {
  box-shadow: var(--shadow);
}

.primary-button,
.quiet-button,
.icon-button,
.danger-button,
.file-import,
.dashboard-section-nav button {
  min-height: 38px;
  border-radius: 8px;
  font-weight: 800;
}

.primary-button {
  background: var(--accent-dark);
  border-color: var(--accent-dark);
  box-shadow: none;
}

.primary-button:hover {
  background: #055a66;
  border-color: #055a66;
  transform: none;
}

.quiet-button,
.icon-button,
.dashboard-section-nav button {
  background: #ffffff;
  border-color: rgba(183, 199, 207, 0.9);
}

.quiet-button:hover,
.icon-button:hover,
.dashboard-section-nav button:hover {
  background: #f1f8f9;
  border-color: rgba(10, 130, 144, 0.38);
  transform: none;
}

.tag,
.badge,
.scope-badge,
.nav-count,
.notification-inbox-lane-head > span,
.customer-mode-list-head > strong,
.customer-mode-journey-step > span,
.customer-next-step > span {
  border-radius: 999px;
}

.tag.must,
.badge.must {
  background: #fae9e7;
  color: #93312c;
}

.tag.should,
.badge.should {
  background: #fff2d8;
  color: #76500c;
}

.tag.practice,
.badge.practice {
  background: #e8f5ee;
  color: #236d47;
}

.field input,
.field select,
.field textarea,
.search,
.data-table input,
.data-table select,
.guided-capture-form input,
.guided-capture-form select,
.guided-capture-form textarea {
  min-height: 40px;
  border-radius: 8px;
  border-color: rgba(183, 199, 207, 0.92);
  background: #fbfdfe;
}

.field textarea,
.guided-capture-form textarea {
  line-height: 1.45;
}

.data-table th,
.compare-table th {
  background: #f3f7f8;
  color: #526670;
  font-size: 11px;
  font-weight: 850;
}

.data-table td,
.compare-table td {
  color: var(--text);
}

.workspace-context-bar,
.customer-mode-hero,
.customer-next-path,
.notification-inbox-hub,
.register-workflow-panel,
.document-customer-hub,
.integration-roadmap-hub,
.vendor-cockpit-hub {
  background: #ffffff;
}

.customer-mode-status-card,
.customer-mode-primary-card,
.customer-mode-progress-card,
.customer-next-step,
.customer-mode-journey-step,
.customer-mode-list-item,
.notification-inbox-kpi,
.notification-inbox-lane,
.notification-next-card {
  border-radius: 8px;
  box-shadow: none;
}

.customer-mode-status-card {
  min-height: 104px;
  background: #fbfdfe;
}

.customer-mode-status-card.warning {
  background: #fff8f6;
}

.customer-mode-status-card.ready,
.customer-mode-status-card.approved {
  background: #f7fbf8;
}

.customer-mode-primary-card {
  background: #f4fbfc;
}

.customer-next-path-steps {
  gap: 12px;
}

.customer-next-step {
  min-height: 136px;
}

.customer-next-step p,
.customer-mode-list-item small,
.customer-mode-journey-step small,
.panel-header p,
.requirement-panel p {
  color: var(--muted);
}

.presentation-hero,
.demo-mode-panel,
.compliance-cockpit {
  border-radius: 8px;
  background: #ffffff;
}

.presentation-hero-metrics span,
.demo-mode-metrics span,
.metric-card,
.dashboard-focus-card,
.dashboard-tool-card {
  border-radius: 8px;
}

@media (max-width: 760px) {
  .app-shell {
    display: block;
  }

  .sidebar {
    padding: 10px 12px 8px;
  }

  .topbar {
    min-height: 0;
