  font-size: 12px;
  font-weight: 800;
}

.dashboard-start-status-card p {
  margin: auto 0 0;
  color: #61717d;
  font-size: 13px;
  line-height: 1.5;
  overflow-wrap: anywhere;
}

.dashboard-start-status-card.active {
  border-color: rgba(13, 132, 148, 0.28);
  background: #f7fcfd;
}

.dashboard-start-status-card.warning {
  border-color: rgba(221, 145, 32, 0.36);
  background: #fffaf0;
}

.dashboard-start-status-card.warning span {
  color: #a66500;
}

.dashboard-start-status-card.warning small {
  background: #fff0d2;
  color: #865300;
}

.dashboard-start-status-card.done {
  border-color: rgba(36, 156, 101, 0.28);
  background: #f7fcf9;
}

.dashboard-start-status-card.done span {
  color: #147844;
}

.dashboard-start-status-card.done small {
  background: #def6e8;
  color: #146a40;
}

.dashboard-simple-focus,
.dashboard-control-focus,
.dashboard-evidence-focus,
.dashboard-project-focus {
  display: grid;
  grid-template-columns: minmax(260px, 0.72fr) minmax(280px, 0.86fr) minmax(320px, 1fr);
  gap: 16px;
  align-items: stretch;
  padding: clamp(16px, 1.45vw, 22px);
  border-color: rgba(190, 210, 218, 0.88);
  background: #ffffff;
}

.dashboard-project-focus {
  grid-template-columns: minmax(280px, 0.8fr) minmax(420px, 1.35fr) minmax(260px, 0.75fr);
}

.dashboard-mapping-focus {
  display: grid;
  grid-template-columns: minmax(260px, 0.72fr) minmax(420px, 1.28fr) minmax(280px, 0.85fr);
  gap: 16px;
  align-items: stretch;
  padding: clamp(16px, 1.45vw, 22px);
  border-color: rgba(190, 210, 218, 0.88);
  background: #ffffff;
}

.dashboard-simple-copy {
  min-width: 0;
}

.dashboard-simple-copy h3 {
  margin: 6px 0 8px;
  font-size: clamp(22px, 1.8vw, 30px);
  line-height: 1.12;
}

.dashboard-simple-copy p {
  max-width: 62ch;
  margin: 0;
  color: #61717d;
  line-height: 1.55;
}

.dashboard-simple-primary,
.dashboard-project-next {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-width: 0;
  min-height: 190px;
  padding: 16px;
  border: 1px solid rgba(13, 132, 148, 0.22);
  border-radius: 10px;
  background: #f7fcfd;
}

.dashboard-simple-primary.warning {
  border-color: rgba(221, 145, 32, 0.36);
  background: #fffaf0;
}

.dashboard-simple-primary.active {
  border-color: rgba(13, 132, 148, 0.28);
  background: #f7fcfd;
}

.dashboard-simple-primary span,
.dashboard-project-next span {
  width: fit-content;
  max-width: 100%;
  padding: 5px 9px;
  border-radius: 999px;
  background: #e7f7fb;
  color: #006274;
  font-size: 12px;
  font-weight: 850;
  text-transform: uppercase;
}

.dashboard-simple-primary strong,
.dashboard-project-next strong {
  display: block;
  margin-top: 12px;
  color: #10243a;
  font-size: 20px;
  line-height: 1.22;
  overflow-wrap: anywhere;
}

.dashboard-simple-primary p,
.dashboard-project-next p {
  margin: 8px 0 0;
  color: #61717d;
  line-height: 1.48;
}

.dashboard-simple-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
  margin-top: 16px;
}

.dashboard-simple-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.dashboard-simple-mini {
  display: grid;
  gap: 5px;
  align-content: center;
  min-width: 0;
  min-height: 88px;
  padding: 12px;
  border: 1px solid rgba(203, 216, 222, 0.95);
  border-radius: 10px;
  background: #fbfdfe;
  color: #10243a;
  text-align: left;
}

.dashboard-simple-mini:hover {
  border-color: rgba(13, 132, 148, 0.38);
  box-shadow: 0 12px 26px rgba(8, 31, 43, 0.06);
}

.dashboard-simple-mini span {
  color: #006274;
  font-size: 12px;
  font-weight: 850;
  text-transform: uppercase;
}

.dashboard-simple-mini strong {
  color: #09203a;
  font-size: 26px;
  line-height: 1;
}

.dashboard-simple-mini small {
  color: #61717d;
  font-weight: 750;
}

.dashboard-simple-mini.warning {
  border-color: rgba(221, 145, 32, 0.36);
  background: #fffaf0;
}

.dashboard-simple-mini.warning span {
  color: #a66500;
}

.dashboard-simple-mini.done {
  border-color: rgba(36, 156, 101, 0.24);
  background: #f7fcf9;
}

.dashboard-simple-mini.done span {
  color: #147844;
}

.dashboard-simple-mini.active {
  border-color: rgba(13, 132, 148, 0.25);
  background: #f7fcfd;
}

.dashboard-project-steps {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.dashboard-project-step {
  display: grid;
  grid-template-rows: auto auto auto 1fr;
  gap: 6px;
  min-width: 0;
  min-height: 160px;
  padding: 13px;
  border: 1px solid rgba(203, 216, 222, 0.95);
  border-radius: 10px;
  background: #fbfdfe;
}

.dashboard-project-step > span {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: #e7f7fb;
  color: #00758a;
  font-weight: 900;
}

.dashboard-project-step strong {
  color: #10243a;
  font-size: 15px;
  line-height: 1.2;
}

.dashboard-project-step small {
  width: fit-content;
  max-width: 100%;
  padding: 4px 7px;
  border-radius: 999px;
  background: #eef2f4;
  color: #435765;
  font-size: 11px;
  font-weight: 850;
}

.dashboard-project-step p {
  margin: 0;
  color: #61717d;
  font-size: 12px;
  line-height: 1.38;
  overflow-wrap: anywhere;
}

.dashboard-project-step.done {
  border-color: rgba(36, 156, 101, 0.28);
  background: #f7fcf9;
}

.dashboard-project-step.done > span,
.dashboard-project-step.done small {
  background: #def6e8;
  color: #146a40;
}

.dashboard-project-step.active {
  border-color: rgba(13, 132, 148, 0.3);
  background: #f7fcfd;
}

.dashboard-project-step.locked {
  opacity: 0.72;
}

.dashboard-project-step.review {
  border-color: rgba(221, 145, 32, 0.34);
  background: #fffaf0;
}

.dashboard-project-step.review > span,
.dashboard-project-step.review small {
  background: #fff0d2;
  color: #865300;
}

.dashboard-project-next .primary-button {
  width: fit-content;
  max-width: 100%;
  margin-top: 16px;
}

.dashboard-mapping-cards {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.dashboard-mapping-card,
.dashboard-mapping-rule {
  display: grid;
  align-content: start;
  gap: 8px;
  min-width: 0;
  min-height: 188px;
  padding: 14px;
  border: 1px solid rgba(203, 216, 222, 0.95);
  border-radius: 10px;
  background: #fbfdfe;
  color: #10243a;
  text-align: left;
}

.dashboard-mapping-card:hover {
  border-color: rgba(13, 132, 148, 0.38);
  box-shadow: 0 12px 26px rgba(8, 31, 43, 0.06);
}

.dashboard-mapping-card span,
.dashboard-mapping-rule span {
  color: #006274;
  font-size: 12px;
  font-weight: 850;
  text-transform: uppercase;
}

.dashboard-mapping-card strong {
  color: #09203a;
  font-size: clamp(24px, 2vw, 32px);
  line-height: 1;
}

.dashboard-mapping-rule strong {
  color: #10243a;
  font-size: 19px;
  line-height: 1.22;
}

.dashboard-mapping-card small {
  color: #435765;
  font-weight: 800;
  line-height: 1.35;
}

.dashboard-mapping-card p,
.dashboard-mapping-rule p {
  margin: 0;
  color: #61717d;
  font-size: 13px;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.dashboard-mapping-card.iso {
  border-color: rgba(13, 132, 148, 0.24);
  background: #f7fcfd;
}

.dashboard-mapping-card.nis {
  border-color: rgba(118, 102, 255, 0.25);
  background: #f8f7ff;
}

.dashboard-mapping-card.shared,
.dashboard-mapping-rule {
  border-color: rgba(221, 145, 32, 0.32);
  background: #fffaf0;
}

.dashboard-mapping-rule {
  justify-content: stretch;
}

.dashboard-mapping-rule .dashboard-simple-actions {
  margin-top: auto;
}

.dashboard-overview-library,
.dashboard-workflow-details {
  overflow: hidden;
  border-color: rgba(190, 210, 218, 0.88);
  background: #ffffff;
}

.dashboard-overview-library > summary,
.dashboard-overview-details > summary,
.dashboard-workflow-details > summary {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  min-height: 64px;
  padding: 16px 18px;
  list-style: none;
}

.dashboard-overview-library > summary::-webkit-details-marker,
.dashboard-overview-details > summary::-webkit-details-marker,
.dashboard-workflow-details > summary::-webkit-details-marker {
  display: none;
}

.dashboard-overview-library > summary span,
.dashboard-overview-details > summary span,
.dashboard-workflow-details > summary span {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.dashboard-overview-library > summary strong,
.dashboard-overview-details > summary strong,
.dashboard-workflow-details > summary strong {
  color: #10243a;
  font-size: 16px;
}

.dashboard-overview-library > summary small,
.dashboard-overview-details > summary small,
.dashboard-workflow-details > summary small {
  color: #61717d;
  font-size: 13px;
  font-weight: 650;
  line-height: 1.35;
}

.dashboard-overview-library > summary em,
.dashboard-overview-details > summary em,
.dashboard-workflow-details > summary em {
  display: inline-grid;
  place-items: center;
  min-width: 78px;
  min-height: 32px;
  padding: 6px 10px;
  border-radius: 999px;
  background: #e7f7fb;
  color: #006274;
  font-size: 12px;
  font-style: normal;
  font-weight: 850;
}

.dashboard-overview-library[open] > summary em,
.dashboard-overview-details[open] > summary em,
.dashboard-workflow-details[open] > summary em {
  background: #eef2f4;
  color: #435765;
}

.dashboard-overview-library > .dashboard-overview-detail-stack {
  background: #f4f9fa;
}

.dashboard-overview-detail-stack.nested {
  padding: 14px;
  background: #f8fbfc;
}

.dashboard-overview-detail-stack > .panel,
.dashboard-overview-detail-stack > .dashboard-details {
  margin: 0;
}

@media (max-width: 1180px) {
  .dashboard-simple-focus,
  .dashboard-control-focus,
  .dashboard-evidence-focus,
  .dashboard-mapping-focus,
  .dashboard-project-focus {
