  }

  .dashboard-overview-library > summary em,
  .dashboard-overview-details > summary em,
  .dashboard-workflow-details > summary em {
    justify-self: start;
  }
}

/* Sidebar presentation pass: quieter groups, capped badges, clearer scan path. */
.sidebar {
  background:
    linear-gradient(180deg, rgba(9, 43, 67, 0.98) 0%, rgba(8, 35, 55, 0.99) 58%, #071d31 100%);
}

.brand {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding-bottom: 18px;
}

.brand-mark {
  width: 48px;
  height: 48px;
  border-radius: 11px;
  box-shadow: none;
}

.brand h1 {
  line-height: 1.16;
}

.main-nav {
  gap: 0;
  padding-top: 10px;
}

.nav-group {
  gap: 5px;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.075);
}

.nav-group:last-child {
  border-bottom: 0;
}

.nav-group-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 2px;
  padding: 0 10px 6px;
}

.nav-group-label {
  margin: 0;
  padding: 0;
  color: rgba(233, 247, 250, 0.64);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0;
}

.nav-group-head small {
  color: rgba(233, 247, 250, 0.34);
  font-size: 11px;
  font-weight: 650;
  line-height: 1.25;
}

.nav-button {
  grid-template-columns: 28px minmax(0, 1fr) minmax(0, auto);
  min-height: 42px;
  padding: 8px 10px;
  border: 1px solid transparent;
  border-radius: 10px;
  color: rgba(247, 251, 252, 0.76);
}

.nav-button:hover {
  border-color: rgba(127, 217, 231, 0.16);
  background: rgba(255, 255, 255, 0.055);
