/* Presentation-grade design pass: calmer surfaces, consistent controls, wider workspace. */
:root {
  --bg: #eef4f6;
  --surface: #ffffff;
  --surface-soft: #f5f8fa;
  --line: #d5e0e5;
  --line-strong: #b9c8cf;
  --text: #102233;
  --muted: #5f6f7b;
  --accent: #087f8c;
  --accent-dark: #075f69;
  --shadow: 0 18px 46px rgba(19, 37, 45, 0.11);
  --shadow-card: 0 10px 30px rgba(19, 37, 45, 0.065);
  --shadow-soft: 0 4px 16px rgba(19, 37, 45, 0.045);
  --radius: 8px;
}

html {
  font-size: 15px;
  text-rendering: optimizeLegibility;
}

body {
  background:
    linear-gradient(180deg, #f8fbfc 0%, #eef4f6 420px),
    var(--bg);
  color: var(--text);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.app-shell {
  grid-template-columns: 292px minmax(0, 1fr);
  background: transparent;
}

.main {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.62), rgba(238, 244, 246, 0.76)),
    var(--bg);
}

.view {
  width: min(100%, 1760px);
  padding: clamp(24px, 2vw, 38px) clamp(26px, 2.7vw, 56px) 64px;
}

.topbar {
  min-height: 82px;
  padding: 18px clamp(24px, 2.5vw, 42px);
  border-bottom: 1px solid rgba(184, 200, 207, 0.74);
  background: rgba(255, 255, 255, 0.9);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.82), 0 8px 24px rgba(19, 37, 45, 0.045);
}

.topbar h2 {
  color: var(--text);
  font-size: clamp(25px, 1.65vw, 34px);
  line-height: 1.1;
}

#viewSubtitle {
  max-width: 920px;
  margin-top: 6px;
  color: var(--muted);
  line-height: 1.45;
}

.eyebrow {
  color: #086f7a;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0;
}

.panel,
.metric-card,
.table-panel,
.requirement-panel,
.source-panel,
.dashboard-section,
.module-guide,
.register-empty-state,
.workspace-context-bar,
.customer-guide-panel,
.dashboard-presentation-suite,
.presentation-hero,
.presentation-guide,
.demo-mode-panel,
.platform-capability-map,
.presentation-agenda,
.presentation-readiness {
  border-color: rgba(184, 200, 207, 0.74);
  box-shadow: var(--shadow-card);
}

.panel,
.metric-card,
.table-panel,
.requirement-panel,
.source-panel {
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.96);
}

.panel {
  padding: clamp(16px, 1.45vw, 22px);
}

.panel-header,
.table-panel-heading,
.table-panel .panel-header {
  gap: 18px;
  margin-bottom: 16px;
}

.panel-header h3,
.table-panel h3,
.requirement-panel h3 {
  color: var(--text);
  font-size: clamp(18px, 1.08vw, 21px);
  line-height: 1.18;
}

.panel-header p,
.table-panel p,
.requirement-panel p,
.source-panel p {
  color: var(--muted);
  line-height: 1.55;
}

.primary-button,
.quiet-button,
.icon-button,
.danger-button {
  min-height: 40px;
  border-radius: var(--radius);
  transition:
    background-color 140ms ease,
    border-color 140ms ease,
    color 140ms ease,
    box-shadow 140ms ease,
    transform 140ms ease;
}

.primary-button {
  box-shadow: 0 8px 18px rgba(8, 127, 140, 0.16);
}

.primary-button:hover {
  transform: translateY(-1px);
  box-shadow: 0 10px 22px rgba(8, 127, 140, 0.2);
}

.quiet-button,
.icon-button {
  background: rgba(255, 255, 255, 0.92);
}

.quiet-button:hover,
.icon-button:hover {
  background: #f2fbfc;
  box-shadow: var(--shadow-soft);
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
summary:focus-visible {
  outline: 3px solid rgba(8, 127, 140, 0.22);
  outline-offset: 2px;
}

input,
select,
textarea {
  min-height: 42px;
  border-color: var(--line-strong);
  border-radius: var(--radius);
  background: #ffffff;
  color: var(--text);
}

textarea {
  min-height: 112px;
  line-height: 1.45;
  resize: vertical;
}

input:hover,
select:hover,
textarea:hover {
  border-color: #8fb1ba;
}

input:focus,
select:focus,
textarea:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(8, 127, 140, 0.12);
}

.table-scroll {
  border-radius: var(--radius);
}

.compare-table,
.data-table {
  border-color: var(--line);
}

.compare-table th,
.data-table th {
  background: #f3f7f9;
  color: #51626d;
  font-size: 11px;
  letter-spacing: 0;
}

.compare-table td,
.data-table td {
  color: var(--text);
  line-height: 1.45;
  vertical-align: top;
}

.data-table tbody tr:hover td,
.compare-table tbody tr:hover td {
  background: #f8fcfd;
}

.dashboard-presentation-suite {
  border-radius: 14px;
  background:
    linear-gradient(180deg, rgba(247, 251, 252, 0.98), rgba(255, 255, 255, 0.98)),
    #ffffff;
}

.presentation-hero,
.presentation-guide,
.demo-mode-panel,
.platform-capability-map,
.presentation-agenda,
.presentation-readiness {
  border-radius: 10px;
}

.dashboard-section-nav {
  border: 1px solid rgba(184, 200, 207, 0.66);
}

.status-pill,
.nav-count,
.top-status-chip {
  letter-spacing: 0;
}

@media (min-width: 1500px) {
  .dashboard-grid {
    grid-template-columns: minmax(0, 1.45fr) minmax(360px, 0.55fr);
  }

  .panel,
  .table-panel {
    padding: clamp(18px, 1.35vw, 24px);
  }
}

@media (max-width: 1180px) {
  .app-shell {
    grid-template-columns: 260px minmax(0, 1fr);
  }

  .view {
    padding-inline: 22px;
  }
}

@media (max-width: 760px) {
  html {
    font-size: 14px;
  }

  .app-shell {
    grid-template-columns: 1fr;
  }

  .view {
    padding: 18px 14px 46px;
  }

  .topbar {
    position: static;
    display: grid;
    gap: 14px;
    padding: 16px;
  }

  .top-actions {
    justify-content: stretch;
  }

  .top-actions .primary-button,
  .top-actions .quiet-button,
  .top-actions .icon-button {
    flex: 1 1 140px;
  }
}

/* Sidebar design pass: clearer groups, calmer badges and stronger active state. */
.sidebar {
  position: sticky;
  top: 0;
  height: 100vh;
  gap: 18px;
  padding: 22px 18px;
  overflow-y: auto;
  scrollbar-gutter: stable;
  background:
    linear-gradient(180deg, #082a3f 0%, #07263a 46%, #061f31 100%);
  border-right: 1px solid rgba(111, 184, 199, 0.16);
  box-shadow: inset -1px 0 0 rgba(255, 255, 255, 0.04);
}

.sidebar::-webkit-scrollbar {
  width: 8px;
}

.sidebar::-webkit-scrollbar-track {
  background: transparent;
}

.sidebar::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(180, 218, 227, 0.22);
}

.brand {
  grid-template-columns: 52px minmax(0, 1fr);
  gap: 13px;
  min-width: 0;
  padding: 2px 4px 20px;
  border-bottom: 1px solid rgba(214, 236, 241, 0.13);
}

.brand-mark {
  width: 52px;
  height: 52px;
  border-radius: 12px;
  background: linear-gradient(135deg, #f5b64c, #ffd98b);
  color: #082235;
  font-size: 15px;
  letter-spacing: 0;
  box-shadow: 0 12px 24px rgba(0, 0, 0, 0.16);
}

.brand h1 {
  overflow: hidden;
  color: #ffffff;
  font-size: 18px;
  line-height: 1.16;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.brand p {
  max-width: 18ch;
  color: rgba(237, 249, 252, 0.66);
  font-size: 13px;
  line-height: 1.35;
}

.language-switcher {
  position: relative;
  z-index: 20;
  margin: -4px 4px 4px;
}

.language-trigger {
  display: inline-flex;
  gap: 8px;
  align-items: center;
  width: 100%;
  min-height: 40px;
  padding: 9px 11px;
  border: 1px solid rgba(214, 236, 241, 0.14);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.055);
  color: rgba(245, 251, 252, 0.86);
  cursor: pointer;
}

.language-trigger span {
  display: inline-grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border-radius: 8px;
  background: rgba(103, 215, 231, 0.14);
  color: #bff5fb;
  font-size: 15px;
  font-weight: 900;
}

.language-trigger strong {
  min-width: 0;
  overflow: hidden;
  font-size: 13px;
  font-weight: 850;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.language-trigger em {
  margin-left: auto;
  color: rgba(237, 249, 252, 0.56);
  font-size: 13px;
  font-style: normal;
}

.language-trigger:hover,
.language-trigger[aria-expanded="true"] {
  border-color: rgba(103, 215, 231, 0.28);
  background: rgba(255, 255, 255, 0.085);
  color: #ffffff;
}

.language-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  width: min(100%, 190px);
  padding: 8px;
  border: 1px solid rgba(103, 215, 231, 0.22);
  border-radius: 12px;
  background: #061a2b;
  box-shadow: 0 18px 38px rgba(0, 0, 0, 0.26);
}

.language-menu[hidden] {
  display: none;
}

.language-menu button {
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 38px;
  padding: 9px 10px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: rgba(245, 251, 252, 0.72);
  font: inherit;
  font-weight: 800;
  text-align: left;
  cursor: pointer;
}

.language-menu button:hover,
.language-menu button.active {
  background: rgba(103, 215, 231, 0.14);
  color: #ffffff;
}

.main-nav {
  gap: 0;
  padding-bottom: 18px;
}

.nav-group {
  display: grid;
  gap: 7px;
  padding: 16px 0;
  border-top: 1px solid rgba(214, 236, 241, 0.1);
}

.nav-group:first-child {
  border-top: 0;
  padding-top: 0;
}

.nav-group:last-child {
  padding-bottom: 6px;
}

.nav-group-head {
  display: flex;
  gap: 8px;
  align-items: baseline;
  justify-content: space-between;
  padding: 0 8px 3px;
}

.nav-group-label {
  color: rgba(221, 242, 247, 0.64);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.02em;
}

.nav-group-head small {
  max-width: 13ch;
  overflow: hidden;
  color: rgba(221, 242, 247, 0.36);
  font-size: 10px;
  font-weight: 700;
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.nav-button {
  position: relative;
  grid-template-columns: 30px minmax(0, 1fr) auto;
  gap: 10px;
  min-height: 44px;
  padding: 9px 10px;
  border-radius: 11px;
  color: rgba(245, 251, 252, 0.72);
}

.nav-button::before {
  content: "";
  position: absolute;
  inset: 9px auto 9px 0;
  width: 3px;
  border-radius: 999px;
  background: transparent;
}

.nav-button:hover {
  border-color: rgba(111, 217, 232, 0.16);
  background: rgba(255, 255, 255, 0.06);
  color: #ffffff;
}

.nav-button.active {
  border-color: rgba(111, 217, 232, 0.28);
  background:
    linear-gradient(90deg, rgba(13, 132, 148, 0.38), rgba(255, 255, 255, 0.06)),
    rgba(255, 255, 255, 0.04);
  color: #ffffff;
  box-shadow: none;
}

.nav-button.active::before {
  background: #67d7e7;
}

.nav-icon {
  width: 24px;
  height: 24px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.09);
  color: rgba(245, 251, 252, 0.78);
  font-size: 11px;
  font-weight: 900;
}

.nav-button.active .nav-icon {
  background: rgba(103, 215, 231, 0.18);
  color: #ffffff;
}

.nav-button > span:nth-child(2),
.nav-label {
  min-width: 0;
  overflow: hidden;
  font-size: 14px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.nav-count {
  min-width: 26px;
  max-width: 62px;
  min-height: 22px;
  padding: 4px 7px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  color: rgba(245, 251, 252, 0.76);
  font-size: 10px;
  font-weight: 900;
  line-height: 1.1;
}

.nav-count.neutral,
.nav-count.catalog {
  background: rgba(255, 255, 255, 0.11);
  color: rgba(245, 251, 252, 0.68);
}

.nav-count.progress {
  background: rgba(103, 215, 231, 0.18);
  color: #bff5fb;
}

.nav-count.warning,
.nav-count.attention {
  background: rgba(245, 182, 76, 0.22);
  color: #ffe0a7;
}

.nav-count.internal {
  background: rgba(245, 182, 76, 0.26);
  color: #ffd98b;
}

.nav-button.active .nav-count {
  background: rgba(255, 255, 255, 0.18);
  color: #ffffff;
}

.knowledge-card {
  margin-top: auto;
  border-color: rgba(214, 236, 241, 0.13);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.055);
}

.knowledge-card strong {
  color: #ffffff;
}

.knowledge-card p {
  color: rgba(237, 249, 252, 0.62);
}

@media (max-width: 760px) {
  .sidebar {
    position: relative;
    height: auto;
    max-height: 72vh;
    padding: 16px;
  }

  .brand {
    grid-template-columns: 46px minmax(0, 1fr);
    padding-bottom: 14px;
  }

  .brand-mark {
    width: 46px;
    height: 46px;
  }

  .language-switcher {
    margin: 0 0 4px;
  }

  .language-menu {
    width: 100%;
  }

  .nav-group {
    padding: 12px 0;
  }

  .nav-button {
    min-height: 42px;
  }
}

/* Topbar design pass: clearer page identity, compact context chips and calmer actions. */
.topbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: clamp(18px, 2vw, 34px);
  align-items: start;
  min-height: 92px;
  padding: 20px clamp(28px, 2.7vw, 52px);
  border-bottom: 1px solid rgba(184, 200, 207, 0.72);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(248, 251, 252, 0.9)),
    #ffffff;
  backdrop-filter: blur(14px);
}

.topbar > div:first-child {
  display: grid;
  gap: 7px;
  min-width: 0;
}

.topbar .eyebrow {
  margin: 0;
  color: #086f7a;
  font-size: 10px;
  font-weight: 950;
  line-height: 1.2;
}

.topbar h2 {
  max-width: 18ch;
  color: #0f2635;
  font-size: clamp(28px, 1.9vw, 38px);
  line-height: 1.03;
  overflow-wrap: anywhere;
}

#viewSubtitle {
  max-width: 84ch;
  margin: 0;
  color: #657683;
  font-size: 14px;
  line-height: 1.45;
}

.top-status-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 4px;
}

.top-status-chip {
  display: inline-flex;
  align-items: center;
  min-height: 27px;
  max-width: 100%;
  padding: 5px 9px;
  border: 1px solid rgba(184, 200, 207, 0.7);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.82);
  color: #445764;
  font-size: 11px;
  font-weight: 850;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.top-status-chip.mode {
  border-color: rgba(8, 127, 140, 0.22);
  background: #edf9fb;
  color: #075f69;
}

.top-status-chip.sync {
  border-color: rgba(40, 125, 75, 0.22);
  background: #edf8f2;
  color: #1d6e43;
}

.top-status-chip.review,
.top-status-chip.local {
  border-color: rgba(201, 130, 20, 0.22);
  background: #fff7e8;
  color: #81550f;
}

.top-actions {
  display: flex;
  flex: 0 0 auto;
  gap: 9px;
  justify-content: flex-end;
  padding: 6px;
  border: 1px solid rgba(184, 200, 207, 0.64);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.72);
  box-shadow: var(--shadow-soft);
}

.top-actions .icon-button,
.top-actions .file-import {
  min-height: 42px;
  padding: 9px 13px;
  border-color: rgba(184, 200, 207, 0.78);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.94);
  color: #102233;
  font-weight: 850;
  white-space: nowrap;
}

.top-actions .icon-button > span:first-child,
.top-actions .file-import > span:first-child {
  display: inline-grid;
  width: 22px;
  height: 22px;
  place-items: center;
  border-radius: 7px;
  background: #eef5f7;
  color: #075f69;
  font-size: 13px;
  font-weight: 950;
}

.top-actions .icon-button:hover,
.top-actions .file-import:hover {
  border-color: rgba(8, 127, 140, 0.32);
  background: #f6fcfd;
}

.top-actions .icon-button.active {
  border-color: rgba(8, 127, 140, 0.32);
  background: #eaf8fa;
  color: #075f69;
}

@media (max-width: 1100px) {
  .topbar {
    grid-template-columns: 1fr;
  }

  .top-actions {
    justify-content: flex-start;
    width: fit-content;
    max-width: 100%;
  }
}

@media (max-width: 760px) {
  .topbar {
    gap: 14px;
    min-height: 0;
    padding: 16px;
  }

  .topbar h2 {
    max-width: none;
    font-size: 27px;
  }

  .top-status-chip {
    max-width: 100%;
  }

  .top-actions {
    display: grid;
    width: 100%;
  }

  .top-actions .icon-button,
  .top-actions .file-import {
    width: 100%;
    justify-content: flex-start;
  }
}

/* Work surface design pass: forms, registers and tables. */
.form-grid {
  gap: 14px;
  margin: 18px 0 20px;
}

.form-grid.two {
  gap: 16px;
}

.field {
  gap: 7px;
  min-width: 0;
}

.field label,
.field > span:first-child,
.connector-actions .field span {
  color: #526672;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.015em;
  line-height: 1.25;
}

.field-help,
.soa-wizard-context label .field-help,
.soa-wizard-form label .field-help {
  margin-top: 2px;
  color: #6a7d88;
  font-size: 12px;
  font-weight: 650;
}

.field input,
.field select,
.field textarea,
.data-table input,
.data-table select,
.data-table textarea,
.document-table input,
.document-table select,
.document-table textarea {
  min-height: 44px;
  padding: 10px 12px;
  border-color: #b8c9d0;
  border-radius: 9px;
  background: #ffffff;
  color: #102233;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.82);
}

.field textarea,
.data-table textarea,
.document-table textarea {
  min-height: 116px;
}

.field input::placeholder,
.field textarea::placeholder {
  color: #7d8d96;
}

.register-form-panel {
  border-radius: 12px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(247, 251, 252, 0.96)),
    #ffffff;
}

.register-form-panel .panel-header {
  margin-bottom: 18px;
  padding-bottom: 14px;
}

.register-panel {
  border-radius: 12px;
  background: #ffffff;
  overflow: hidden;
}

.register-panel-heading {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(260px, auto);
  gap: 18px;
  align-items: center;
  padding: 20px 22px;
  background:
    linear-gradient(180deg, #ffffff, #f7fbfc),
    #ffffff;
}

.register-panel-heading h3 {
  margin: 0;
  color: #102233;
  font-size: clamp(20px, 1.3vw, 25px);
  line-height: 1.16;
}

.register-panel-heading p {
  max-width: 72ch;
  margin: 6px 0 0;
  color: #627481;
  line-height: 1.5;
}

.register-panel-kpis {
  grid-template-columns: repeat(3, minmax(92px, 1fr));
  gap: 10px;
  min-width: min(420px, 46vw);
}

.register-panel-kpis div {
  min-height: 78px;
  padding: 12px;
  border-color: rgba(184, 200, 207, 0.72);
  border-radius: 10px;
  background: #ffffff;
}

.register-panel-kpis strong {
  color: #102233;
  font-size: 26px;
}

.register-panel-kpis span {
  color: #5f707b;
  font-size: 10px;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.table-panel {
  border-radius: 12px;
}

.table-scroll {
  border-top: 1px solid rgba(216, 225, 229, 0.75);
  background: #ffffff;
}

.compare-table,
.data-table,
.register-table,
.document-table {
  border-collapse: separate;
  border-spacing: 0;
}

.compare-table th,
.data-table th,
.register-table th,
.document-table th {
  position: sticky;
  top: 0;
  z-index: 1;
  padding: 13px 12px;
  border-bottom: 1px solid #d9e4e9;
  background: #f3f8fa;
  color: #536673;
  font-size: 10px;
  font-weight: 950;
  line-height: 1.2;
  text-transform: uppercase;
}

.compare-table td,
.data-table td,
.register-table td,
.document-table td {
  padding: 13px 12px;
  border-bottom: 1px solid rgba(216, 225, 229, 0.86);
  color: #172936;
}

.data-table tbody tr:nth-child(even) td,
.register-table tbody tr:nth-child(even) td,
.document-table tbody tr:nth-child(even) td {
  background: rgba(248, 251, 252, 0.72);
}

.data-table tbody tr:hover td,
.register-table tbody tr:hover td,
.document-table tbody tr:hover td {
  background: #eef9fb;
}

.register-title-cell strong,
.register-owner-cell strong {
  font-size: 14px;
  line-height: 1.28;
}

.register-title-cell span,
.register-title-cell small,
.register-owner-cell span,
.register-date-cell span,
.register-status-stack small,
.register-evidence-cell small {
  color: #647684;
  font-size: 12px;
}

.register-date-cell,
.register-next-step {
  border-color: rgba(184, 200, 207, 0.74);
  border-radius: 9px;
  background: #ffffff;
}

.register-next-step {
  max-width: 260px;
  background: #f6fafb;
}

.badge,
.tag,
.status-pill {
  border-radius: 999px;
  letter-spacing: 0;
  line-height: 1.2;
  white-space: normal;
}

.page-action-strip,
.module-guide,
.register-customer-hub {
  border-radius: 12px;
}

.page-action-grid {
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 12px;
}

.page-action-card {
  min-height: 168px;
  border-radius: 11px;
}

@media (max-width: 1180px) {
  .form-grid,
  .risk-form {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .register-panel-heading {
    grid-template-columns: 1fr;
  }

  .register-panel-kpis {
    min-width: 0;
  }
}

@media (max-width: 760px) {
  .form-grid,
  .form-grid.two,
  .risk-form {
    grid-template-columns: 1fr;
  }

  .register-panel-heading {
    padding: 16px;
  }

  .register-panel-kpis {
    grid-template-columns: 1fr;
  }

  .table-scroll {
    margin-inline: -1px;
  }

  .compare-table th,
  .data-table th,
  .register-table th,
  .document-table th,
  .compare-table td,
  .data-table td,
  .register-table td,
  .document-table td {
    padding: 11px 10px;
  }
