}

.customer-mode-status-card small {
  color: #647684;
  line-height: 1.35;
}

.customer-mode-status-card.warning {
  border-color: rgba(201, 130, 20, 0.28);
  background: #fff8eb;
}

.customer-mode-status-card.waiting {
