.customer-simple-head,
.customer-submission-flow-head,
.guided-step-head,
.customer-mode-journey-head {
  gap: 18px;
}

.customer-simple-head h3,
.customer-submission-flow-head h3,
.guided-step-head h3,
.customer-mode-journey-head h3 {
  color: #0f2635;
  font-size: clamp(22px, 1.45vw, 30px);
  line-height: 1.12;
}

.customer-simple-grid,
.customer-mode-workboard,
.customer-mode-journey-grid,
.guided-step-grid,
.guided-task-list {
  gap: 14px;
}

.customer-simple-section,
.customer-simple-today,
.customer-mode-list-item,
.guided-task-card,
.guided-step-card,
.customer-mode-journey-step,
.customer-submission-flow-steps article {
