}

.customer-simple-row small,
.customer-mode-list-item small,
.guided-task-copy span,
.guided-task-copy small,
.guided-step-card p {
  color: #647684;
  line-height: 1.45;
}

.customer-rework-guidance {
  border-radius: 10px;
  background: #fff8eb;
  border-color: rgba(201, 130, 20, 0.2);
}

.customer-mode-detail-toggle summary {
  border-radius: 12px;
  background: #ffffff;
  box-shadow: var(--shadow-soft);
}

.customer-mode-detail-stack {
  gap: 16px;
  padding-top: 16px;
}

.customer-submission-flow-steps {
  gap: 10px;
}

.customer-submission-flow-steps article {
  min-height: 108px;
  padding: 14px;
}

.customer-submission-flow-steps article > span,
.guided-task-number,
.customer-mode-journey-step > span {
  border-radius: 10px;
  background: #e7f7fb;
  color: #087f8c;
