}

.guided-stepper {
  gap: 10px;
}

.guided-step-button {
  min-width: 190px;
  border-radius: 11px;
  background: #ffffff;
}

.guided-step-button.active {
  border-color: rgba(8, 127, 140, 0.36);
  background: #eefbfc;
}

.guided-step-navigation,
.guided-step-actions,
.customer-mode-list-actions,
.guided-task-actions,
.customer-submission-flow-actions {
  gap: 10px;
}

@media (max-width: 1280px) {
  .customer-mode-hero {
    grid-template-columns: 1fr;
  }

  .customer-mode-hero-copy h3 {
    max-width: none;
  }
}

@media (max-width: 760px) {
  .customer-mode-status-grid,
  .customer-mode-primary-steps,
  .customer-simple-grid,
  .customer-mode-workboard,
  .customer-mode-journey-grid,
  .guided-step-grid {
    grid-template-columns: 1fr;
  }

  .customer-simple-row,
  .customer-mode-list-item,
  .guided-task-card {
    grid-template-columns: 1fr;
  }

  .customer-submission-flow-actions,
  .guided-step-navigation,
  .guided-step-actions,
  .customer-mode-list-actions,
  .guided-task-actions {
    display: grid;
  }

  .customer-submission-flow-actions .primary-button,
  .customer-submission-flow-actions .quiet-button,
  .guided-step-navigation .primary-button,
  .guided-step-navigation .quiet-button,
  .guided-step-actions .primary-button,
  .guided-step-actions .quiet-button,
  .customer-mode-list-actions .primary-button,
  .customer-mode-list-actions .quiet-button,
  .guided-task-actions .primary-button,
  .guided-task-actions .quiet-button {
    width: 100%;
  }

  .guided-step-button {
    min-width: min(220px, 72vw);
  }
}

/* Review Center design pass: consultant workbench with clearer priorities and decisions. */
.review-center {
  display: grid;
  gap: 18px;
}

.review-command,
.review-priority-panel,
.review-triage-panel,
.review-sla-panel,
.review-overview-panel,
.review-filter-panel,
.review-list-panel,
.review-detail-panel,
.audit-gate-panel {
