.review-filter-head {
  gap: 18px;
}

.review-filter-head-actions {
  align-items: center;
  gap: 10px;
}

.review-filter-count {
  min-width: 86px;
  min-height: 66px;
  border-radius: 10px;
  border-color: rgba(184, 200, 207, 0.74);
  background: #ffffff;
}

.review-filter-grid {
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 12px;
}

.review-filter-grid label:first-child {
  grid-column: span 2;
}

.review-filter-grid label {
  gap: 7px;
}

.review-filter-grid span,
.review-comment-grid span {
  color: #526672;
  font-size: 11px;
  font-weight: 900;
}

.review-filter-grid input,
.review-filter-grid select,
.review-comment-grid textarea {
  border-color: #b8c9d0;
  border-radius: 9px;
}

.review-filter-actions {
  gap: 9px;
}

.review-bulk-planning {
  display: grid;
  grid-template-columns: minmax(240px, 1fr) minmax(160px, 0.34fr) auto;
  gap: 12px;
  align-items: end;
  padding: 14px;
  border: 1px solid rgba(184, 200, 207, 0.74);
  border-radius: 11px;
  background: #f7fbfc;
}

.review-bulk-planning > div,
.review-bulk-planning label {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.review-bulk-planning strong {
  color: #102233;
}

.review-bulk-planning span {
  color: #607481;
  font-size: 11px;
  line-height: 1.4;
}

.review-bulk-planning label > span {
  color: #526672;
  font-weight: 900;
}

.review-bulk-planning input {
  width: 100%;
  min-width: 0;
  min-height: 42px;
  border-color: #b8c9d0;
  border-radius: 9px;
}

.review-bulk-planning .quiet-button {
  min-height: 42px;
  white-space: nowrap;
}

.review-workload {
  display: grid;
  gap: 12px;
  margin-top: 4px;
  padding-top: 16px;
  border-top: 1px solid rgba(216, 225, 229, 0.82);
}

.review-workload-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: end;
}

.review-workload-head strong,
.review-workload-head span,
.review-workload-head small {
  display: block;
}

.review-workload-head strong {
  color: #102233;
}

.review-workload-head span,
.review-workload-head small,
.review-workload-card small,
.review-workload-empty span {
  margin-top: 3px;
  color: #607481;
  line-height: 1.35;
}

.review-workload-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 10px;
}

.review-workload-card {
  display: grid;
  gap: 5px;
  min-width: 0;
  min-height: 112px;
  padding: 13px;
  border: 1px solid rgba(184, 200, 207, 0.74);
  border-radius: 11px;
  background: #ffffff;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.review-workload-card:hover,
.review-workload-card:focus-visible {
  border-color: rgba(8, 127, 140, 0.42);
  background: #f2fbfc;
}

.review-workload-card.warning {
  border-color: rgba(201, 130, 20, 0.28);
  background: #fff9ed;
}

.review-workload-card.danger {
  border-color: rgba(168, 63, 57, 0.28);
  background: #fff5f3;
}

.review-workload-card span {
  overflow: hidden;
  color: #405661;
  font-size: 11px;
  font-weight: 900;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.review-workload-card strong {
  color: #102233;
  font-size: 27px;
  line-height: 1;
}

.review-workload-empty {
  display: grid;
  gap: 4px;
  padding: 14px;
  border: 1px dashed rgba(184, 200, 207, 0.84);
  border-radius: 11px;
  background: #f8fbfc;
}

.review-active-filter-strip {
  border-radius: 11px;
  background: #f6fafb;
}

.review-workbench {
  display: grid;
  grid-template-columns: minmax(360px, 0.95fr) minmax(420px, 1.05fr);
  gap: 18px;
  align-items: start;
}

.review-list-panel {
  overflow: hidden;
}

.review-panel-head {
  padding: 20px 20px 0;
}

.review-list {
  gap: 12px;
  padding: 18px 20px 20px;
}

.review-item {
  display: grid;
  gap: 12px;
  padding: 15px;
  border-radius: 12px;
  border-color: rgba(184, 200, 207, 0.74);
  background: #ffffff;
}

.review-item.active {
  border-color: rgba(8, 127, 140, 0.38);
  background: #eefbfc;
  box-shadow: 0 12px 30px rgba(8, 127, 140, 0.09);
}

.review-item.blocker {
  border-left: 5px solid #a83f39;
}

.review-item-main {
  gap: 8px;
}

.review-type,
.review-resubmitted-badge,
.review-queue-signal {
  border-radius: 999px;
}

.review-item-main strong {
  color: #102233;
  font-size: 16px;
  line-height: 1.22;
}

.review-item-main small,
.review-item-meta span {
  color: #647684;
  line-height: 1.38;
}

.review-item-meta {
  grid-template-columns: repeat(auto-fit, minmax(128px, 1fr));
  gap: 8px;
}

.review-item-meta span {
  display: grid;
  gap: 3px;
  min-width: 0;
  padding: 8px 9px;
  border-radius: 9px;
  background: #f5f9fa;
  overflow-wrap: anywhere;
}

.review-item-meta b {
  color: #526672;
  font-size: 9px;
  font-weight: 950;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.review-item-state {
  gap: 8px;
}

.review-item-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.review-item-actions .quiet-button {
  min-height: 34px;
  padding: 7px 10px;
  font-size: 12px;
}

.review-detail-panel {
  position: sticky;
  top: 112px;
  max-height: calc(100vh - 132px);
  overflow: auto;
}

.review-detail-head {
  gap: 14px;
  padding-bottom: 16px;
  border-bottom: 1px solid rgba(216, 225, 229, 0.78);
}

.review-detail-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.review-detail-grid div,
.review-detail-section,
.review-resubmission-note,
.review-decision-aid,
.review-planning {
  border-radius: 11px;
  border-color: rgba(184, 200, 207, 0.72);
  background: #ffffff;
}

.review-planning {
  display: grid;
  gap: 12px;
  padding: 14px;
  border: 1px solid rgba(8, 127, 140, 0.24);
  background: #f2fbfc;
}

.review-planning-head {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: flex-start;
}

.review-planning-head strong,
.review-planning-head span,
.review-planning > small {
  display: block;
}

.review-planning-head strong {
  color: #102233;
}

.review-planning-head span,
.review-planning > small {
  margin-top: 3px;
  color: #607481;
  line-height: 1.4;
}

.review-planning-grid {
  display: grid;
  grid-template-columns: minmax(180px, 1fr) minmax(150px, 0.72fr) auto;
  gap: 10px;
  align-items: end;
}

.review-planning-grid label {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.review-planning-grid label > span {
  color: #526672;
  font-size: 11px;
  font-weight: 900;
}

.review-planning-grid input {
  width: 100%;
  min-width: 0;
  min-height: 42px;
  border-color: #b8c9d0;
  border-radius: 9px;
}

.review-planning-grid .quiet-button {
  min-height: 42px;
  white-space: nowrap;
}

.review-detail-grid span,
.review-detail-section strong,
.review-aid-grid span {
  color: #526672;
  font-size: 11px;
  font-weight: 900;
}

.review-detail-grid strong,
.review-detail-section p,
.review-aid-grid strong {
  color: #102233;
  line-height: 1.42;
}

.review-decision-aid {
  background:
    linear-gradient(180deg, #ffffff, #f7fbfc),
    #ffffff;
}

.review-aid-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.review-aid-grid article {
  border-radius: 10px;
}

.review-comment-grid {
  gap: 12px;
}

.review-comment-grid textarea {
  min-height: 128px;
}

.review-comment-savebar {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: center;
  padding: 11px 12px;
  border: 1px solid rgba(184, 200, 207, 0.72);
  border-radius: 10px;
  background: #f7fbfc;
}

.review-comment-savebar span {
  color: #607481;
  font-size: 11px;
  line-height: 1.4;
}

.review-comment-savebar .quiet-button {
  flex: 0 0 auto;
  min-height: 38px;
  white-space: nowrap;
}

.review-decision-bar {
  position: sticky;
  bottom: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  padding: 12px 0 0;
  border-top: 1px solid rgba(216, 225, 229, 0.78);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.82), #ffffff 35%);
}

.review-history-section,
.review-history-entry {
  border-radius: 11px;
}

@media (max-width: 1280px) {
  .review-triage-grid {
    grid-template-columns: repeat(2, minmax(260px, 1fr));
  }

  .review-sla-head,
  .review-sla-grid {
    grid-template-columns: 1fr;
  }

  .review-workbench {
    grid-template-columns: 1fr;
  }

  .review-detail-panel {
    position: static;
    max-height: none;
  }
}

@media (max-width: 760px) {
  .review-command .panel-header,
  .review-triage-head,
  .review-filter-head {
    display: grid;
  }

  .review-gate-badge,
  .review-filter-head-actions {
    width: 100%;
  }

  .review-header-cards,
  .review-priority-grid,
  .review-triage-grid,
  .review-sla-kpis,
  .review-filter-grid,
  .review-detail-grid,
  .review-aid-grid,
  .review-item-meta {
    grid-template-columns: 1fr;
  }

  .review-item-actions,
  .review-triage-actions,
  .review-decision-bar,
  .review-filter-actions {
    display: grid;
  }

  .review-planning-head,
  .review-planning-grid,
  .review-bulk-planning,
  .review-workload-head,
  .review-comment-savebar {
    display: grid;
    grid-template-columns: 1fr;
  }

  .review-filter-grid label:first-child {
    grid-column: auto;
  }

  .review-item-actions .quiet-button,
  .review-triage-actions .quiet-button,
  .review-decision-bar .primary-button,
  .review-decision-bar .quiet-button,
  .review-filter-actions .quiet-button {
    width: 100%;
  }

  .review-planning-grid .quiet-button {
    width: 100%;
  }

  .review-bulk-planning .quiet-button {
    width: 100%;
  }

  .review-comment-savebar .quiet-button {
    width: 100%;
  }
}

/* Enterprise SaaS design pass: calmer hierarchy, less visual noise, more premium spacing. */
:root {
  --bg: #f6f8fa;
  --surface: #ffffff;
  --surface-soft: #f7f9fb;
  --line: #e3e8ee;
  --line-strong: #cad3dc;
  --text: #111827;
  --muted: #687385;
  --accent: #256f7a;
  --accent-dark: #1d5962;
  --green: #23704d;
  --gold: #9d6b1a;
  --danger: #a0443e;
  --radius: 10px;
  --sfm-radius-sm: 8px;
  --sfm-radius-md: 10px;
  --shadow: 0 18px 42px rgba(15, 23, 42, 0.08);
  --shadow-soft: 0 1px 2px rgba(15, 23, 42, 0.06), 0 10px 28px rgba(15, 23, 42, 0.045);
}

body {
  background: #f6f8fa;
  color: var(--text);
  font-size: 14px;
  line-height: 1.5;
}

.app-shell {
  grid-template-columns: 292px minmax(0, 1fr);
}

.sidebar {
  background:
    linear-gradient(180deg, #17202a 0%, #111827 100%);
  border-right: 1px solid rgba(255, 255, 255, 0.06);
  box-shadow: none;
}

.brand {
  gap: 12px;
  padding-bottom: 20px;
}

.brand-mark {
  width: 42px;
  height: 42px;
  border-radius: 10px;
  background: #f6c267;
  color: #111827;
  font-weight: 900;
  box-shadow: none;
}

.brand h1 {
  font-size: 17px;
  letter-spacing: 0;
}

.brand p {
  max-width: 18ch;
  color: rgba(255, 255, 255, 0.58);
  font-size: 13px;
  line-height: 1.35;
}

.language-switcher,
.knowledge-card {
  border-color: rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.045);
  box-shadow: none;
}

.knowledge-card {
  padding: 14px;
}

.knowledge-card .eyebrow,
.nav-group-label {
  color: rgba(255, 255, 255, 0.4);
  font-size: 10px;
  letter-spacing: 0;
}

.nav-group {
  gap: 3px;
  padding-block: 14px;
}

.nav-button {
  min-height: 38px;
  padding: 8px 10px;
  border-radius: 9px;
  color: rgba(255, 255, 255, 0.66);
  font-weight: 750;
}

.nav-button:hover {
  background: rgba(255, 255, 255, 0.055);
  border-color: transparent;
  color: rgba(255, 255, 255, 0.9);
}

.nav-button.active {
  background: rgba(255, 255, 255, 0.095);
  border-color: rgba(255, 255, 255, 0.08);
  color: #ffffff;
  box-shadow: inset 2px 0 0 #7ec9d2;
}

.nav-icon {
  width: 24px;
  height: 24px;
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.72);
}

.nav-button.active .nav-icon {
  background: rgba(126, 201, 210, 0.18);
  color: #bcecf2;
}

.nav-count {
  min-width: 24px;
  height: 22px;
  padding: 0 7px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.72);
  font-size: 11px;
  font-weight: 750;
}

.nav-button.active .nav-count {
  background: rgba(126, 201, 210, 0.14);
  color: #d7f7fa;
}

.main {
  background: #f6f8fa;
}

.topbar {
  min-height: 88px;
  padding: 22px 38px 18px;
  background: rgba(255, 255, 255, 0.92);
  border-bottom: 1px solid #e8edf2;
  box-shadow: 0 1px 0 rgba(15, 23, 42, 0.02);
}

.topbar h2 {
  color: #101820;
  font-size: clamp(28px, 2.4vw, 40px);
  font-weight: 780;
  line-height: 1.08;
}

.topbar p {
  max-width: 72ch;
  margin-top: 7px;
  color: var(--muted);
  font-size: 14px;
  font-weight: 600;
}

.eyebrow {
  color: var(--accent-dark);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.view {
  width: min(100%, 1500px);
  padding: 32px 40px 56px;
}

.panel,
.table-panel,
.requirement-panel,
.metric-card,
.management-score-card,
.management-compliance-card,
.management-board-card,
.dashboard-curated-card,
.dashboard-executive-card {
  border: 1px solid #e2e8ef;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: var(--shadow-soft);
}

.panel,
.requirement-panel {
  padding: 24px;
}

.panel-header h3,
.table-panel h3,
.requirement-panel h3 {
  color: #111827;
  font-size: 18px;
  font-weight: 760;
  letter-spacing: 0;
}

.panel-header p,
.requirement-panel p,
.table-panel p {
  color: var(--muted);
  font-size: 14px;
  line-height: 1.5;
}

.primary-button,
.quiet-button,
.danger-button,
.icon-button {
  min-height: 38px;
  border-radius: 9px;
  font-size: 13px;
  font-weight: 760;
  letter-spacing: 0;
}

.primary-button {
  border-color: #1f6b75;
  background: #1f6b75;
  color: #ffffff;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.08);
}

.primary-button:hover {
  border-color: #175760;
  background: #175760;
  transform: translateY(-1px);
}

.quiet-button,
.icon-button {
  border-color: #d9e2ea;
  background: #ffffff;
  color: #17212b;
}

.quiet-button:hover,
.icon-button:hover {
  border-color: #c6d2dc;
  background: #f8fafc;
  transform: translateY(-1px);
}

.danger-button {
  border-color: rgba(160, 68, 62, 0.22);
  background: #fffafa;
  color: #8f3832;
}

.badge,
.tag,
.scope-badge,
.status-pill {
  min-height: 24px;
  padding: 4px 9px;
  border: 1px solid #dde6ee;
  border-radius: 999px;
  background: #f7fafc;
  color: #52606f;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: none;
}

.badge.must,
.tag.must,
.badge.should,
.tag.should {
  border-color: #ecd7bd;
  background: #fff8ef;
  color: #8a5f23;
}

.badge.practice,
.tag.practice {
  border-color: #cfe5d7;
  background: #f3faf6;
  color: #286848;
}

.dashboard-curated-home {
  display: grid;
  gap: 24px;
  margin-bottom: 22px;
  padding: 28px;
  border: 1px solid #e2e8ef;
  background: #ffffff;
}

.dashboard-curated-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 24px;
  align-items: end;
}

.dashboard-curated-head h3 {
  margin: 0;
  color: #101820;
  font-size: clamp(28px, 2.8vw, 44px);
  font-weight: 780;
  line-height: 1.06;
}

.dashboard-curated-head p {
  max-width: 78ch;
  margin: 10px 0 0;
  color: var(--muted);
  font-size: 15px;
  line-height: 1.55;
}

.dashboard-curated-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(92px, 1fr));
  gap: 10px;
}

.dashboard-curated-summary span {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 12px 14px;
  border: 1px solid #e2e8ef;
  border-radius: 10px;
  background: #f8fafc;
}

.dashboard-curated-summary strong {
  color: #111827;
  font-size: 24px;
  line-height: 1;
}

.dashboard-curated-summary small {
  color: var(--muted);
  font-size: 11px;
  font-weight: 760;
}

.dashboard-curated-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.dashboard-curated-card {
  display: grid;
  gap: 12px;
  min-height: 210px;
  padding: 18px;
  box-shadow: none;
}

.dashboard-curated-card:first-child {
  border-color: #cfe1e5;
  background: #fbfefe;
}

.dashboard-curated-card.warning,
.dashboard-curated-card.danger {
  border-color: #ead8c4;
  background: #fffdf9;
}

.dashboard-curated-card.done {
  border-color: #d6e7dd;
}

.dashboard-curated-card-top {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: center;
}

.dashboard-curated-card-top span,
.dashboard-curated-card-foot small {
  color: #667085;
  font-size: 12px;
  font-weight: 720;
  text-transform: none;
}

.dashboard-curated-card-top strong {
  color: #111827;
  font-size: 26px;
  line-height: 1;
}

.dashboard-curated-card h4 {
  margin: 0;
  color: #111827;
  font-size: 18px;
  font-weight: 760;
  line-height: 1.22;
}

.dashboard-curated-card p {
  margin: 0;
  color: var(--muted);
  line-height: 1.5;
}

.dashboard-curated-card-foot {
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
}

.dashboard-curated-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  padding-top: 4px;
}

.dashboard-details {
  border: 1px solid #e2e8ef;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: none;
}

.dashboard-details summary {
  min-height: 56px;
  padding: 14px 16px;
}

.dashboard-details summary strong {
  color: #182230;
  font-weight: 760;
}

.dashboard-details summary small {
  color: var(--muted);
  font-weight: 500;
}

.dashboard-details summary em {
  border: 1px solid #d9e2ea;
  background: #f8fafc;
  color: #536171;
  font-style: normal;
}

.dashboard-section {
  margin-top: 24px;
}

.dashboard-section-head {
  margin-bottom: 14px;
}

.dashboard-section-head h3 {
  font-size: 24px;
  font-weight: 760;
}

.executive-cockpit {
  gap: 22px;
  padding: 26px;
}

.dashboard-executive-main {
  grid-template-columns: minmax(0, 1fr) minmax(220px, 300px);
  gap: 24px;
  align-items: stretch;
}

.dashboard-executive-main h3 {
  margin: 0;
  color: #101820;
  font-size: clamp(26px, 2.2vw, 36px);
  font-weight: 780;
  line-height: 1.1;
}

.dashboard-executive-main p {
  max-width: 78ch;
  color: var(--muted);
}

.dashboard-executive-status {
  display: grid;
  align-content: center;
  gap: 8px;
  padding: 18px;
  border: 1px solid #e2e8ef;
  border-radius: 12px;
  background: #f8fafc;
}

.dashboard-executive-status span {
  color: #52606f;
  font-size: 12px;
  font-weight: 780;
  text-transform: none;
}

.dashboard-executive-status strong {
  color: #111827;
  font-size: 20px;
}

.dashboard-executive-status small {
  color: var(--muted);
  line-height: 1.4;
}

.dashboard-executive-status.red {
  border-color: #ead1cc;
  background: #fffafa;
}

.dashboard-executive-status.yellow {
  border-color: #ead8c4;
  background: #fffbf5;
}

.dashboard-executive-status.green {
  border-color: #d6e7dd;
  background: #fbfefc;
}

.dashboard-executive-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.dashboard-executive-card {
  min-height: 126px;
  padding: 16px;
  box-shadow: none;
  text-align: left;
}

.dashboard-executive-card.warning,
.dashboard-executive-card.active,
.dashboard-executive-card.done {
  background: #ffffff;
}

.dashboard-executive-card span {
  color: #667085;
  font-size: 12px;
  font-weight: 720;
  text-transform: none;
}

.dashboard-executive-card strong {
  margin-top: 12px;
  color: #111827;
  font-size: 28px;
  font-weight: 780;
  line-height: 1.05;
}

.dashboard-executive-card small {
  margin-top: 8px;
  color: var(--muted);
}

.executive-cockpit-board,
.executive-cockpit-bottom {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.executive-cockpit-list,
.executive-traces,
.executive-deadlines {
  display: grid;
  align-content: start;
  gap: 10px;
  min-width: 0;
  padding: 16px;
  border: 1px solid #e2e8ef;
  border-radius: 12px;
  background: #ffffff;
}

.executive-cockpit-list-head {
  display: flex;
  gap: 12px;
  justify-content: space-between;
  align-items: baseline;
  padding-bottom: 6px;
}

.executive-cockpit-list-head strong {
  color: #111827;
  font-size: 15px;
  font-weight: 760;
}

.executive-cockpit-list-head span {
  color: var(--muted);
  font-size: 12px;
  font-weight: 650;
}

.executive-cockpit-row,
.executive-trace-row,
.executive-deadline-lane button {
  display: grid;
  width: 100%;
  min-width: 0;
  gap: 4px;
  padding: 12px;
  border: 1px solid #e4eaf0;
  border-radius: 10px;
  background: #fbfcfd;
  color: #111827;
  text-align: left;
}

.executive-cockpit-row:hover,
.executive-trace-row:hover,
.executive-deadline-lane button:hover {
  border-color: #ccd6df;
  background: #ffffff;
}

.executive-cockpit-row span,
.executive-deadline-lane > span {
  color: #697586;
  font-size: 11px;
  font-weight: 760;
}

.executive-cockpit-row strong,
.executive-deadline-lane strong {
  color: #111827;
  font-size: 14px;
  font-weight: 720;
  line-height: 1.3;
}

.executive-cockpit-row small,
.executive-deadline-lane small {
  color: var(--muted);
  line-height: 1.4;
}

.executive-empty {
  padding: 18px;
  border: 1px dashed #d8e1e9;
  border-radius: 10px;
  background: #fbfcfd;
  color: var(--muted);
}

.executive-trace-row {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
}

.executive-trace-row span {
  color: #111827;
  font-weight: 720;
}

.executive-trace-row strong {
  color: #52606f;
  font-size: 13px;
  font-weight: 760;
}

.executive-deadlines {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.executive-deadlines .executive-cockpit-list-head {
  grid-column: 1 / -1;
}

.executive-deadline-lane {
  display: grid;
  align-content: start;
  gap: 8px;
  min-width: 0;
}

.dashboard-executive-action {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 16px;
  align-items: center;
  padding: 16px;
  border: 1px solid #e2e8ef;
  border-radius: 12px;
  background: #fbfcfd;
}

.dashboard-executive-action strong {
  color: #111827;
  font-size: 18px;
  font-weight: 760;
}

.dashboard-executive-action p {
  margin: 5px 0 0;
  color: var(--muted);
}

.dashboard-executive-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.empty-state,
.product-empty-state,
.management-empty,
.register-empty-state {
  border: 1px dashed #d8e1e9;
  border-radius: 12px;
  background: #fbfcfd;
  box-shadow: none;
}

.product-empty-state .empty-state-mark {
  background: #eef3f7;
  color: #536171;
}

@media (max-width: 1280px) {
  .dashboard-curated-grid,
  .dashboard-executive-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .dashboard-executive-main,
  .dashboard-executive-action,
  .executive-cockpit-board,
  .executive-cockpit-bottom {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 920px) {
  .app-shell {
    grid-template-columns: 1fr;
  }

  .sidebar {
    position: static;
    height: auto;
  }

  .view {
    padding: 22px;
  }

  .dashboard-curated-head,
  .dashboard-curated-summary,
  .dashboard-curated-grid,
  .dashboard-executive-grid,
  .executive-deadlines {
    grid-template-columns: 1fr;
  }

  .dashboard-curated-card {
    min-height: 0;
  }

  .dashboard-executive-buttons,
  .dashboard-curated-actions {
    display: grid;
    grid-template-columns: 1fr;
  }
}

