  position: sticky;
  top: 104px;
  max-height: calc(100vh - 128px);
  overflow: auto;
  padding-right: 2px;
}

.split-layout:has(.template-list) .list-panel .panel,
.split-layout:has(.template-list) .requirement-panel {
  border-radius: 16px;
  border-color: rgba(184, 200, 207, 0.72);
  box-shadow: 0 16px 38px rgba(17, 44, 56, 0.06);
}

.template-list,
.draft-list {
  gap: 9px;
}

.template-library-toolbar {
  display: grid;
  grid-template-columns: minmax(220px, 1fr);
  gap: 10px;
  margin: 14px 0 12px;
  padding: 12px;
  border: 1px solid rgba(207, 219, 225, 0.82);
  border-radius: 14px;
  background: #f7fbfc;
}

.template-library-search {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.template-library-search span {
  color: #526672;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.template-library-search input {
  width: 100%;
  min-height: 40px;
  padding: 9px 11px;
  border: 1px solid #b8c9d0;
  border-radius: 10px;
  background: #ffffff;
  color: var(--text);
  font: inherit;
}

.template-library-search input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 4px rgba(11, 127, 141, 0.11);
  outline: 0;
}

.template-library-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.template-library-filters button {
  min-height: 30px;
  padding: 5px 10px;
  border: 1px solid rgba(184, 200, 207, 0.86);
  border-radius: 999px;
  background: #ffffff;
  color: #526672;
  font-size: 12px;
  font-weight: 850;
  cursor: pointer;
}

.template-library-filters button:hover,
.template-library-filters button.active {
  border-color: rgba(8, 127, 140, 0.36);
  background: #e9f8fa;
  color: #0b6e7c;
}

.template-library-result-count {
  justify-self: start;
  padding: 5px 10px;
  border-radius: 999px;
  background: #eaf3f5;
  color: #274756;
  font-size: 11px;
  font-weight: 850;
}

.template-library-empty {
  display: grid;
  gap: 8px;
  justify-items: start;
  padding: 16px;
  border: 1px dashed rgba(149, 174, 185, 0.8);
  border-radius: 14px;
  background: #fbfdfe;
  color: #617583;
}

.template-library-empty strong {
  color: #102233;
}

.template-library-group {
  display: grid;
  gap: 10px;
  padding: 12px;
  border: 1px solid rgba(207, 219, 225, 0.82);
  border-radius: 14px;
  background: #fbfdfe;
}

.template-library-group + .template-library-group {
  margin-top: 12px;
}

.template-library-group-head {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  justify-content: space-between;
  min-width: 0;
}

.template-library-group-head div {
  min-width: 0;
}

.template-library-group-head strong,
.template-library-group-head span {
  display: block;
  min-width: 0;
  overflow-wrap: anywhere;
}

.template-library-group-head strong {
  color: #102233;
  font-size: 13px;
  line-height: 1.25;
}

.template-library-group-head span {
  margin-top: 4px;
  color: #617583;
  font-size: 12px;
  line-height: 1.35;
}

.template-library-group-head small {
  flex: 0 0 auto;
  min-width: 42px;
  padding: 5px 9px;
  border-radius: 999px;
  background: #eaf3f5;
  color: #274756;
  font-size: 11px;
  font-weight: 850;
  text-align: center;
}

.template-library-group-list {
  display: grid;
  gap: 8px;
}

.template-review-queue {
  display: grid;
  gap: 14px;
  margin-bottom: 18px;
}

.template-review-queue-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 16px;
  align-items: start;
}

.template-review-queue-head h3,
.template-review-queue-head p {
  max-width: 820px;
}

.template-review-queue-summary {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.template-review-queue-summary span {
  min-width: 94px;
  padding: 9px 11px;
  border: 1px solid rgba(207, 219, 225, 0.82);
  border-radius: 10px;
  background: #ffffff;
  color: #617583;
  font-size: 12px;
  line-height: 1.25;
}

.template-review-queue-summary b {
  display: block;
  color: #102233;
  font-size: 18px;
}

.template-review-queue-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 10px;
}

.template-review-card {
  display: grid;
  gap: 12px;
  align-content: start;
  min-width: 0;
  padding: 14px;
  border: 1px solid rgba(184, 200, 207, 0.78);
  border-radius: 14px;
  background: #ffffff;
}

.template-review-card.active {
  border-color: rgba(8, 127, 140, 0.32);
  box-shadow: 0 10px 24px rgba(8, 127, 140, 0.08);
}

.template-review-card.warning {
  border-color: rgba(214, 133, 16, 0.34);
  background: #fff9ef;
}

.template-review-card.active:not(.warning) {
  background: #f3fbfc;
}

.template-review-card span,
.template-review-card strong,
.template-review-card p,
.template-review-card small {
  display: block;
  min-width: 0;
  overflow-wrap: anywhere;
}

.template-review-card > div > span {
  color: #0b6e7c;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.template-review-card.warning > div > span {
  color: #9c5d08;
}

.template-review-card strong {
  margin-top: 5px;
  color: #102233;
  font-size: 15px;
  line-height: 1.25;
}

.template-review-card p,
.template-review-card small {
  margin-top: 6px;
  color: #617583;
  line-height: 1.42;
}

.template-review-card small {
  color: #805008;
  font-weight: 760;
}

.template-review-card-meta {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.template-review-card-meta span {
  padding: 8px 9px;
  border: 1px solid rgba(207, 219, 225, 0.82);
  border-radius: 10px;
  background: #ffffff;
  color: #617583;
  font-size: 12px;
}

.template-review-card-meta b {
  display: block;
  color: #102233;
  line-height: 1.3;
}

.template-review-card-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.template-completion-check {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  margin: 14px 0 18px;
  padding: 15px;
  border: 1px solid rgba(184, 200, 207, 0.78);
  border-radius: 14px;
  background: #fbfdfe;
}

.template-completion-check.missing {
  border-color: rgba(214, 133, 16, 0.32);
  background: #fff9ef;
}

.template-completion-check.complete {
  border-color: rgba(30, 128, 74, 0.24);
  background: #f1fbf5;
}

.template-completion-check strong,
.template-completion-check p,
.template-completion-note {
  display: block;
  min-width: 0;
  overflow-wrap: anywhere;
}

.template-completion-check strong {
  color: #102233;
  font-size: 18px;
  line-height: 1.2;
}

.template-completion-check p,
.template-completion-note {
  margin-top: 5px;
  color: #617583;
  line-height: 1.42;
}

.template-completion-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(92px, 1fr));
  gap: 8px;
  min-width: 320px;
}

.template-completion-metrics span,
.template-missing-fields span {
  display: block;
  padding: 9px 10px;
  border: 1px solid rgba(207, 219, 225, 0.82);
  border-radius: 10px;
  background: #ffffff;
  color: #617583;
  font-size: 12px;
  line-height: 1.3;
}

.template-completion-metrics b {
  display: block;
  color: #102233;
  font-size: 16px;
}

.template-missing-fields {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.template-missing-fields span {
  border-color: rgba(214, 133, 16, 0.24);
  background: #ffffff;
  color: #805008;
  font-weight: 800;
}

.template-list .requirement-button,
.draft-button {
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  min-height: 68px;
  padding: 14px;
  border-color: rgba(184, 200, 207, 0.72);
  border-radius: 13px;
  background: #ffffff;
}

.template-list .requirement-button:hover,
.template-list .requirement-button.active,
.draft-button:hover,
.draft-button.active {
  border-color: rgba(8, 127, 140, 0.4);
  background: #f1fbfc;
  box-shadow: 0 10px 24px rgba(8, 127, 140, 0.08);
}

.template-list .requirement-button strong,
.draft-button strong {
  color: #102233;
  line-height: 1.22;
}

.template-list .requirement-button span span,
.draft-button small {
  color: #617583;
  line-height: 1.38;
}

.template-library-button-meta {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 7px;
  min-width: 104px;
}

.template-status-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 23px;
  padding: 3px 9px;
  border-radius: 999px;
  background: #e9eef2;
  color: #536a76;
  font-size: 11px;
  font-weight: 850;
  white-space: nowrap;
}

.template-status-pill.active {
  background: #e7f5f7;
  color: #0b6e7c;
}

.template-status-pill.review {
  background: #fff3d8;
  color: #805008;
}

.template-status-pill.warning {
  background: #fdecea;
  color: #9c342e;
}

.template-status-pill.done {
  background: #e6f5ec;
  color: #217145;
}

.template-layout {
  grid-template-columns: minmax(360px, 0.92fr) minmax(420px, 1.08fr);
  gap: 18px;
  align-items: start;
}

.template-form {
  gap: 12px;
  padding: 16px;
  border: 1px solid rgba(184, 200, 207, 0.72);
  border-radius: 14px;
  background: #f8fbfc;
}

.template-form .field {
  padding: 12px;
  border: 1px solid rgba(216, 226, 231, 0.86);
  border-radius: 12px;
  background: #ffffff;
}

.template-field-guidance {
  display: grid;
  gap: 5px;
  margin: -1px 0 3px;
  padding: 9px 10px;
  border: 1px solid rgba(215, 226, 231, 0.78);
  border-radius: 10px;
  background: #f7fbfc;
  color: #627783;
  font-size: 12px;
  line-height: 1.42;
}

.template-field-guidance strong {
  color: #334c5a;
  font-weight: 850;
}

.template-form .field label,
.draft-editor .field label {
  color: #526672;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

.template-form .field input,
.template-form .field select,
.template-form .field textarea,
.draft-editor input,
.draft-editor select,
.draft-editor textarea {
  border-color: #b8c9d0;
  border-radius: 10px;
}

.template-form .field textarea {
  min-height: 168px;
  line-height: 1.45;
}

.template-preview {
  position: sticky;
  top: 104px;
  padding: 18px;
  border-color: rgba(184, 200, 207, 0.72);
  border-radius: 14px;
  background: #ffffff;
  box-shadow: 0 14px 34px rgba(17, 44, 56, 0.06);
}

.template-preview pre {
  max-height: 620px;
  padding: 16px;
  border-color: rgba(216, 226, 231, 0.9);
  border-radius: 12px;
  background: #fbfdfe;
  color: #172c3a;
  font-size: 13px;
  line-height: 1.55;
}

.draft-editor-grid {
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 12px;
}

.draft-editor .field {
  padding: 12px;
  border: 1px solid rgba(216, 226, 231, 0.86);
  border-radius: 12px;
  background: #f9fcfd;
}

.template-draft-review-panel {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(260px, 0.72fr);
  gap: 14px;
  align-items: center;
  margin: 0 0 16px;
  padding: 14px;
  border: 1px solid rgba(184, 200, 207, 0.78);
  border-radius: 14px;
  background: #fbfdfe;
}

.template-draft-review-panel.active {
  border-color: rgba(8, 127, 140, 0.26);
  background: #f2fbfc;
}

.template-draft-review-panel.warning {
  border-color: rgba(214, 133, 16, 0.32);
  background: #fff9ef;
}

.template-draft-review-panel.done {
  border-color: rgba(30, 128, 74, 0.24);
  background: #f1fbf5;
}

.template-draft-review-panel strong,
.template-draft-review-panel p,
.template-draft-review-panel small {
  display: block;
  min-width: 0;
  overflow-wrap: anywhere;
}

.template-draft-review-panel strong {
  color: #102233;
  font-size: 17px;
  line-height: 1.22;
}

.template-draft-review-panel p,
.template-draft-review-panel small {
  margin-top: 5px;
  color: #617583;
  line-height: 1.42;
}

.template-draft-review-panel small {
  color: #805008;
  font-weight: 750;
}

.template-draft-review-facts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.template-draft-review-facts span {
  display: block;
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid rgba(207, 219, 225, 0.82);
  border-radius: 10px;
  background: #ffffff;
  color: #617583;
  font-size: 12px;
  line-height: 1.32;
  overflow-wrap: anywhere;
}

.template-draft-review-facts b {
  display: block;
  color: #102233;
  font-size: 13px;
}

.draft-editor .field.full {
  grid-column: 1 / -1;
}

.draft-content-editor {
  min-height: 560px;
  border-radius: 12px;
  background: #fbfdfe;
}

@media (max-width: 1320px) {
  .policy-control-center,
  .policy-detail-layout,
  .policy-guide,
  .template-layout,
  .split-layout:has(.template-list) {
    grid-template-columns: 1fr;
  }

  .policy-detail-side,
  .template-preview,
  .split-layout:has(.template-list) .list-panel {
    position: static;
    max-height: none;
  }
}

@media (max-width: 820px) {
  .policy-control-metrics,
  .policy-quick-grid,
  .policy-package-sections,
  .policy-package-list,
  .policy-package-grid,
  .policy-detail-facts,
  .policy-detail-form-grid,
  .policy-guide-grid,
  .template-form,
  .template-review-queue-head,
  .template-completion-check,
  .template-draft-review-panel,
  .draft-editor-grid {
    grid-template-columns: 1fr;
  }

  .template-review-queue-summary {
    justify-content: flex-start;
  }

  .template-review-card-meta {
    grid-template-columns: 1fr;
  }

  .policy-package-chip {
    grid-template-columns: 1fr;
  }

  .policy-command-card {
    min-height: 0;
  }

  .policy-mini-table-head {
    display: none;
  }

  .policy-mini-row {
    grid-template-columns: 38px minmax(0, 1fr);
  }

  .policy-mini-row strong:nth-of-type(1),
  .policy-mini-row strong:nth-of-type(2) {
    display: none;
  }

  .policy-auth-list div {
    grid-template-columns: 34px minmax(0, 1fr);
  }

  .policy-auth-list em {
    grid-column: 2;
  }

  .policy-quick-grid label.full {
    grid-column: auto;
  }

  .policy-package-chip-open {
    justify-content: center;
    width: calc(100% - 4px);
  }

  .policy-detail-form label.wide,
  .policy-detail-form label.full,
  .draft-editor .field.full {
    grid-column: auto;
  }

  .policy-detail-head-actions,
  .policy-detail-actions,
  .policy-actions,
  .template-form .inline-actions,
  .draft-editor .inline-actions {
    display: grid;
    width: 100%;
  }

  .template-library-button {
    grid-template-columns: 1fr;
  }

  .template-library-button-meta {
    align-items: flex-start;
    min-width: 0;
  }

  .template-completion-metrics {
    grid-template-columns: 1fr;
    min-width: 0;
  }

  .template-draft-review-facts {
    grid-template-columns: 1fr;
  }

  .policy-detail-head-actions .primary-button,
  .policy-detail-head-actions .quiet-button,
  .policy-detail-actions .primary-button,
  .policy-detail-actions .quiet-button,
  .template-form .primary-button,
  .template-form .quiet-button,
  .draft-editor .primary-button,
  .draft-editor .quiet-button {
    width: 100%;
  }
}

/* Risk workbench design pass: simple enough for customers, useful for consultants. */
.risk-workshop-panel,
.risk-board-panel,
.risk-focus-panel,
.risk-methodology-panel,
.risk-decision-center,
.risk-treatment-plan,
.risk-acceptance-panel,
.risk-review-panel,
.risk-traceability-panel,
.risk-effectiveness-panel,
.risk-register-panel,
.soc-risk-panel {
  border-color: rgba(184, 200, 207, 0.72);
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 18px 44px rgba(17, 44, 56, 0.07);
}

.risk-focus-panel {
  display: grid;
  gap: 16px;
  background:
    linear-gradient(135deg, #ffffff 0%, #f2fbfc 56%, #eef8fa 100%),
    #ffffff;
}

.risk-focus-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 0.42fr);
  gap: 18px;
  align-items: stretch;
}

.risk-focus-head h3 {
  margin: 3px 0 7px;
  color: #102233;
  font-size: clamp(26px, 2.3vw, 38px);
  line-height: 1.08;
}

.risk-focus-head p {
  max-width: 92ch;
  margin: 0;
  color: #617583;
  line-height: 1.55;
}

.risk-focus-primary {
  display: grid;
  gap: 8px;
  align-content: start;
  min-width: 0;
  padding: 16px;
  border: 1px solid rgba(8, 127, 140, 0.2);
  border-radius: 14px;
  background: #ffffff;
  box-shadow: 0 14px 30px rgba(17, 44, 56, 0.07);
}

.risk-focus-primary span {
  color: #087f8c;
  font-size: 11px;
  font-weight: 950;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.risk-focus-primary strong {
  color: #102233;
  font-size: 18px;
  line-height: 1.2;
}

.risk-focus-primary p {
  color: #526672;
  font-size: 13px;
  line-height: 1.45;
}

.risk-focus-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 10px;
}

.risk-focus-card {
  display: grid;
  gap: 5px;
  min-width: 0;
  min-height: 102px;
  padding: 14px;
  border: 1px solid rgba(184, 200, 207, 0.72);
  border-radius: 13px;
  background: #ffffff;
  text-align: left;
  cursor: pointer;
  transition: transform 0.16s ease, border-color 0.16s ease, box-shadow 0.16s ease;
}

.risk-focus-card:hover {
  transform: translateY(-1px);
  border-color: rgba(8, 127, 140, 0.34);
  box-shadow: 0 14px 26px rgba(17, 44, 56, 0.08);
}

.risk-focus-card.danger {
  border-color: rgba(168, 63, 57, 0.3);
  background: #fff5f3;
}

.risk-focus-card.warning {
  border-color: rgba(201, 130, 20, 0.3);
  background: #fff8eb;
}

.risk-focus-card.active {
  border-color: rgba(8, 127, 140, 0.28);
  background: #eefbfc;
}

.risk-focus-card.done {
  border-color: rgba(64, 150, 96, 0.24);
  background: #f5fbf7;
}

.risk-focus-card strong {
  color: #102233;
  font-size: 30px;
  line-height: 1;
}

.risk-focus-card span,
.risk-focus-card small {
  color: #526672;
  font-size: 11px;
  font-weight: 900;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.risk-focus-shortcuts {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding-top: 2px;
}

.risk-focus-shortcuts .quiet-button {
  min-height: 36px;
  padding: 7px 12px;
}

.risk-methodology-panel {
  display: grid;
  gap: 16px;
  background:
    linear-gradient(135deg, #ffffff 0%, #f8fcfd 58%, #eef8fa 100%),
    #ffffff;
}

.risk-methodology-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: start;
}

.risk-methodology-head h3 {
  margin: 3px 0 7px;
  color: #102233;
  font-size: clamp(24px, 2.1vw, 34px);
  line-height: 1.1;
}

.risk-methodology-head p {
  max-width: 90ch;
  margin: 0;
  color: #617583;
  line-height: 1.55;
}

.risk-methodology-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 9px;
}

.risk-methodology-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.risk-methodology-kpis article {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 14px;
  border: 1px solid rgba(184, 200, 207, 0.72);
  border-radius: 13px;
