.dashboard-activity-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 4px 10px;
  min-width: 0;
  min-height: 92px;
  padding: 12px;
  border: 1px solid rgba(216, 226, 231, 0.92);
  border-radius: 10px;
  background: #ffffff;
  color: var(--text);
  text-align: left;
  transition:
    border-color 140ms ease,
    background-color 140ms ease,
    box-shadow 140ms ease;
}

.dashboard-activity-item:hover {
  border-color: rgba(8, 127, 140, 0.32);
  background: #f4fbfc;
  box-shadow: 0 10px 24px rgba(8, 74, 84, 0.06);
}

.dashboard-activity-item > span {
  color: var(--accent-dark);
  font-size: 10px;
  font-weight: 950;
  line-height: 1.2;
  text-transform: uppercase;
}

.dashboard-activity-item strong {
  grid-column: 1 / -1;
  min-width: 0;
  color: var(--text);
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.dashboard-activity-item small {
  min-width: 0;
  color: var(--muted);
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.dashboard-activity-item em {
  min-width: 0;
  color: #667985;
  font-size: 12px;
  font-style: normal;
  font-weight: 750;
  line-height: 1.3;
  overflow-wrap: anywhere;
}

.dashboard-activity-item .tag {
  grid-row: 1;
  grid-column: 2;
  align-self: start;
}

.dashboard-activity-empty {
  display: grid;
  gap: 5px;
  min-height: 120px;
  place-content: center;
  padding: 18px;
  border: 1px dashed rgba(183, 197, 206, 0.9);
  border-radius: 10px;
  color: var(--muted);
  text-align: center;
}

.dashboard-activity-empty strong {
  color: var(--text);
}

.dashboard-quick-create-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  min-width: 0;
}

.dashboard-quick-create-action {
  display: grid;
  gap: 8px;
  min-width: 0;
  min-height: 134px;
  align-content: start;
  padding: 13px;
  border: 1px solid rgba(216, 226, 231, 0.92);
  border-radius: 10px;
  background: #ffffff;
  color: var(--text);
  text-align: left;
  transition:
    border-color 140ms ease,
    background-color 140ms ease,
    box-shadow 140ms ease,
    transform 140ms ease;
}

.dashboard-quick-create-action:hover {
  border-color: rgba(8, 127, 140, 0.34);
  background: #f3fbfc;
  box-shadow: 0 12px 26px rgba(8, 74, 84, 0.07);
  transform: translateY(-1px);
}

.dashboard-quick-create-action strong {
  min-width: 0;
  color: var(--text);
  font-size: 15px;
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.dashboard-quick-create-action span {
  min-width: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.dashboard-quick-create-action .tag {
  width: fit-content;
  max-width: 100%;
  margin-top: auto;
}

@media (max-width: 1400px) {
  .dashboard-focus-switcher {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .dashboard-active-focus {
    grid-template-columns: 1fr;
  }

  .dashboard-active-focus-actions {
    justify-content: flex-start;
  }

  .dashboard-action-board {
    grid-template-columns: 1fr;
  }

  .dashboard-focus-preview-head {
    grid-template-columns: 1fr;
  }

  .dashboard-activity-layout {
    grid-template-columns: 1fr;
  }

  .dashboard-quick-create-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 820px) {
  .dashboard-interactive-head {
    display: grid;
  }

  .dashboard-activity-head {
    display: grid;
  }

  .dashboard-interactive-actions,
  .dashboard-active-focus-actions,
  .dashboard-activity-head .quiet-button {
    justify-content: stretch;
  }

  .dashboard-interactive-actions .quiet-button,
  .dashboard-active-focus-actions .primary-button,
  .dashboard-active-focus-actions .quiet-button,
  .dashboard-activity-head .quiet-button {
    width: 100%;
  }

  .dashboard-focus-switcher {
    grid-template-columns: 1fr;
  }

  .dashboard-action-card > div,
  .dashboard-action-card .primary-button,
  .dashboard-action-card .quiet-button {
    width: 100%;
  }

  .dashboard-quick-create-grid {
    grid-template-columns: 1fr;
  }
}

/* Guided customer fast track: compact route from input to consultant review. */
@media (max-width: 1500px) {
  .customer-fast-track-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 1180px) {
  .customer-action-traffic-main {
    grid-template-columns: 1fr;
  }

  .customer-action-traffic-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .customer-fast-track-head {
    grid-template-columns: 1fr;
  }

  .customer-fast-track-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .customer-fast-track-next {
    width: 100%;
  }

  .customer-step-coach-head,
  .customer-step-coach-grid {
    grid-template-columns: 1fr;
  }

  .customer-step-coach-status {
    width: 100%;
    text-align: left;
  }
}

@media (max-width: 720px) {
  .customer-action-traffic-grid {
    grid-template-columns: 1fr;
  }

  .customer-action-traffic-note {
    display: grid;
  }

  .customer-fast-track-grid {
    grid-template-columns: 1fr;
  }

  .customer-fast-track-stage {
    min-height: 0;
  }

  .customer-fast-track-next .quiet-button {
    width: 100%;
  }

  .customer-step-coach-actions,
  .customer-step-coach-actions .primary-button,
  .customer-step-coach-actions .quiet-button {
    width: 100%;
  }
}

/* SFM Compliance design quality pass: quieter enterprise SaaS polish. */
:root {
  --bg: #f4f7f8;
  --surface: #ffffff;
  --surface-soft: #f7fafb;
  --surface-muted: #eef4f6;
  --surface-warm: #fff8ed;
  --line: #dbe4e8;
  --line-strong: #becbd2;
  --text: #10212b;
  --muted: #637480;
  --muted-strong: #4f626e;
  --accent: #0b7f8d;
  --accent-dark: #075f69;
  --accent-soft: #e7f6f8;
  --gold: #aa6c0d;
  --rose: #a44268;
  --green: #26764a;
  --blue: #315f86;
  --danger: #a33d37;
  --warning-soft: #fff5e6;
  --danger-soft: #fff0ee;
  --success-soft: #eefaf3;
  --shadow: 0 20px 56px rgba(12, 34, 45, 0.1);
  --shadow-soft: 0 8px 24px rgba(12, 34, 45, 0.06);
  --shadow-card: 0 1px 2px rgba(12, 34, 45, 0.04);
  --radius: 8px;
  --content-max: 1660px;
  --page-pad: clamp(18px, 2vw, 34px);
}

html {
  background: var(--bg);
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

body {
  background:
    radial-gradient(circle at 42% -80px, rgba(11, 127, 141, 0.1), transparent 360px),
    linear-gradient(180deg, #f8fbfc 0, var(--bg) 360px);
  color: var(--text);
}

button,
input,
select,
textarea {
  letter-spacing: 0;
}

input,
select,
textarea {
  border-color: var(--line-strong);
  background: #fbfdfe;
}

input:focus,
select:focus,
textarea:focus,
button:focus-visible {
  outline: 3px solid rgba(11, 127, 141, 0.16);
  outline-offset: 2px;
}

.app-shell {
  grid-template-columns: 286px minmax(0, 1fr);
  background: transparent;
}

.sidebar {
  position: sticky;
  top: 0;
  z-index: 9;
  height: 100vh;
  gap: 18px;
  padding: 22px 20px;
  overflow-y: auto;
  scrollbar-gutter: stable;
  background:
    linear-gradient(180deg, rgba(10, 47, 63, 0.98), rgba(8, 39, 54, 0.99)),
    #082736;
  border-right: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: 8px 0 28px rgba(6, 25, 36, 0.14);
}

.sidebar::-webkit-scrollbar {
  width: 8px;
}

.sidebar::-webkit-scrollbar-thumb {
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.22);
}

.brand {
  grid-template-columns: 44px minmax(0, 1fr);
  gap: 12px;
  padding: 4px 2px 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.11);
}

.brand-mark {
  width: 44px;
  height: 44px;
  border-radius: 8px;
  background: #ffd072;
  box-shadow: inset 0 -1px 0 rgba(0, 0, 0, 0.12);
}

.brand h1 {
  color: #ffffff;
  font-size: 17px;
  font-weight: 850;
  line-height: 1.15;
}

.brand p {
  color: rgba(248, 251, 252, 0.72);
  font-size: 13px;
}

.main-nav,
.nav-group {
  gap: 5px;
}

.nav-group-head {
  margin: 14px 0 6px;
  padding: 0 8px;
  color: rgba(232, 242, 246, 0.48);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.nav-group-head small {
  color: rgba(232, 242, 246, 0.38);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: none;
}

.nav-button {
  grid-template-columns: 30px minmax(0, 1fr) auto;
  min-height: 42px;
  padding: 9px 10px;
  border-radius: 8px;
  color: rgba(248, 251, 252, 0.78);
  transition:
    background-color 140ms ease,
    border-color 140ms ease,
    color 140ms ease;
}

.nav-button:hover {
  background: rgba(255, 255, 255, 0.075);
  border-color: rgba(255, 255, 255, 0.12);
}

.nav-button.active {
  background: rgba(13, 129, 145, 0.26);
  border-color: rgba(85, 205, 220, 0.36);
  color: #ffffff;
}

.nav-icon {
  width: 23px;
  height: 23px;
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.11);
  color: rgba(255, 255, 255, 0.82);
  font-size: 11px;
}

.nav-button.active .nav-icon {
  background: rgba(255, 255, 255, 0.18);
  color: #ffffff;
}

.nav-count {
  min-width: 28px;
  padding: 3px 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
  color: rgba(248, 251, 252, 0.76);
  font-size: 11px;
  font-weight: 850;
  font-variant-numeric: tabular-nums;
}

.nav-button.active .nav-count {
  background: rgba(255, 255, 255, 0.17);
  color: #ffffff;
}

.knowledge-card {
  padding: 14px;
  border-color: rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.055);
}

.main {
  min-width: 0;
}

.topbar {
  min-height: 84px;
  padding: 18px var(--page-pad);
  border-bottom: 1px solid rgba(190, 203, 210, 0.55);
  background: rgba(248, 251, 252, 0.9);
  box-shadow: 0 1px 0 rgba(12, 34, 45, 0.03);
}

.topbar > div:first-child {
  min-width: 0;
}

.topbar h2 {
  max-width: min(780px, 70vw);
  color: var(--text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: clamp(25px, 2.2vw, 36px);
  font-weight: 850;
  line-height: 1.08;
  overflow-wrap: anywhere;
}

#viewSubtitle,
.view-subtitle {
  max-width: 78ch;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.45;
}

.main > .view,
.view {
  width: min(100%, var(--content-max));
  margin-inline: auto;
  padding: var(--page-pad);
}

.panel,
.table-panel,
.dashboard-section,
.workspace-context-bar,
.dashboard-presentation-suite,
.presentation-hero,
.review-command,
.policy-package,
.document-hero,
.document-customer-hub,
.audit-trail-hero,
.audit-trail-filter-panel,
.audit-trail-events-panel,
.audit-version-panel,
.register-work-card,
.register-form-panel,
.risk-board-panel,
.customer-action-traffic,
.customer-fast-track {
  border: 1px solid rgba(190, 203, 210, 0.72);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: var(--shadow-soft);
}

.panel,
.table-panel,
.dashboard-section {
  overflow: clip;
}

.panel-header,
.table-panel-heading,
.dashboard-section-head,
.review-panel-head {
  gap: 18px;
  padding: clamp(17px, 1.4vw, 24px);
  border-bottom: 1px solid rgba(219, 228, 232, 0.78);
}

.panel-header h3,
.table-panel h3,
.dashboard-section-head h3,
.review-panel-head h3,
.workspace-context-main h3 {
  color: var(--text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-weight: 850;
  line-height: 1.14;
  overflow-wrap: anywhere;
}

.panel-header p,
.table-panel p,
.dashboard-section-head p,
.review-panel-head p {
  max-width: 82ch;
  color: var(--muted);
  line-height: 1.55;
}

.eyebrow {
  margin-bottom: 7px;
  color: var(--accent-dark);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.06em;
}

.primary-button,
.quiet-button,
.icon-button,
.danger-button {
  min-height: 40px;
  border-radius: 8px;
  font-weight: 800;
  transition:
    border-color 140ms ease,
    background-color 140ms ease,
    box-shadow 140ms ease,
    color 140ms ease,
    transform 140ms ease;
}

.primary-button {
  border-color: var(--accent);
  background: linear-gradient(180deg, #0c8796, var(--accent-dark));
  box-shadow: 0 10px 22px rgba(7, 95, 105, 0.16);
}

.primary-button:hover {
  transform: translateY(-1px);
  box-shadow: 0 13px 28px rgba(7, 95, 105, 0.2);
}

.quiet-button,
.icon-button {
  background: #ffffff;
}

.quiet-button:hover,
.icon-button:hover {
  background: var(--accent-soft);
  box-shadow: var(--shadow-card);
}

.tag,
.scope-badge,
.status-pill,
.review-type,
.review-queue-signal,
.audit-trail-type-pill,
.policy-mini-status,
.review-header-card span {
  border-radius: 999px;
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0;
  line-height: 1.2;
}

.tag {
  border-color: rgba(190, 203, 210, 0.76);
  background: #f4f7f8;
  color: var(--muted-strong);
}

.tag.must,
.tag.should {
  border-color: rgba(163, 61, 55, 0.22);
  background: var(--danger-soft);
  color: var(--danger);
}

.tag.practice,
.tag.ready,
.tag.approved {
  border-color: rgba(38, 118, 74, 0.22);
  background: var(--success-soft);
  color: var(--green);
}

.empty-state,
.dashboard-activity-empty,
.risk-decision-empty,
.risk-treatment-empty,
.risk-review-empty {
  border: 1px dashed rgba(190, 203, 210, 0.9);
  border-radius: 8px;
  background:
    linear-gradient(180deg, #ffffff, #f8fbfc),
    #ffffff;
  color: var(--muted);
}

.dashboard-section-nav {
  position: sticky;
  top: 84px;
  z-index: 4;
  gap: 8px;
  margin: calc(var(--page-pad) * -0.35) 0 18px;
  padding: 10px;
  border: 1px solid rgba(190, 203, 210, 0.64);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.88);
  backdrop-filter: blur(12px);
  box-shadow: var(--shadow-card);
}

.dashboard-section-nav button,
.dashboard-section-nav a {
  min-height: 38px;
  border-radius: 8px;
}

.workspace-context-bar.dashboard-context {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(340px, 0.42fr);
  gap: 22px;
  padding: clamp(20px, 1.7vw, 28px);
  background:
    linear-gradient(135deg, #ffffff 0%, #f1fafb 100%),
    #ffffff;
}

.workspace-context-bar.dashboard-context .workspace-context-main h3 {
  font-size: clamp(24px, 2vw, 34px);
}

.workspace-context-bar.dashboard-context .workspace-context-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.workspace-context-bar.dashboard-context .workspace-context-meta span {
  min-height: 28px;
  padding: 5px 10px;
  border: 1px solid rgba(190, 203, 210, 0.72);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.78);
}

.workspace-context-bar.dashboard-context .workspace-context-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(100px, 1fr));
  gap: 10px;
}

.workspace-context-bar.dashboard-context .workspace-context-metrics div {
  min-height: 78px;
  padding: 13px;
  border: 1px solid rgba(190, 203, 210, 0.68);
  border-radius: 8px;
  background: #ffffff;
  box-shadow: none;
}

.workspace-context-bar.dashboard-context .workspace-context-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(150px, 1fr));
  gap: 10px;
}

.workspace-context-bar.dashboard-context .workspace-context-actions .primary-button,
.workspace-context-bar.dashboard-context .workspace-context-actions .quiet-button {
  width: 100%;
}

.dashboard-presentation-suite {
  display: grid;
  gap: 18px;
  padding: clamp(20px, 1.7vw, 28px);
}

.dashboard-presentation-suite-head,
.presentation-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 22px;
  align-items: start;
}

.dashboard-presentation-suite-head h3,
.presentation-hero h3 {
  max-width: 15ch;
  font-size: clamp(30px, 3vw, 48px);
  line-height: 1.02;
}

.dashboard-presentation-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
}

.presentation-hero {
  padding: clamp(18px, 1.5vw, 24px);
  border: 1px solid rgba(190, 203, 210, 0.68);
  background:
    linear-gradient(135deg, #ffffff 0%, #f4fafb 100%),
    #ffffff;
  box-shadow: none;
}

.presentation-hero-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(110px, 1fr));
  gap: 10px;
}

.presentation-hero-metrics span {
  min-height: 86px;
  padding: 14px;
  border: 1px solid rgba(190, 203, 210, 0.72);
  border-radius: 8px;
  background: #ffffff;
}

.dashboard-section {
  display: grid;
  gap: 0;
}

.dashboard-section > *:not(.dashboard-section-head) {
  padding: clamp(18px, 1.5vw, 24px);
}

.dashboard-grid,
.dashboard-lower,
.dashboard-start-status-grid,
.dashboard-quick-create-grid,
.dashboard-tool-grid,
.tool-hub-grid,
.review-header-cards,
.document-health,
.document-customer-status-grid,
.audit-trail-kpis,
.register-panel-kpis {
  gap: 12px;
}

.dashboard-start-center,
.dashboard-start-status-card,
.dashboard-start-next,
.dashboard-focus-preview,
.dashboard-activity-item,
.dashboard-quick-create-action,
.review-header-card,
.document-health-item,
.document-customer-status,
.audit-trail-kpis article,
.register-panel-kpis div {
  border-radius: 8px;
  border-color: rgba(190, 203, 210, 0.72);
  box-shadow: none;
}

.dashboard-start-status-card,
.dashboard-quick-create-action,
.review-header-card {
  min-height: 0;
}

.customer-action-traffic,
.customer-fast-track,
.customer-step-coach,
.customer-simple-cockpit,
.customer-submission-flow {
  gap: 16px;
}

.customer-action-traffic-main,
.customer-fast-track-head {
  grid-template-columns: minmax(0, 1fr) minmax(300px, 0.38fr);
  gap: 18px;
}

.customer-action-traffic-grid,
.customer-fast-track-grid {
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 12px;
}

.customer-action-traffic-grid article,
.customer-fast-track-stage,
.customer-step-coach-card,
.customer-simple-card {
  min-height: 0;
  border-radius: 8px;
  box-shadow: none;
}

.customer-action-traffic-note,
.document-customer-hint,
.audit-trail-boundary-note {
  border-radius: 8px;
  background: #f7fafb;
  border-color: rgba(190, 203, 210, 0.68);
}

.review-center {
  display: grid;
  gap: 18px;
}

.review-command .panel-header,
.review-filter-head,
.review-triage-head,
.review-sla-head {
  grid-template-columns: minmax(0, 1fr) auto;
}

.review-header-cards {
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  padding: 0 clamp(18px, 1.5vw, 24px) clamp(18px, 1.5vw, 24px);
}

.review-header-card {
  min-height: 96px;
  padding: 14px;
  background: #ffffff;
}

.review-workbench {
  align-items: start;
  gap: 18px;
}

.review-list-panel,
.review-detail-panel {
  border-radius: 8px;
}

.review-item {
  border-radius: 8px;
  border-color: rgba(190, 203, 210, 0.72);
  background: #ffffff;
}

.review-item.active {
  border-color: rgba(11, 127, 141, 0.36);
  background: #f5fbfc;
}

.review-detail-grid div,
.review-detail-section,
.review-decision-aid,
.review-history-entry {
  border-radius: 8px;
}

.review-comment-grid textarea {
  min-height: 112px;
}

.policy-package {
  padding: clamp(18px, 1.5vw, 24px);
}

.policy-package > .panel-header {
  padding: 0 0 18px;
}

.policy-package-grid {
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 12px;
}

.policy-package-grid div,
.policy-package-section {
  border-radius: 8px;
  box-shadow: none;
}

.policy-package-sections {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.policy-package-chip {
  min-height: 38px;
  border-radius: 999px;
  box-shadow: none;
}

.policy-package-chip:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 18px rgba(12, 34, 45, 0.08);
}

.policy-package-chip-main,
.policy-package-chip-open {
  min-width: 0;
}

.document-workspace {
  display: grid;
  gap: 18px;
}

.document-hero,
.document-customer-hub {
  padding: clamp(18px, 1.5vw, 24px);
}

.document-hero .panel-header,
.document-customer-hub .document-customer-hub-head {
  padding: 0 0 18px;
}

.document-health {
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
}

.document-health-item {
  min-height: 86px;
  padding: 14px;
  background: #ffffff;
}

.document-customer-lanes {
  gap: 12px;
}

.document-customer-next,
.document-customer-lane,
.document-workflow-card,
.document-card,
.document-row,
.upload-dropzone {
  border-radius: 8px;
}

.document-workflow-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.audit-trail-workspace {
  display: grid;
  gap: 18px;
}

.audit-trail-hero {
  padding: clamp(18px, 1.5vw, 24px);
}

.audit-trail-hero .panel-header {
  padding: 0 0 18px;
}

.audit-trail-kpis,
.audit-trail-focus-strip {
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
}

.audit-trail-kpis article,
.audit-trail-focus-strip article {
  border-radius: 8px;
  box-shadow: none;
}

.audit-trail-layout {
  grid-template-columns: minmax(0, 1fr) minmax(320px, 0.38fr);
  gap: 18px;
  align-items: start;
}

.audit-trail-list,
.audit-version-list {
  gap: 10px;
  padding: clamp(14px, 1.2vw, 18px);
}

.audit-trail-event,
.audit-version-row {
  border-radius: 8px;
  background: #ffffff;
  box-shadow: none;
}

.audit-trail-event {
  position: relative;
  padding-left: 18px;
}

.audit-trail-dot {
  box-shadow: 0 0 0 4px #ffffff;
}

.register-card-list {
  gap: 12px;
  padding: clamp(16px, 1.4vw, 22px);
  background: #f7fafb;
}

.register-work-card {
  grid-template-columns: minmax(280px, 0.74fr) minmax(0, 1.26fr);
  gap: 16px;
  border-radius: 8px;
  box-shadow: var(--shadow-card);
}

.register-work-card-grid {
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
}

.register-work-card-grid > div,
.risk-register-decision-strip,
.register-mini-path div {
  border-radius: 8px;
  background: #ffffff;
}

.table-scroll {
  max-width: 100%;
  overflow-x: auto;
  border-radius: 8px;
  background: #ffffff;
}

.data-table {
  min-width: 920px;
  border-collapse: separate;
  border-spacing: 0;
}

.data-table th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: #f7fafb;
  color: var(--muted-strong);
  font-size: 11px;
  letter-spacing: 0.05em;
}

.data-table td {
  vertical-align: top;
}

.data-table th,
.data-table td {
  overflow-wrap: anywhere;
}

.form-grid,
.register-simple-form,
.risk-workshop-form,
.risk-form {
  gap: 12px;
}

.field,
.risk-workshop-form .field {
  border-radius: 8px;
}

.field label,
.risk-workshop-form .field label,
.risk-form .field label {
  color: var(--muted-strong);
  font-size: 11px;
  letter-spacing: 0.04em;
}

.field-help {
  color: var(--muted);
  line-height: 1.35;
}

[class*="grid"] > *,
[class*="layout"] > *,
[class*="panel"] > *,
[class*="card"] > *,
.view *,
.panel * {
  min-width: 0;
}

img,
svg,
canvas,
video {
  max-width: 100%;
}

@media (max-width: 1280px) {
  .app-shell {
    grid-template-columns: 262px minmax(0, 1fr);
  }

  .workspace-context-bar.dashboard-context,
  .dashboard-presentation-suite-head,
  .presentation-hero,
  .review-command .panel-header,
  .review-filter-head,
  .review-triage-head,
  .review-sla-head,
  .customer-action-traffic-main,
  .customer-fast-track-head,
  .audit-trail-layout {
    grid-template-columns: 1fr;
  }

  .dashboard-presentation-actions,
  .workspace-context-bar.dashboard-context .workspace-context-actions {
    justify-content: flex-start;
  }

  .policy-package-sections,
  .document-workflow-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 860px) {
  .app-shell {
    display: block;
  }

  .sidebar {
    position: relative;
    width: 100%;
    height: auto;
    max-height: none;
    padding: 18px;
  }

  .nav-button {
    width: 100%;
    max-width: 100%;
    grid-template-columns: 30px minmax(0, 1fr) max-content;
  }

  .nav-count {
    justify-self: end;
    max-width: 72px;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .topbar {
    position: sticky;
    min-height: auto;
    padding: 16px;
  }

  .topbar,
  .top-actions {
    align-items: flex-start;
  }

  .topbar h2 {
    max-width: 100%;
    font-size: 28px;
  }

  .main > .view,
  .view {
    padding: 16px;
  }

  .dashboard-section-nav {
    position: static;
    margin-top: 0;
  }

  .workspace-context-bar.dashboard-context .workspace-context-metrics,
  .presentation-hero-metrics,
  .dashboard-start-status-grid,
  .review-header-cards,
  .document-health,
  .audit-trail-kpis,
  .register-work-card,
  .register-work-card-grid,
  .register-mini-path,
  .risk-register-decision-strip {
    grid-template-columns: 1fr;
  }

  .workspace-context-bar.dashboard-context .workspace-context-actions,
  .dashboard-presentation-actions,
  .review-decision-bar,
  .review-item-actions,
  .document-customer-actions,
  .register-actions,
  .top-actions {
    display: grid;
    grid-template-columns: 1fr;
    width: 100%;
  }

  .workspace-context-bar.dashboard-context .workspace-context-actions button,
  .dashboard-presentation-actions button,
  .review-decision-bar button,
  .review-item-actions button,
  .document-customer-actions button,
  .register-actions button,
  .top-actions button {
    width: 100%;
  }

  .table-scroll,
  .table-panel .table-scroll {
    max-width: 100%;
    overflow-x: auto;
  }

  .compare-table,
  .data-table,
  .policy-table,
  .evidence-matrix-table {
    width: 100%;
    min-width: 0;
    table-layout: fixed;
  }

  .compare-table th,
  .compare-table td,
  .data-table th,
  .data-table td,
  .policy-table th,
  .policy-table td,
  .evidence-matrix-table th,
  .evidence-matrix-table td {
    padding: 10px 8px;
    white-space: normal;
    word-break: break-word;
    overflow-wrap: anywhere;
  }

  .data-table .document-actions,
  .compare-table .document-actions,
  .policy-table .document-actions,
  .evidence-matrix-table .document-actions {
    display: grid;
    grid-template-columns: 1fr;
    gap: 6px;
  }

  .integration-line {
    max-width: calc(100vw - 48px);
  }
}

@media (max-width: 560px) {
  :root {
    --page-pad: 14px;
  }

  .brand {
    grid-template-columns: 40px 1fr;
  }

  .brand-mark {
    width: 40px;
    height: 40px;
  }

  .panel-header,
  .table-panel-heading,
  .dashboard-section-head,
  .review-panel-head {
    padding: 15px;
  }

  .dashboard-section > *:not(.dashboard-section-head),
  .dashboard-presentation-suite,
  .presentation-hero,
  .document-hero,
  .document-customer-hub,
  .audit-trail-hero {
    padding: 15px;
  }

  .dashboard-presentation-suite-head h3,
  .presentation-hero h3 {
    max-width: none;
    font-size: 30px;
  }

  .compare-table,
  .data-table,
  .policy-table,
  .evidence-matrix-table {
    min-width: 0;
  }
}

/* Mobile navigation repair: keep the sidebar as a readable list, never as an icon grid. */
@media (max-width: 860px) {
  .sidebar {
    display: grid !important;
    grid-template-columns: 1fr !important;
    width: 100% !important;
    max-width: 100% !important;
    overflow-x: hidden !important;
  }

  .main-nav {
    display: grid !important;
    grid-template-columns: 1fr !important;
    gap: 6px !important;
    width: 100% !important;
    max-width: 100% !important;
    overflow: visible !important;
  }

  .nav-group {
    display: grid !important;
    grid-template-columns: 1fr !important;
    gap: 5px !important;
    width: 100% !important;
    max-width: 100% !important;
  }

  .nav-button {
    grid-template-columns: 30px minmax(0, 1fr) max-content !important;
    width: 100% !important;
    max-width: 100% !important;
  }

  .nav-button > span:nth-child(2),
  .nav-label {
    width: auto !important;
    min-width: 0 !important;
    max-width: 100% !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
  }

  .nav-count {
    justify-self: end !important;
    max-width: 76px !important;
  }
}

.customer-mode-hero-copy h3 {
  line-height: 1.12 !important;
}

/* SFM Compliance Design System v1: final product shell, tokens and component rules. */
:root {
  --sfm-font-sans: "Inter", "SF Pro Text", "Segoe UI", Roboto, Arial, sans-serif;
  --sfm-font-display: "Inter", "SF Pro Display", "Segoe UI", Roboto, Arial, sans-serif;
  --sfm-bg: #f4f8fa;
  --sfm-bg-soft: #eef6f8;
  --sfm-surface: #ffffff;
  --sfm-surface-soft: #f8fbfc;
  --sfm-surface-blue: #f1fbfd;
  --sfm-surface-warm: #fff8ec;
  --sfm-border: #d7e3e8;
  --sfm-border-strong: #b9cbd3;
  --sfm-text: #102838;
  --sfm-text-strong: #071d2b;
  --sfm-muted: #637686;
  --sfm-muted-strong: #506574;
  --sfm-primary: #087b89;
  --sfm-primary-strong: #056574;
  --sfm-primary-soft: #dff6f8;
  --sfm-info: #1484a5;
  --sfm-success: #1f7a4a;
  --sfm-success-soft: #e8f7ee;
  --sfm-warning: #a86a0b;
  --sfm-warning-soft: #fff3d8;
  --sfm-danger: #b83f3f;
  --sfm-danger-soft: #fff0ee;
  --sfm-purple: #6656b8;
  --sfm-purple-soft: #f1effc;
  --sfm-sidebar: #073245;
  --sfm-sidebar-2: #06293a;
  --sfm-radius-xs: 6px;
  --sfm-radius-sm: 8px;
  --sfm-radius-md: 10px;
  --sfm-radius-lg: 12px;
  --sfm-shadow-xs: 0 1px 2px rgba(9, 31, 44, 0.06);
  --sfm-shadow-sm: 0 8px 22px rgba(9, 31, 44, 0.07);
  --sfm-shadow-md: 0 18px 48px rgba(9, 31, 44, 0.1);
  --sfm-space-1: 4px;
  --sfm-space-2: 8px;
  --sfm-space-3: 12px;
  --sfm-space-4: 16px;
  --sfm-space-5: 20px;
  --sfm-space-6: 24px;
  --sfm-space-7: 32px;
  --sfm-content-max: 1600px;
  --sfm-sidebar-width: 292px;
}

html {
  background: var(--sfm-bg) !important;
  color-scheme: light;
}

body {
  min-width: 0 !important;
  overflow-x: hidden !important;
  background:
    radial-gradient(circle at 88% 0, rgba(174, 223, 231, 0.28), transparent 32rem),
    linear-gradient(180deg, #f8fbfc 0, var(--sfm-bg) 40%, #eef6f8 100%) !important;
  color: var(--sfm-text) !important;
  font-family: var(--sfm-font-sans) !important;
  font-size: 15px !important;
  line-height: 1.5 !important;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body *,
body *::before,
body *::after {
  box-sizing: border-box;
}

.app-shell {
  display: grid !important;
  grid-template-columns: var(--sfm-sidebar-width) minmax(0, 1fr) !important;
  min-height: 100vh !important;
  background: transparent !important;
}

.sidebar {
  position: sticky !important;
  top: 0 !important;
  display: grid !important;
  grid-template-columns: 1fr !important;
  align-content: start !important;
  gap: var(--sfm-space-5) !important;
  width: var(--sfm-sidebar-width) !important;
  height: 100vh !important;
  padding: 24px 20px !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
  background:
    linear-gradient(180deg, rgba(8, 51, 70, 0.99), rgba(5, 36, 52, 0.99)),
    var(--sfm-sidebar) !important;
  border-right: 1px solid rgba(255, 255, 255, 0.1) !important;
  box-shadow: 10px 0 30px rgba(7, 29, 43, 0.12) !important;
}

.brand {
  display: grid !important;
  grid-template-columns: 48px minmax(0, 1fr) !important;
  align-items: center !important;
  gap: 12px !important;
  padding: 4px 2px 18px !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12) !important;
}

.brand-mark {
  display: grid !important;
  place-items: center !important;
  width: 48px !important;
  height: 48px !important;
  border-radius: var(--sfm-radius-sm) !important;
  background: linear-gradient(180deg, #ffd982, #ffc86b) !important;
  color: #062234 !important;
  font-family: var(--sfm-font-display) !important;
  font-size: 14px !important;
  font-weight: 900 !important;
  letter-spacing: 0 !important;
  box-shadow: inset 0 -1px 0 rgba(6, 34, 52, 0.14) !important;
}

.brand h1 {
  margin: 0 !important;
  color: #ffffff !important;
  font-family: var(--sfm-font-display) !important;
  font-size: 18px !important;
  font-weight: 850 !important;
  line-height: 1.12 !important;
  letter-spacing: 0 !important;
}

.brand p {
  margin: 4px 0 0 !important;
  color: rgba(240, 249, 252, 0.72) !important;
  font-size: 13px !important;
  line-height: 1.35 !important;
}

.language-switcher {
  margin: 0 !important;
}

.language-trigger {
  width: 100% !important;
  min-height: 44px !important;
  padding: 10px 12px !important;
  border: 1px solid rgba(214, 236, 241, 0.18) !important;
  border-radius: var(--sfm-radius-md) !important;
  background: rgba(255, 255, 255, 0.065) !important;
  color: #edf9fc !important;
  box-shadow: none !important;
}

.language-menu {
  width: 100% !important;
  margin-top: 8px !important;
  border: 1px solid rgba(214, 236, 241, 0.2) !important;
  border-radius: var(--sfm-radius-md) !important;
  background: #092d3e !important;
  box-shadow: var(--sfm-shadow-md) !important;
}

.main-nav {
  display: grid !important;
  grid-template-columns: 1fr !important;
  gap: 10px !important;
  width: 100% !important;
  overflow: visible !important;
}

.nav-group {
  display: grid !important;
  grid-template-columns: 1fr !important;
  gap: 5px !important;
  padding: 0 0 12px !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1) !important;
}

.nav-group-head {
  display: flex !important;
  justify-content: space-between !important;
  gap: 10px !important;
  margin: 10px 0 4px !important;
  padding: 0 8px !important;
  color: rgba(229, 244, 249, 0.56) !important;
  font-size: 10px !important;
  font-weight: 900 !important;
  letter-spacing: 0.08em !important;
  text-transform: uppercase !important;
}

.nav-group-head small {
  max-width: 14ch !important;
  overflow: hidden !important;
  color: rgba(229, 244, 249, 0.4) !important;
  font-size: 10px !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}

.nav-button {
  display: grid !important;
  grid-template-columns: 30px minmax(0, 1fr) max-content !important;
  align-items: center !important;
  gap: 10px !important;
  width: 100% !important;
  min-height: 42px !important;
  padding: 9px 10px !important;
  border: 1px solid transparent !important;
  border-radius: var(--sfm-radius-sm) !important;
  background: transparent !important;
  color: rgba(245, 251, 252, 0.78) !important;
  box-shadow: none !important;
}

.nav-button:hover {
  border-color: rgba(103, 215, 231, 0.18) !important;
  background: rgba(255, 255, 255, 0.065) !important;
  color: #ffffff !important;
}

.nav-button.active {
  border-color: rgba(103, 215, 231, 0.38) !important;
  background:
    linear-gradient(90deg, rgba(10, 126, 144, 0.42), rgba(255, 255, 255, 0.055)),
    rgba(255, 255, 255, 0.045) !important;
  color: #ffffff !important;
}

.nav-button::before {
  inset: 8px auto 8px 0 !important;
  width: 3px !important;
  border-radius: 999px !important;
}

.nav-button.active::before {
  background: #75ddec !important;
}

.nav-icon {
  display: grid !important;
  place-items: center !important;
  width: 24px !important;
  height: 24px !important;
  border-radius: 7px !important;
  background: rgba(255, 255, 255, 0.11) !important;
  color: rgba(245, 251, 252, 0.84) !important;
  font-size: 10px !important;
  font-weight: 900 !important;
}

.nav-label,
.nav-button > span:nth-child(2) {
  min-width: 0 !important;
  overflow: hidden !important;
  color: inherit !important;
  font-size: 14px !important;
  font-weight: 720 !important;
  line-height: 1.25 !important;
  text-overflow: ellipsis !important;
  white-space: nowrap !important;
}

.nav-count {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-width: 26px !important;
  max-width: 74px !important;
  min-height: 22px !important;
  padding: 3px 8px !important;
  border-radius: 999px !important;
  background: rgba(255, 255, 255, 0.12) !important;
  color: rgba(245, 251, 252, 0.78) !important;
  font-size: 11px !important;
  font-weight: 850 !important;
  line-height: 1 !important;
}

.nav-count.warning,
.nav-count.attention,
.nav-count.internal {
  background: rgba(246, 190, 82, 0.24) !important;
  color: #ffe2a8 !important;
}

.knowledge-card {
  margin-top: auto !important;
  padding: 14px !important;
  border: 1px solid rgba(214, 236, 241, 0.16) !important;
  border-radius: var(--sfm-radius-md) !important;
  background: rgba(255, 255, 255, 0.06) !important;
  box-shadow: none !important;
}

.main {
  min-width: 0 !important;
  background: transparent !important;
}

.topbar {
  position: sticky !important;
  top: 0 !important;
  z-index: 25 !important;
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) auto !important;
  gap: 24px !important;
  align-items: start !important;
  min-height: 118px !important;
  padding: 24px clamp(28px, 3vw, 52px) 20px !important;
  overflow: visible !important;
  border-bottom: 1px solid var(--sfm-border) !important;
  background: rgba(248, 251, 252, 0.92) !important;
  backdrop-filter: blur(16px) !important;
}

.topbar .eyebrow,
.eyebrow {
  color: var(--sfm-primary) !important;
  font-size: 11px !important;
  font-weight: 900 !important;
  letter-spacing: 0.08em !important;
  line-height: 1.15 !important;
  text-transform: uppercase !important;
}

.topbar h2,
.view h1,
.panel h1 {
  margin: 0 !important;
  color: var(--sfm-text-strong) !important;
  font-family: var(--sfm-font-display) !important;
  font-size: clamp(30px, 2.25vw, 42px) !important;
  font-weight: 850 !important;
  line-height: 1.03 !important;
  letter-spacing: 0 !important;
}

.view-subtitle,
.topbar p {
  max-width: 880px !important;
  margin: 6px 0 0 !important;
  color: var(--sfm-muted) !important;
  font-size: 15px !important;
  font-weight: 650 !important;
  line-height: 1.45 !important;
}

.top-status-chips {
  display: flex !important;
  flex-wrap: wrap !important;
  gap: 8px !important;
  margin-top: 10px !important;
}

.top-status-chip,
.badge,
.status-pill,
.tag,
.source-pill,
.policy-chip,
.policy-package-chip,
.metric-chip {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-height: 26px !important;
  max-width: 100% !important;
  padding: 5px 10px !important;
  border: 1px solid var(--sfm-border) !important;
  border-radius: 999px !important;
  background: var(--sfm-surface-soft) !important;
  color: var(--sfm-muted-strong) !important;
  font-size: 12px !important;
  font-weight: 850 !important;
  line-height: 1.15 !important;
  letter-spacing: 0 !important;
  white-space: normal !important;
}

.top-status-chip.role,
.top-status-chip.sync,
.top-status-chip.local,
.top-status-chip.review {
