/* NIS-2 design pass: separate regulatory workspace with a clear customer route. */
.nis-workspace {
  display: grid !important;
  gap: 20px !important;
}

.nis-command-panel {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) auto !important;
  gap: 20px !important;
  align-items: start !important;
  padding: clamp(20px, 2vw, 28px) !important;
  overflow: hidden !important;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.98), rgba(239, 250, 252, 0.95)),
    var(--sfm-surface) !important;
}

.nis-command-copy {
  display: grid !important;
  gap: 8px !important;
}

.nis-command-copy h3 {
  max-width: 820px !important;
  margin: 0 !important;
  color: var(--sfm-text-strong) !important;
  font-size: clamp(27px, 1.9vw, 38px) !important;
  line-height: 1.06 !important;
}

.nis-command-copy p {
  max-width: 920px !important;
  margin: 0 !important;
}

.nis-command-actions {
  display: flex !important;
  flex-wrap: wrap !important;
  gap: 10px !important;
  justify-content: flex-end !important;
}

.nis-stage-strip {
  grid-column: 1 / -1 !important;
  display: grid !important;
  grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
  gap: 12px !important;
  margin-top: 4px !important;
}

.nis-stage-card {
  display: grid !important;
  grid-template-columns: 42px minmax(0, 1fr) !important;
  gap: 12px !important;
  align-items: start !important;
  min-height: 128px !important;
  padding: 16px !important;
  border: 1px solid var(--sfm-border) !important;
  border-left: 4px solid #7bcfdd !important;
  border-radius: var(--sfm-radius-md) !important;
  background: #ffffff !important;
  color: var(--sfm-text) !important;
  box-shadow: var(--sfm-shadow-xs) !important;
  text-align: left !important;
}

.nis-stage-card:hover {
  border-color: #9adbe4 !important;
  box-shadow: 0 12px 24px rgba(8, 52, 70, 0.08) !important;
  transform: translateY(-1px) !important;
}

.nis-stage-card.done {
  border-left-color: var(--sfm-success) !important;
  background: linear-gradient(180deg, #ffffff, var(--sfm-success-soft)) !important;
}

.nis-stage-card.active {
  border-left-color: var(--sfm-primary) !important;
}

.nis-stage-card.blocked {
  border-left-color: var(--sfm-danger) !important;
  background: linear-gradient(180deg, #ffffff, var(--sfm-danger-soft)) !important;
}

.nis-stage-number {
  display: grid !important;
  place-items: center !important;
  width: 38px !important;
  height: 38px !important;
  border-radius: var(--sfm-radius-sm) !important;
  background: var(--sfm-primary-soft) !important;
  color: var(--sfm-primary-strong) !important;
  font-size: 13px !important;
  font-weight: 900 !important;
}

.nis-stage-main {
  display: grid !important;
  gap: 5px !important;
}

.nis-stage-main strong {
  color: var(--sfm-text-strong) !important;
  font-size: 16px !important;
  line-height: 1.18 !important;
}

.nis-stage-main small {
  color: var(--sfm-muted) !important;
  font-size: 13px !important;
  font-weight: 650 !important;
  line-height: 1.35 !important;
}

.nis-stage-status {
  grid-column: 2 !important;
  align-self: end !important;
  width: fit-content !important;
  max-width: 100% !important;
  padding: 4px 8px !important;
  border-radius: 999px !important;
  background: #f1f6f8 !important;
  color: var(--sfm-muted-strong) !important;
  font-size: 11px !important;
  font-weight: 900 !important;
}

.nis-metric-grid {
  grid-column: 1 / -1 !important;
