/* Background jobs: technical processing queue for platform admins. */
.background-jobs-view .operations-hero-actions {
  align-items: stretch !important;
}

.job-live-status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 14px;
  border: 1px solid var(--sfm-border);
  border-radius: var(--sfm-radius-md);
  background: rgba(255, 255, 255, 0.82);
  box-shadow: var(--sfm-shadow-xs);
}

.job-live-status div {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.job-live-status strong {
  color: var(--sfm-ink);
  font-size: 0.92rem;
}

.job-live-status span {
  color: var(--sfm-muted);
  font-size: 0.84rem;
}

.job-list {
  display: grid;
  gap: 12px;
}

.job-filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin: 0 0 14px;
}

.job-filter-bar button {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 38px;
  padding: 8px 12px;
  border: 1px solid var(--sfm-border);
  border-radius: 999px;
  background: #ffffff;
  color: var(--sfm-ink);
  font: inherit;
  font-size: 0.88rem;
  font-weight: 800;
  cursor: pointer;
}

.job-filter-bar button:hover,
.job-filter-bar button.active {
  border-color: var(--sfm-accent);
  background: var(--sfm-accent-soft);
  color: var(--sfm-accent-strong);
}

.job-filter-bar strong {
  display: inline-grid;
  min-width: 24px;
  height: 24px;
  place-items: center;
  padding: 0 7px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.84);
  color: inherit;
  font-size: 0.78rem;
}

.job-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: start;
  padding: 18px;
  border: 1px solid var(--sfm-border);
  border-left: 4px solid var(--sfm-border-strong);
  border-radius: var(--sfm-radius-md);
  background: #ffffff;
  box-shadow: var(--sfm-shadow-xs);
}

.job-card.running,
.job-card.queued,
.job-card.retry {
  border-left-color: var(--sfm-accent);
}

.job-card.succeeded {
  border-left-color: var(--sfm-success);
}

.job-card.failed {
  border-left-color: var(--sfm-danger);
  background: #fffafa;
}

.job-card.cancelled {
  border-left-color: var(--sfm-muted);
}

.job-card-main {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.job-card h3 {
  margin: 0;
  font-size: 1rem;
  line-height: 1.25;
}

.job-card p {
  margin: 0;
  color: var(--sfm-muted);
}

.job-error,
.job-result {
  padding: 10px 12px;
  border-radius: var(--sfm-radius-sm);
  font-size: 0.9rem;
}

.job-error {
  border: 1px solid rgba(183, 59, 52, 0.2);
  background: #fff0ef;
  color: #92332e !important;
}

.job-result {
  border: 1px solid rgba(25, 132, 89, 0.18);
  background: #effaf5;
  color: #176a49 !important;
}

.job-runbook {
  display: grid;
  gap: 4px;
  padding: 10px 12px;
  border: 1px solid var(--sfm-border);
  border-radius: var(--sfm-radius-sm);
  background: #f8fbfc;
}

.job-runbook strong {
  color: var(--sfm-ink);
  font-size: 0.86rem;
}

.job-runbook span {
  color: var(--sfm-muted);
  font-size: 0.84rem;
  line-height: 1.35;
}

.job-runbook.warning {
  border-color: rgba(183, 59, 52, 0.22);
  background: #fff7f6;
}

.job-runbook.attention {
  border-color: rgba(201, 130, 32, 0.24);
  background: #fff9ed;
}

.job-runbook.ready {
  border-color: rgba(25, 132, 89, 0.18);
  background: #f2fbf7;
}

@media (max-width: 760px) {
  .job-live-status {
    align-items: stretch;
    flex-direction: column;
  }

  .job-filter-bar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .job-filter-bar button {
    justify-content: space-between;
    width: 100%;
  }

  .job-card {
    grid-template-columns: 1fr;
  }

  .job-card .operations-alert-actions,
  .job-card .operations-alert-actions button {
    width: 100%;
  }
}

/* Presentation-ready layout hardening: prevent overwide cards and vertical word breaks. */
*,
*::before,
*::after {
  box-sizing: border-box;
}

.main,
.view,
.panel,
.table-panel,
.register-panel,
.customer-mode-page,
.guided-mode,
.dashboard-section,
.document-workspace,
.soa-workspace {
  min-width: 0;
  max-width: 100%;
}

.view {
  overflow-x: clip;
}

.panel,
.table-panel,
.register-panel {
  overflow: hidden;
}

.panel :where(h1, h2, h3, h4, p, span, strong, small, label, button),
.table-panel :where(h1, h2, h3, h4, p, span, strong, small, label, button),
.register-panel :where(h1, h2, h3, h4, p, span, strong, small, label, button),
.customer-mode-page :where(h1, h2, h3, h4, p, span, strong, small, label, button),
.guided-mode :where(h1, h2, h3, h4, p, span, strong, small, label, button) {
  min-width: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
  word-break: normal;
  hyphens: auto;
}

.topbar {
  overflow: hidden;
}

.topbar > div:first-child {
  min-width: 0;
}

.topbar h2,
.topbar p {
  max-width: 100%;
  overflow-wrap: anywhere;
}

.top-actions {
  flex: 0 0 auto;
}

.tag,
.badge,
.scope-badge,
.nav-count,
.status-pill {
  max-width: 100%;
  white-space: normal;
  overflow-wrap: anywhere;
}

.primary-button,
.quiet-button,
.danger-button,
.icon-button {
  justify-content: center;
  white-space: normal;
}

.register-card-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 420px), 1fr));
  gap: 16px;
  width: 100%;
  min-width: 0;
}

.register-work-card {
  display: grid;
  grid-template-columns: 1fr;
  gap: 14px;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  align-content: start;
}

.register-work-card-main,
.register-work-card-main > *,
.register-card-badges,
.register-review-cell,
.register-evidence-cell,
.register-date-cell {
  min-width: 0;
  max-width: 100%;
}

.register-card-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.register-work-card-main strong {
  display: block;
  font-size: clamp(1rem, 1.4vw, 1.18rem);
  line-height: 1.25;
}

.register-work-card-main p,
.register-work-card-main small,
.register-next-step,
.evidence-mini-link {
  overflow-wrap: anywhere;
  word-break: normal;
}

.register-work-card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
  width: 100%;
  min-width: 0;
}

.register-work-card-grid > div {
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
}

.register-mini-path,
.register-mini-path.compact {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
  width: 100%;
  min-width: 0;
}

.register-mini-path div {
  min-width: 0;
  overflow: hidden;
}

.register-mini-path span {
  min-width: 0;
}

.register-card-footer {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
}

.register-card-footer .document-actions,
.register-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
