/* Enterprise SaaS final polish: reduce color noise and make hierarchy feel curated. */
:root {
  --sfm-ui-bg: #f7f9fb;
  --sfm-ui-surface: #ffffff;
  --sfm-ui-soft: #f9fbfc;
  --sfm-ui-line: #e2e8ef;
  --sfm-ui-line-strong: #cbd5df;
  --sfm-ui-text: #101820;
  --sfm-ui-muted: #667586;
  --sfm-ui-accent: #1f6b75;
  --sfm-ui-accent-soft: #eef8fa;
  --sfm-ui-warning: #9a6700;
  --sfm-ui-warning-soft: #fff8e8;
  --sfm-ui-danger: #a0443e;
  --sfm-ui-danger-soft: #fff5f4;
  --sfm-ui-success: #24734d;
  --sfm-ui-success-soft: #f3faf6;
  --sfm-ui-radius: 12px;
  --sfm-ui-shadow: 0 1px 2px rgba(16, 24, 40, 0.06), 0 16px 38px rgba(16, 24, 40, 0.055);
}

body {
  background: var(--sfm-ui-bg) !important;
}

