/* Final platform polish: unified SaaS controls, quieter badges, cleaner fields and tables. */
:root {
  --sfm-radius-sm: 10px;
  --sfm-radius-md: 14px;
  --sfm-radius-lg: 18px;
  --sfm-border-soft: #d7e3ea;
  --sfm-border-strong: #b9ccd6;
  --sfm-surface: #ffffff;
  --sfm-surface-muted: #f7fafc;
  --sfm-text: #102333;
  --sfm-muted: #607486;
  --sfm-accent: #0f7480;
  --sfm-accent-strong: #0b5f6a;
  --sfm-danger: #b94444;
  --sfm-warning: #a46a12;
  --sfm-success: #20744a;
  --sfm-focus-ring: 0 0 0 4px rgba(15, 116, 128, 0.14);
  --sfm-shadow-control: 0 8px 18px rgba(16, 35, 51, 0.06);
  --sfm-shadow-panel: 0 16px 36px rgba(16, 35, 51, 0.08);
}

#appView {
  color: var(--sfm-text);
}

#appView :where(button, input, select, textarea) {
  font: inherit;
}

#appView :where(.primary-button, .quiet-button, .danger-button, button.primary-button) {
  min-height: 40px;
  border-radius: var(--sfm-radius-sm);
  padding: 0 18px;
  font-size: 0.9rem;
  font-weight: 750;
  letter-spacing: 0;
  line-height: 1.15;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  white-space: nowrap;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 160ms ease, border-color 160ms ease, color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

#appView :where(.primary-button, button.primary-button) {
  border: 1px solid var(--sfm-accent);
  background: var(--sfm-accent);
  color: #fff;
  box-shadow: 0 10px 20px rgba(15, 116, 128, 0.14);
}

#appView :where(.primary-button:hover, button.primary-button:hover) {
  border-color: var(--sfm-accent-strong);
  background: var(--sfm-accent-strong);
  transform: translateY(-1px);
  box-shadow: 0 12px 24px rgba(15, 116, 128, 0.18);
}

#appView .quiet-button {
  border: 1px solid var(--sfm-border-soft);
  background: #fff;
  color: var(--sfm-text);
  box-shadow: 0 1px 2px rgba(16, 35, 51, 0.03);
}

#appView .quiet-button:hover {
  border-color: var(--sfm-border-strong);
  background: var(--sfm-surface-muted);
  transform: translateY(-1px);
  box-shadow: var(--sfm-shadow-control);
}

#appView .danger-button {
  border: 1px solid rgba(185, 68, 68, 0.32);
  background: #fff;
  color: var(--sfm-danger);
}

#appView .danger-button:hover {
  border-color: rgba(185, 68, 68, 0.52);
  background: #fff7f7;
  transform: translateY(-1px);
}

#appView :where(.primary-button, .quiet-button, .danger-button, button):focus-visible,
#appView :where(input, select, textarea):focus-visible {
  outline: none;
  box-shadow: var(--sfm-focus-ring);
}

#appView :where(.primary-button, .quiet-button, .danger-button, button):disabled {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

#appView :where(.tag, .badge, .status-pill, .scope-badge, .template-status-pill) {
  min-height: 24px;
  border-radius: 999px;
  padding: 4px 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: fit-content;
  max-width: 100%;
  font-size: 0.74rem;
  font-weight: 750;
  line-height: 1.1;
  letter-spacing: 0;
  white-space: normal;
  overflow-wrap: anywhere;
  border: 1px solid #dce8ee;
  background: #f5f8fa;
  color: #516779;
}

#appView :where(.tag.must, .badge.must, .status-pill.blocked, .status-pill.abgelehnt, .status-pill.nacharbeit_noetig) {
  border-color: #f0c7c3;
