}

#appView :where(.tag.practice, .badge.practice, .status-pill.freigegeben, .tag.approved, .tag.ready, .template-status-pill.done) {
  border-color: #c3e4d1;
  background: #f0fbf5;
  color: #20744a;
}

#appView :where(.tag.auditrelevant, .badge.auditrelevant, .status-pill.auditrelevant) {
  border-color: #b9dfe6;
  background: #eefbfe;
  color: #0f6670;
}

#appView :where(input, select, textarea) {
  border: 1px solid var(--sfm-border-soft);
  border-radius: var(--sfm-radius-sm);
  background: #fff;
  color: var(--sfm-text);
  box-shadow: inset 0 1px 0 rgba(16, 35, 51, 0.02);
  transition: border-color 160ms ease, box-shadow 160ms ease, background-color 160ms ease;
}

#appView :where(input, select) {
  min-height: 42px;
  padding: 0 13px;
}

#appView textarea {
  min-height: 104px;
  padding: 12px 13px;
  resize: vertical;
}

#appView :where(input:hover, select:hover, textarea:hover) {
  border-color: var(--sfm-border-strong);
}

