/* Executive cockpit: calm add-on view for management, not an operational BI suite. */
.executive-page {
  display: grid;
  gap: 18px;
  width: min(100%, 1480px);
  margin: 0 auto;
}

.executive-page-hero,
.executive-page-panel,
.executive-page-actions {
  min-width: 0;
  border: 1px solid #dde6ed;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 18px 48px rgba(15, 23, 42, 0.055);
}

.executive-page-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 0.42fr);
  gap: 24px;
  align-items: start;
  padding: 26px;
}

.executive-page-hero h3 {
  margin: 4px 0 10px;
  color: #0f1f2b;
  font-size: clamp(28px, 2.5vw, 42px);
  font-weight: 780;
  line-height: 1.08;
}

.executive-page-hero p,
.executive-page-note,
.executive-page-subtle {
  margin: 0;
  color: #607180;
  line-height: 1.55;
}

.executive-page-note {
  padding: 16px;
  border: 1px solid #dce8ee;
  border-radius: 14px;
  background: #f8fbfc;
  font-size: 14px;
}

.executive-page-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}

.executive-page-kpi {
  display: grid;
  gap: 9px;
  min-width: 0;
  min-height: 132px;
  padding: 18px;
  border: 1px solid #dde6ed;
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 14px 36px rgba(15, 23, 42, 0.045);
}

.executive-page-kpi span,
.executive-page-panel .eyebrow {
  color: #667887;
  font-size: 11px;
  font-weight: 760;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.executive-page-kpi strong {
  color: #0e1c27;
  font-size: clamp(24px, 2vw, 32px);
  font-weight: 780;
  line-height: 1.05;
}

.executive-page-kpi small {
  color: #607180;
  font-weight: 650;
  line-height: 1.38;
}

.executive-page-kpi.warning {
  border-color: #ead9ba;
}

.executive-page-kpi.critical {
  border-color: #ebc9c4;
}

.executive-page-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(360px, 0.85fr);
  gap: 18px;
  align-items: start;
}

.executive-page-panel {
  display: grid;
  gap: 14px;
  padding: 20px;
}

.executive-page-panel-head {
  display: flex;
  gap: 16px;
  justify-content: space-between;
  align-items: start;
}

.executive-page-panel-head h3 {
  margin: 4px 0 0;
  color: #0e1c27;
  font-size: 20px;
  font-weight: 760;
}

.executive-risk-list,
.executive-decision-list {
  display: grid;
  gap: 10px;
}

.executive-risk-item,
.executive-track-card,
.executive-deadline-card button {
  display: grid;
  gap: 10px;
  width: 100%;
  min-width: 0;
  padding: 14px;
  border: 1px solid #e1e9ef;
  border-radius: 13px;
  background: #fbfcfd;
  color: #0e1c27;
  text-align: left;
}

.executive-risk-item {
  grid-template-columns: minmax(0, 1fr) minmax(180px, 0.35fr);
  align-items: center;
}

.executive-risk-item:hover,
.executive-track-card:hover,
.executive-deadline-card button:hover {
  border-color: #cbd8e1;
  background: #ffffff;
}

.executive-risk-item.warning,
.executive-track-card.warning {
  border-left: 4px solid #d19a45;
}

.executive-risk-item.critical,
.executive-track-card.critical {
  border-left: 4px solid #c4514a;
}

.executive-risk-item.active,
.executive-track-card.active {
  border-left: 4px solid #5aa8b3;
}

.executive-risk-item span,
.executive-deadline-card button span {
  color: #687987;
  font-size: 12px;
  font-weight: 680;
}

.executive-risk-item strong,
.executive-decision-item strong,
.executive-track-card strong,
.executive-deadline-card b {
  color: #0e1c27;
  font-size: 15px;
  font-weight: 730;
  line-height: 1.32;
  overflow-wrap: anywhere;
}

.executive-risk-item small,
.executive-decision-item p,
.executive-decision-item small,
.executive-track-card span,
.executive-track-footer small,
.executive-deadline-card small {
  color: #607180;
  line-height: 1.45;
  overflow-wrap: anywhere;
}

.executive-risk-meta {
  display: grid;
  gap: 6px;
  justify-items: end;
  text-align: right;
}

.executive-decision-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  min-width: 0;
  padding: 14px;
  border: 1px solid #e1e9ef;
  border-radius: 13px;
  background: #fbfcfd;
}

.executive-decision-item p {
  margin: 6px 0;
}

.executive-decision-item > div:last-child {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.executive-track-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 12px;
}

.executive-track-card {
  align-content: space-between;
  min-height: 186px;
}

.executive-track-footer {
  display: grid;
  gap: 8px;
}

.executive-deadline-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.executive-deadline-card {
  display: grid;
  gap: 10px;
  min-width: 0;
  padding: 14px;
  border: 1px solid #e1e9ef;
  border-radius: 14px;
  background: #fbfcfd;
}

.executive-deadline-card > strong {
  color: #0e1c27;
  font-size: 16px;
}

.executive-deadline-card button {
  background: #ffffff;
}

.executive-page-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  padding: 20px;
}

.executive-page-actions strong {
  color: #0e1c27;
  font-size: 18px;
}

.executive-page-actions p {
  margin: 6px 0 0;
  color: #607180;
  line-height: 1.5;
}

.executive-page-actions > div:last-child {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

@media (min-width: 1680px) {
  .executive-page {
    width: min(100%, 1640px);
  }
}

@media (max-width: 1280px) {
  .executive-page-kpis,
  .executive-track-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .executive-page-grid,
  .executive-page-hero,
  .executive-page-actions {
    grid-template-columns: 1fr;
  }

  .executive-page-actions > div:last-child {
    justify-content: flex-start;
  }
}

@media (max-width: 760px) {
  .executive-page {
    gap: 14px;
  }

  .executive-page-hero,
  .executive-page-panel,
  .executive-page-actions {
    padding: 16px;
  }

  .executive-page-kpis,
  .executive-track-grid,
  .executive-deadline-grid,
  .executive-risk-item,
  .executive-decision-item {
    grid-template-columns: 1fr;
  }

  .executive-risk-meta,
  .executive-decision-item > div:last-child {
    justify-items: start;
    justify-content: flex-start;
    text-align: left;
  }
}

@media (max-width: 860px) {
  .sidebar {
    width: 100% !important;
    min-width: 0 !important;
    padding: 18px !important;
    border-right: 0 !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.12) !important;
  }

  .brand {
    grid-template-columns: 46px minmax(0, 1fr) !important;
  }

  .brand-mark {
    width: 46px !important;
    height: 46px !important;
  }
}

