/* Enterprise SaaS redesign pass: calm hierarchy, less badge noise, consistent surfaces. */
:root {
  --bg: #f6f8fa;
  --surface: #ffffff;
  --surface-soft: #f8fafc;
  --surface-warm: #fffaf2;
  --line: #dfe6ee;
  --line-strong: #cbd6e2;
  --text: #111c27;
  --muted: #5f7080;
  --accent: #176f7b;
  --accent-dark: #0f5661;
  --gold: #b7791f;
  --green: #287a4d;
  --blue: #315f86;
  --danger: #b0473f;
  --shadow: 0 10px 30px rgba(15, 23, 42, 0.055);
  --shadow-soft: 0 4px 18px rgba(15, 23, 42, 0.045);
  --radius: 12px;
  --sfm-space-page: clamp(22px, 2vw, 40px);
  --sfm-space-panel: clamp(18px, 1.4vw, 26px);
}

html,
body {
  background: var(--bg) !important;
}

body {
  color: var(--text) !important;
  font-size: 14px !important;
  line-height: 1.5 !important;
}

.app-shell {
  grid-template-columns: 276px minmax(0, 1fr) !important;
  background: var(--bg) !important;
}

.sidebar {
  width: 276px !important;
  gap: 18px !important;
  padding: 22px 18px !important;
  background: #0c2b35 !important;
  border-right: 1px solid rgba(255, 255, 255, 0.08) !important;
  box-shadow: none !important;
}

.brand {
  grid-template-columns: 42px minmax(0, 1fr) !important;
  gap: 12px !important;
  padding-bottom: 16px !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12) !important;
}

.brand-mark {
  width: 42px !important;
