/* Live workspace synchronization */
.top-status-chip.live {
  gap: 7px;
  color: #245b48;
  background: #f4faf7;
  border-color: #cfe5da;
}

.top-status-chip.live::before {
  content: "";
  width: 7px;
  height: 7px;
  flex: 0 0 7px;
  border-radius: 50%;
  background: #2f9d68;
  box-shadow: 0 0 0 3px rgba(47, 157, 104, 0.12);
}

.top-status-chip.live.connecting::before,
.top-status-chip.live.retrying::before {
  background: #d68a1d;
  box-shadow: 0 0 0 3px rgba(214, 138, 29, 0.12);
}

.top-status-chip.live.offline::before,
.top-status-chip.live.fallback::before,
.top-status-chip.live.idle::before {
  background: #82919c;
  box-shadow: none;
}

.account-access-notice {
  display: grid;
  gap: 5px;
  margin-top: 14px;
