/* Corrective action and CAPA workspace */
.capa-workspace {
  display: grid;
  gap: 16px;
  min-width: 0;
}

.capa-overview {
  display: grid;
  grid-template-columns: minmax(280px, 0.85fr) minmax(560px, 1.5fr);
  gap: 24px;
  align-items: stretch;
}

.capa-overview-copy,
.capa-content-grid > *,
.capa-kpis,
.capa-kpi,
.capa-register-row > span,
.capa-detail-form label {
  min-width: 0;
}

.capa-overview-copy h2 {
  margin: 6px 0 8px;
  font-size: 1.45rem;
  line-height: 1.25;
}

.capa-overview-copy p,
.capa-workflow p,
.capa-detail-head p,
.capa-detail-form small,
.capa-create-action small {
  color: var(--muted);
  line-height: 1.5;
}

.capa-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(128px, 1fr));
  gap: 10px;
}

.capa-kpi {
  display: flex;
  min-height: 118px;
  padding: 16px;
  flex-direction: column;
  justify-content: center;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface, #fff);
}

.capa-kpi.warning {
  border-color: #ead4a9;
  background: #fffaf1;
}

.capa-kpi.done {
  border-color: #cfe4d8;
  background: #f7fbf8;
}

.capa-kpi strong {
  color: var(--ink);
  font-size: 1.75rem;
  line-height: 1;
}

.capa-kpi span {
  margin-top: 10px;
  font-weight: 700;
}

.capa-kpi small {
  margin-top: 4px;
  color: var(--muted);
}

.capa-workflow-panel .section-heading,
.capa-create-panel .section-heading,
.capa-register-panel .section-heading {
  margin-bottom: 14px;
}

.capa-workflow {
  display: grid;
  grid-template-columns: repeat(5, minmax(150px, 1fr));
  gap: 10px;
}

.capa-workflow article {
  display: flex;
  gap: 10px;
  min-height: 92px;
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
}

.capa-workflow article > span {
  display: grid;
  flex: 0 0 32px;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 7px;
  background: #e8f5f6;
  color: #087786;
  font-size: 0.76rem;
  font-weight: 800;
}

.capa-workflow strong {
  display: block;
  margin-bottom: 4px;
}

.capa-workflow p {
  margin: 0;
  font-size: 0.82rem;
}

.capa-create-form {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 12px;
  align-items: end;
}

.capa-create-form label {
  grid-column: span 2;
  min-width: 0;
}

.capa-create-form label:first-child,
.capa-create-form .capa-title-field {
  grid-column: span 3;
}

.capa-create-form .capa-wide-field {
  grid-column: span 9;
}

.capa-create-form textarea {
  min-height: 84px;
}

.capa-create-action {
  display: flex;
  grid-column: span 3;
  min-width: 0;
  flex-direction: column;
  gap: 7px;
}

.capa-content-grid {
  display: grid;
  grid-template-columns: minmax(440px, 0.9fr) minmax(560px, 1.1fr);
  gap: 16px;
  align-items: start;
  min-width: 0;
}

.capa-register-list {
  display: grid;
  gap: 8px;
}

.capa-register-row {
  display: grid;
  width: 100%;
  grid-template-columns: minmax(190px, 1.65fr) minmax(120px, 0.9fr) minmax(104px, 0.7fr) auto;
  gap: 14px;
  align-items: center;
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
}

.capa-register-row:hover,
.capa-register-row.active {
  border-color: #75bec8;
  background: #f4fbfc;
}

.capa-register-row.active {
  box-shadow: inset 3px 0 0 #168795;
}

.capa-register-row strong,
.capa-register-row small {
  display: block;
  overflow-wrap: anywhere;
}

.capa-register-row small {
  margin-top: 3px;
  color: var(--muted);
  line-height: 1.35;
}

.capa-row-main strong {
  font-size: 0.96rem;
}

.capa-detail-panel {
  position: sticky;
  top: 16px;
}

.capa-detail-head {
  display: flex;
  gap: 16px;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--border);
}

.capa-detail-head h3 {
  margin: 5px 0 5px;
  font-size: 1.2rem;
}

.capa-detail-head p {
  margin: 0;
}

.capa-detail-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.capa-detail-form label {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.capa-detail-form label > span,
.capa-create-form label > span {
  color: var(--muted-strong, #516375);
  font-size: 0.72rem;
  font-weight: 800;
  text-transform: uppercase;
}

.capa-detail-form .capa-form-wide,
.capa-customer-review-note,
.capa-detail-actions,
.capa-history {
  grid-column: 1 / -1;
}

.capa-detail-form textarea {
  min-height: 88px;
  resize: vertical;
}

.capa-detail-form .capa-form-wide textarea {
  min-height: 104px;
}

.capa-audit-toggle {
  display: flex !important;
  min-height: 44px;
  padding: 10px 12px;
  flex-direction: row !important;
  align-items: center;
  border: 1px solid var(--border);
  border-radius: 8px;
}

.capa-audit-toggle input {
  width: 18px;
  height: 18px;
}

.capa-customer-review-note {
  display: flex;
  padding: 12px 14px;
  flex-direction: column;
  gap: 3px;
  border: 1px solid #cfe4e8;
  border-radius: 8px;
  background: #f4fafb;
}

.capa-detail-actions {
  display: flex;
  gap: 8px;
  align-items: center;
  justify-content: flex-end;
  padding-top: 4px;
}

.capa-execution {
  display: grid;
  gap: 14px;
  margin-top: 18px;
  padding-top: 18px;
  border-top: 1px solid var(--border);
}

.capa-execution-head {
  display: flex;
  gap: 18px;
  align-items: flex-start;
  justify-content: space-between;
}

.capa-execution-head > div,
.capa-execution-columns > *,
.capa-execution-row span {
  min-width: 0;
}

.capa-execution-head h4 {
  margin: 5px 0 4px;
  color: var(--ink);
  font-size: 1rem;
}

.capa-execution-head p {
  max-width: 680px;
  margin: 0;
  color: var(--muted);
  line-height: 1.45;
}

.capa-execution-summary {
  display: flex;
  flex: 0 0 auto;
  gap: 6px;
  align-items: center;
}

.capa-execution-summary span {
  padding: 7px 9px;
  border: 1px solid var(--border);
  border-radius: 7px;
  color: var(--muted);
  background: #fff;
  white-space: nowrap;
}

.capa-execution-summary strong {
  color: var(--ink);
}

.capa-execution-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.capa-effectiveness-gate {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(220px, 0.8fr);
  gap: 12px;
  align-items: start;
  padding: 13px 14px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #f8fbfc;
}

.capa-effectiveness-gate.done {
  border-color: #b9dfce;
  background: #f3fbf7;
}

.capa-effectiveness-gate.ready {
  border-color: #f2d39b;
  background: #fffaf0;
}

.capa-effectiveness-gate.warning {
  border-color: #ead2a1;
  background: #fff8e8;
}

.capa-effectiveness-gate strong,
.capa-effectiveness-gate span {
  display: block;
}

.capa-effectiveness-gate strong {
  color: var(--ink);
}

.capa-effectiveness-gate span {
  margin-top: 4px;
  color: var(--muted);
  line-height: 1.45;
}

.capa-effectiveness-gate ul {
  margin: 0;
  padding-left: 18px;
  color: var(--ink);
  line-height: 1.45;
}

.capa-execution-columns {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.capa-execution-group {
  display: grid;
  align-content: start;
  gap: 7px;
}

.capa-execution-group > strong {
  color: var(--muted-strong, #516375);
  font-size: 0.76rem;
  text-transform: uppercase;
}

.capa-execution-row {
  display: flex;
  width: 100%;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
  padding: 10px 11px;
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--ink);
  background: #fff;
  text-align: left;
  cursor: pointer;
}

.capa-execution-row:hover {
  border-color: #75bec8;
  background: #f7fbfc;
}

.capa-execution-row b,
.capa-execution-row small {
  display: block;
  overflow-wrap: anywhere;
}

.capa-execution-row small {
  margin-top: 3px;
  color: var(--muted);
  line-height: 1.35;
}

.capa-execution-empty {
  display: flex;
  min-height: 72px;
  padding: 12px;
  flex-direction: column;
  justify-content: center;
  gap: 3px;
  border: 1px dashed var(--border-strong, #bdcbd3);
  border-radius: 8px;
  color: var(--muted);
  background: #fbfcfd;
}

.capa-execution-empty strong {
  color: var(--ink);
}

.capa-history {
  margin-top: 4px;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
}

.capa-history summary {
  cursor: pointer;
  font-weight: 700;
}

.capa-history p {
  display: flex;
  margin: 10px 0 0;
  justify-content: space-between;
  gap: 12px;
}

.capa-history p span {
  color: var(--muted);
}

@media (max-width: 1380px) {
  .capa-overview,
  .capa-content-grid {
    grid-template-columns: 1fr;
  }

  .capa-detail-panel {
    position: static;
  }

  .capa-create-form label,
  .capa-create-form label:first-child,
  .capa-create-form .capa-title-field {
    grid-column: span 4;
  }

  .capa-create-form .capa-wide-field {
    grid-column: span 8;
  }

  .capa-create-action {
    grid-column: span 4;
  }
}

@media (max-width: 980px) {
  .capa-kpis,
  .capa-workflow {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .capa-register-row {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .capa-register-row > span:nth-child(2),
  .capa-register-row > span:nth-child(3) {
    grid-column: 1;
  }

  .capa-register-row > .status-tag {
    grid-column: 2;
    grid-row: 1;
  }
}

@media (max-width: 700px) {
  .capa-kpis,
  .capa-workflow,
  .capa-detail-form {
    grid-template-columns: 1fr;
  }

  .capa-create-form label,
  .capa-create-form label:first-child,
  .capa-create-form .capa-title-field,
  .capa-create-form .capa-wide-field,
  .capa-create-action {
    grid-column: 1 / -1;
  }

  .capa-detail-actions,
  .capa-execution-head,
  .capa-execution-summary,
  .capa-history p {
    align-items: stretch;
    flex-direction: column;
  }

  .capa-execution-columns {
    grid-template-columns: 1fr;
  }

  .capa-effectiveness-gate {
    grid-template-columns: 1fr;
  }

  .capa-execution-actions > button {
    width: 100%;
  }
}

/* Register command layout parity: Legal, Incident and Contract use the same
   spacious workspace model as Asset, Risk and Vendor Management. */
