  padding-inline: clamp(22px, 1.8vw, 38px) !important;
}

#appView[data-view="legal"] > .register-module-workspace,
#appView[data-view="incidents"] > .register-module-workspace,
#appView[data-view="contracts"] > .register-module-workspace {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 360px) !important;
  gap: clamp(18px, 1.6vw, 28px) !important;
  align-items: start !important;
  width: min(100%, 1760px) !important;
  max-width: 1760px !important;
  min-width: 0 !important;
